/**
 * Admin Listings Filters Client Component
 * 
 * Provides real-time search and filter functionality for the admin listings dashboard.
 * Updates URL parameters without full page reload for better UX.
 * 
 * Features:
 * - Real-time search with debouncing
 * - Sort dropdown with instant update
 * - Active filters display
 * - Mobile-responsive design
 * 
 * Requirements: 3.3
 */

'use client';

import { useState, useEffect, useCallback } from 'react';
import { useRouter, useSearchParams } from 'next/navigation';
import { Search, Filter, X } from 'lucide-react';

interface ListingsFiltersProps {
  totalPending: number;
  filteredCount: number;
}

/**
 * Debounce hook for search input
 */
function useDebounce<T>(value: T, delay: number): T {
  const [debouncedValue, setDebouncedValue] = useState<T>(value);

  useEffect(() => {
    const handler = setTimeout(() => {
      setDebouncedValue(value);
    }, delay);

    return () => {
      clearTimeout(handler);
    };
  }, [value, delay]);

  return debouncedValue;
}

/**
 * Admin Listings Filters Component
 * 
 * Client component that provides interactive filtering and search.
 * Updates URL params using Next.js router for shareable filter state.
 */
export function ListingsFilters({
  totalPending,
  filteredCount,
}: ListingsFiltersProps) {
  const router = useRouter();
  const searchParams = useSearchParams();

  // State for controlled inputs
  const [searchQuery, setSearchQuery] = useState(
    searchParams.get('search') || ''
  );
  const [sortOrder, setSortOrder] = useState<'newest' | 'oldest'>(
    (searchParams.get('sort') as 'newest' | 'oldest') || 'newest'
  );

  // Debounce search query for better performance
  const debouncedSearchQuery = useDebounce(searchQuery, 300);

  /**
   * Update URL parameters without page reload
   */
  const updateFilters = useCallback(
    (search: string, sort: 'newest' | 'oldest') => {
      const params = new URLSearchParams();

      if (search.trim()) {
        params.set('search', search.trim());
      }

      if (sort !== 'newest') {
        params.set('sort', sort);
      }

      const queryString = params.toString();
      const url = queryString
        ? `/admin/listings?${queryString}`
        : '/admin/listings';

      router.push(url);
    },
    [router]
  );

  /**
   * Update URL when debounced search query changes
   */
  useEffect(() => {
    if (debouncedSearchQuery !== searchParams.get('search') || '') {
      updateFilters(debouncedSearchQuery, sortOrder);
    }
  }, [debouncedSearchQuery]); // Only depend on debounced query

  /**
   * Handle sort change
   */
  const handleSortChange = (newSort: 'newest' | 'oldest') => {
    setSortOrder(newSort);
    updateFilters(searchQuery, newSort);
  };

  /**
   * Clear all filters
   */
  const clearFilters = () => {
    setSearchQuery('');
    setSortOrder('newest');
    router.push('/admin/listings');
  };

  /**
   * Clear search only
   */
  const clearSearch = () => {
    setSearchQuery('');
    updateFilters('', sortOrder);
  };

  const hasActiveFilters = searchQuery.trim() !== '' || sortOrder !== 'newest';

  return (
    <div className="bg-dark-card border border-dark-border rounded-lg p-4">
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        {/* Search input */}
        <div>
          <label
            htmlFor="search"
            className="block text-sm font-medium text-gray-300 mb-2"
          >
            <Search className="inline h-4 w-4 mr-1" />
            Search by title or user
          </label>
          <div className="relative">
            <input
              type="text"
              id="search"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              placeholder="Type to search..."
              className="w-full bg-dark-bg border border-dark-border rounded-lg px-4 py-2 pr-10 text-white placeholder:text-gray-500 focus:outline-none focus:ring-2 focus:ring-naija-green focus:border-transparent"
              aria-label="Search listings by title or user"
            />
            {searchQuery && (
              <button
                onClick={clearSearch}
                className="absolute right-2 top-1/2 -translate-y-1/2 p-1 hover:bg-dark-bg rounded-full transition-colors"
                aria-label="Clear search"
                title="Clear search"
              >
                <X className="h-4 w-4 text-gray-400 hover:text-white" />
              </button>
            )}
          </div>
        </div>

        {/* Sort dropdown */}
        <div>
          <label
            htmlFor="sort"
            className="block text-sm font-medium text-gray-300 mb-2"
          >
            <Filter className="inline h-4 w-4 mr-1" />
            Sort by date
          </label>
          <select
            id="sort"
            value={sortOrder}
            onChange={(e) =>
              handleSortChange(e.target.value as 'newest' | 'oldest')
            }
            className="w-full bg-dark-bg border border-dark-border rounded-lg px-4 py-2 text-white focus:outline-none focus:ring-2 focus:ring-naija-green focus:border-transparent cursor-pointer"
            aria-label="Sort listings by date"
          >
            <option value="newest">Newest first</option>
            <option value="oldest">Oldest first</option>
          </select>
        </div>
      </div>

      {/* Active filters indicator */}
      {hasActiveFilters && (
        <div className="mt-4 flex items-center gap-2 flex-wrap">
          <span className="text-sm text-gray-400">Active filters:</span>
          {searchQuery.trim() && (
            <span className="inline-flex items-center gap-1 px-3 py-1 bg-naija-green/20 text-naija-green rounded-full text-sm">
              Search: "{searchQuery.trim()}"
              <button
                onClick={clearSearch}
                className="ml-1 hover:text-white transition-colors"
                aria-label="Clear search filter"
                title="Clear search"
              >
                ├ù
              </button>
            </span>
          )}
          {sortOrder !== 'newest' && (
            <span className="inline-flex items-center gap-1 px-3 py-1 bg-naija-green/20 text-naija-green rounded-full text-sm">
              Sort:{' '}
              {sortOrder === 'oldest' ? 'Oldest first' : 'Newest first'}
            </span>
          )}
          <button
            onClick={clearFilters}
            className="text-sm text-naija-green hover:text-naija-green/80 underline transition-colors"
            aria-label="Clear all filters"
          >
            Clear all filters
          </button>
        </div>
      )}

      {/* Results count */}
      {searchQuery.trim() && filteredCount !== totalPending && (
        <div className="mt-4 text-sm text-gray-400">
          Showing {filteredCount} of {totalPending} pending listing
          {totalPending !== 1 ? 's' : ''}
        </div>
      )}
    </div>
  );
}

"use client";

import { useEffect } from "react";
import { AlertTriangle, RefreshCw, Home } from "lucide-react";
import { Button } from "@/components/ui/button";
import Link from "next/link";

export default function AuthError({
  error,
  reset,
}: {
  error: Error & { digest?: string };
  reset: () => void;
}) {
  useEffect(() => {
    console.error("Auth error:", error);

    if (typeof window !== "undefined" && (window as any).__ERROR_TRACKER__) {
      (window as any).__ERROR_TRACKER__.captureException(error);
    }
  }, [error]);

  return (
    <div className="min-h-screen flex items-center justify-center p-4 bg-gradient-to-br from-gray-900 via-black to-gray-900">
      <div className="max-w-md w-full">
        <div className="bg-gray-900/50 backdrop-blur-xl border border-red-500/20 rounded-2xl p-8 shadow-2xl">
          <div className="flex flex-col items-center text-center space-y-6">
            <div className="relative">
              <div className="absolute inset-0 bg-red-500/20 blur-2xl rounded-full" />
              <div className="relative bg-red-500/10 p-4 rounded-full border border-red-500/30">
                <AlertTriangle className="w-12 h-12 text-red-500" />
              </div>
            </div>

            <div className="space-y-2">
              <h2 className="text-2xl font-bold text-white">
                Authentication Error
              </h2>
              <p className="text-gray-400 text-sm">
                We couldn't complete your authentication. Please try again.
              </p>
            </div>

            {process.env.NODE_ENV === "development" && (
              <div className="w-full bg-black/50 rounded-lg p-4 border border-red-500/20">
                <p className="text-xs text-red-400 font-mono break-all">
                  {error.message}
                </p>
              </div>
            )}

            <div className="flex flex-col sm:flex-row gap-3 w-full">
              <Button
                onClick={reset}
                className="flex-1 bg-gradient-to-r from-[#00ff41] to-[#00cc33] hover:from-[#00cc33] hover:to-[#00ff41] text-black font-semibold"
              >
                <RefreshCw className="w-4 h-4 mr-2" />
                Try Again
              </Button>
              <Link href="/" className="flex-1">
                <Button
                  variant="outline"
                  className="w-full border-gray-700 hover:bg-gray-800"
                >
                  <Home className="w-4 h-4 mr-2" />
                  Go Home
                </Button>
              </Link>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

import { redirect } from "next/navigation";
import { Metadata } from "next";
import { ListingForm } from "@/components/features/listing-form";
import { getCategories } from "@/lib/services/database";
import { requireAuth } from "@/lib/services/auth";

/**
 * CreateListing Page - Task 6.9
 * 
 * Server Component that handles:
 * - Authentication guard using requireAuth() (redirects to login if not authenticated)
 * - Fetches categories from database using getCategories() from database service
 * - Defines Nigerian states array directly in code
 * - Renders ListingForm with fetched categories
 * - Provides proper SEO metadata
 * - Applies consistent page layout with container and padding
 * 
 * Requirements: 13.1, 13.16
 */

// ============================================================================
// Nigerian States Array
// ============================================================================

const NIGERIAN_STATES = [
  "Abia",
  "Adamawa",
  "Akwa Ibom",
  "Anambra",
  "Bauchi",
  "Bayelsa",
  "Benue",
  "Borno",
  "Cross River",
  "Delta",
  "Ebonyi",
  "Edo",
  "Ekiti",
  "Enugu",
  "Gombe",
  "Imo",
  "Jigawa",
  "Kaduna",
  "Kano",
  "Katsina",
  "Kebbi",
  "Kogi",
  "Kwara",
  "Lagos",
  "Nasarawa",
  "Niger",
  "Ogun",
  "Ondo",
  "Osun",
  "Oyo",
  "Plateau",
  "Rivers",
  "Sokoto",
  "Taraba",
  "Yobe",
  "Zamfara",
  "FCT",
];

// ============================================================================
// Page Metadata
// ============================================================================

export const metadata: Metadata = {
  title: "Create Listing | FindAm",
  description: "Create a new listing on FindAm. Upload images, add details, and reach customers across Nigeria.",
  robots: {
    index: false, // Don't index authenticated pages
    follow: false,
  },
};

// ============================================================================
// Main Page Component
// ============================================================================

export default async function CreateListingPage() {
  // ========== Authentication Guard ==========
  // Use requireAuth() to ensure user is authenticated
  // This will throw UnauthorizedError if user is not logged in
  try {
    await requireAuth();
  } catch (error) {
    // Redirect to login page with return URL
    redirect("/login?redirect=/listings/create");
  }

  // ========== Fetch Categories ==========
  // Fetch all categories using getCategories() from database service
  const categories = await getCategories();

  // Handle categories fetch error
  if (!categories || categories.length === 0) {
    return (
      <div className="min-h-screen bg-gray-50 dark:bg-gray-900 flex items-center justify-center px-4">
        <div className="max-w-md w-full text-center space-y-4">
          <div className="text-red-600 dark:text-red-400 text-lg font-semibold">
            Unable to Load Categories
          </div>
          <p className="text-gray-600 dark:text-gray-400">
            We couldn&apos;t load the categories. Please check your internet
            connection and try again.
          </p>
          <a
            href="/listings/create"
            className="inline-block px-6 py-3 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
          >
            Try Again
          </a>
        </div>
      </div>
    );
  }

  // ========== Render Form ==========
  return (
    <div className="min-h-screen bg-gray-50 dark:bg-gray-900 py-8">
      <div className="container mx-auto px-4 max-w-4xl">
        {/* Page Header */}
        <div className="mb-8">
          <h1 className="text-3xl md:text-4xl font-bold text-gray-900 dark:text-white mb-2">
            Create New Listing
          </h1>
          <p className="text-gray-600 dark:text-gray-400 text-sm md:text-base">
            Fill in the details below to create your listing. All listings are
            reviewed before going live.
          </p>
        </div>

        {/* Listing Form Component */}
        <div className="bg-white dark:bg-gray-800 rounded-lg shadow-lg p-6 md:p-8">
          <ListingForm categories={categories} />
        </div>
      </div>
    </div>
  );
}

"use client";

// Business Profile page with enhanced features
// Requirements: 21.3, 21.4, 21.5, 21.6

import { useState, useEffect } from "react";
import { useParams } from "next/navigation";
import { motion } from "framer-motion";
import {
  MapPin,
  Phone,
  Mail,
  Globe,
  Star,
  CheckCircle,
  MessageCircle,
  Share2,
  ChevronLeft,
  ExternalLink,
  Building2,
  Shield,
} from "lucide-react";
import Link from "next/link";
import { getBusinessById, getBusinessListings } from "@/lib/services/business";
import { formatNigerianPhone, maskPhoneNumber } from "@/lib/utils/phone";
import numeral from "numeral";
import dynamic from "next/dynamic";
import { ClaimBusinessButton } from "@/components/business/claim-business-button";

const BusinessMap = dynamic(
  () => import("@/components/business/business-map").then((mod) => mod.BusinessMap),
  {
    ssr: false,
    loading: () => (
      <div className="h-80 w-full flex items-center justify-center bg-dark-bg">
        <div className="text-gray-400">Loading map...</div>
      </div>
    ),
  }
);

export default function BusinessProfilePage() {
  const params = useParams();
  const businessId = params.id as string;

  const [business, setBusiness] = useState<any>(null);
  const [listings, setListings] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [showPhone, setShowPhone] = useState(false);
  const [viewMode, setViewMode] = useState<"listings" | "map">("listings");

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [businessData, listingsData] = await Promise.all([
          getBusinessById(businessId),
          getBusinessListings(businessId, 10),
        ]);

        setBusiness(businessData);
        setListings(listingsData);
      } catch (error) {
        console.error("Failed to fetch business data:", error);
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, [businessId]);

  if (loading) {
    return (
      <div className="flex min-h-screen items-center justify-center bg-dark-bg">
        <div className="h-8 w-8 animate-spin rounded-full border-4 border-naija-green border-t-transparent" />
      </div>
    );
  }

  if (!business) {
    return (
      <div className="flex min-h-screen flex-col items-center justify-center bg-dark-bg px-4 text-center">
        <Building2 className="mb-4 h-16 w-16 text-gray-600" />
        <h2 className="mb-2 text-2xl font-bold text-white">Business Not Found</h2>
        <p className="mb-6 text-gray-400">
          The business you&apos;re looking for doesn&apos;t exist or has been removed.
        </p>
        <Link
          href="/businesses"
          className="rounded-lg bg-naija-green px-6 py-3 font-semibold text-white transition-colors hover:bg-naija-green/90"
        >
          Browse Businesses
        </Link>
      </div>
    );
  }

  // Extract coordinates if available
  let coordinates: [number, number] | null = null;
  if (business.coordinates) {
    // PostGIS format: POINT(lng lat)
    const match = business.coordinates.match(/POINT\(([^ ]+) ([^ ]+)\)/);
    if (match) {
      coordinates = [parseFloat(match[1]), parseFloat(match[2])];
    }
  }

  return (
    <div className="min-h-screen bg-dark-bg pb-20">
      {/* Back Button */}
      <div className="border-b border-dark-border bg-dark-card/50 backdrop-blur-md">
        <div className="mx-auto max-w-7xl px-4 py-4">
          <Link
            href="/businesses"
            className="flex items-center gap-2 text-gray-400 transition-colors hover:text-white"
          >
            <ChevronLeft className="h-5 w-5" />
            <span>Back to Directory</span>
          </Link>
        </div>
      </div>

      {/* Cover Image */}
      <div className="relative h-64 overflow-hidden bg-gradient-to-br from-naija-green/20 to-dark-bg">
        {business.cover_url && (
          <img
            src={business.cover_url}
            alt={`${business.name} cover`}
            className="h-full w-full object-cover"
          />
        )}

        {/* Verified Badge */}
        {business.is_verified && (
          <div className="absolute right-6 top-6 flex items-center gap-2 rounded-full bg-naija-green/90 px-4 py-2 font-semibold text-white backdrop-blur-sm">
            <CheckCircle className="h-5 w-5" />
            <span>Verified Business</span>
          </div>
        )}
        
        {/* Claimed Badge */}
        {business.is_claimed && (
          <div className="absolute right-6 top-20 flex items-center gap-2 rounded-full bg-blue-600/90 px-4 py-2 font-semibold text-white backdrop-blur-sm">
            <Shield className="h-5 w-5" />
            <span>Claimed Business</span>
          </div>
        )}
      </div>

      <div className="mx-auto max-w-7xl px-4">
        {/* Logo and Header Info */}
        <div className="relative -mt-16 mb-8 flex flex-col gap-6 sm:flex-row sm:items-end">
          {/* Logo */}
          <div className="h-32 w-32 overflow-hidden rounded-2xl border-4 border-dark-bg bg-dark-card shadow-2xl">
            {business.logo_url ? (
              <img
                src={business.logo_url}
                alt={business.name}
                className="h-full w-full object-cover"
              />
            ) : (
              <div className="flex h-full items-center justify-center bg-gradient-to-br from-naija-green to-naija-orange text-4xl font-bold text-white">
                {business.name.charAt(0).toUpperCase()}
              </div>
            )}
          </div>

          {/* Business Info */}
          <div className="flex-1">
            <h1 className="mb-2 text-3xl font-bold text-white">{business.name}</h1>

            {/* Rating */}
            {business.average_rating && business.review_count ? (
              <div className="mb-3 flex items-center gap-3">
                <div className="flex items-center gap-2">
                  <Star className="h-5 w-5 fill-yellow-400 text-yellow-400" />
                  <span className="text-lg font-semibold text-white">
                    {business.average_rating.toFixed(1)}
                  </span>
                </div>
                <span className="text-sm text-gray-400">
                  ({numeral(business.review_count).format("0,0")} reviews)
                </span>
              </div>
            ) : null}

            {/* Location */}
            <div className="mb-4 flex items-center gap-2 text-gray-400">
              <MapPin className="h-5 w-5" />
              <span>
                {business.ward && `${business.ward}, `}
                {business.lga}, {business.state}
              </span>
            </div>

            {/* Action Buttons */}
            <div className="flex flex-wrap gap-3">
              {/* Claim Business Button */}
              <ClaimBusinessButton
                businessId={business.id}
                businessName={business.name}
                isClaimable={business.is_claimable === true}
                isClaimed={business.is_claimed === true}
              />
              
              <Link
                href={`/messages?business=${business.id}`}
                className="flex items-center gap-2 rounded-lg bg-naija-green px-6 py-3 font-semibold text-white transition-colors hover:bg-naija-green/90"
              >
                <MessageCircle className="h-5 w-5" />
                <span>Message</span>
              </Link>

              <button
                onClick={() => {
                  // Implement share functionality
                  if (navigator.share) {
                    navigator.share({
                      title: business.name,
                      text: business.description || "",
                      url: window.location.href,
                    });
                  }
                }}
                className="flex items-center gap-2 rounded-lg border border-dark-border bg-dark-card px-6 py-3 font-semibold text-white transition-colors hover:bg-dark-border"
              >
                <Share2 className="h-5 w-5" />
                <span>Share</span>
              </button>
            </div>
          </div>
        </div>

        {/* Content Grid */}
        <div className="grid gap-8 lg:grid-cols-3">
          {/* Main Content */}
          <div className="lg:col-span-2 space-y-8">
            {/* Description */}
            <motion.div
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              className="rounded-2xl border border-dark-border bg-dark-card p-6"
            >
              <h2 className="mb-4 text-xl font-bold text-white">About</h2>
              <p className="text-gray-300 leading-relaxed">
                {business.description || "No description provided."}
              </p>
            </motion.div>

            {/* Listings */}
            {listings.length > 0 && (
              <motion.div
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: 0.1 }}
                className="rounded-2xl border border-dark-border bg-dark-card p-6"
              >
                <div className="mb-4 flex items-center justify-between">
                  <h2 className="text-xl font-bold text-white">Listings</h2>
                  <Link
                    href={`/search?business=${business.id}`}
                    className="text-sm text-naija-green hover:underline"
                  >
                    View All
                  </Link>
                </div>

                <div className="grid gap-4 sm:grid-cols-2">
                  {listings.map((listing) => (
                    <Link
                      key={listing.id}
                      href={`/listing/${listing.id}`}
                      className="group overflow-hidden rounded-lg border border-dark-border bg-dark-bg transition-colors hover:border-naija-green/50"
                    >
                      {listing.thumbnail_url && (
                        <div className="aspect-video overflow-hidden">
                          <img
                            src={listing.thumbnail_url}
                            alt={listing.title}
                            className="h-full w-full object-cover transition-transform group-hover:scale-110"
                          />
                        </div>
                      )}
                      <div className="p-3">
                        <h3 className="mb-1 font-semibold text-white line-clamp-1">
                          {listing.title}
                        </h3>
                        <p className="font-mono text-naija-green">
                          Γéª{numeral(listing.price).format("0,0")}
                        </p>
                      </div>
                    </Link>
                  ))}
                </div>
              </motion.div>
            )}

            {/* Map View */}
            {coordinates && (
              <motion.div
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: 0.2 }}
                className="rounded-2xl border border-dark-border bg-dark-card overflow-hidden"
              >
                <div className="p-4 border-b border-dark-border">
                  <h2 className="text-xl font-bold text-white">Location</h2>
                </div>
                <div className="h-80 w-full">
                  <BusinessMap coordinates={coordinates} businessName={business.name} />
                </div>
              </motion.div>
            )}
          </div>

          {/* Sidebar */}
          <div className="space-y-6">
            {/* Contact Information */}
            <motion.div
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: 0.1 }}
              className="rounded-2xl border border-dark-border bg-dark-card p-6"
            >
              <h2 className="mb-4 text-lg font-bold text-white">Contact Information</h2>

              <div className="space-y-4">
                {/* Phone */}
                <div className="flex items-start gap-3">
                  <Phone className="h-5 w-5 text-naija-green" />
                  <div className="flex-1">
                    <p className="text-sm font-medium text-gray-400">Phone</p>
                    {showPhone ? (
                      <p className="text-white">
                        {formatNigerianPhone(business.phone)}
                      </p>
                    ) : (
                      <button
                        onClick={() => setShowPhone(true)}
                        className="text-naija-green hover:underline"
                      >
                        {maskPhoneNumber(business.phone)} - Click to reveal
                      </button>
                    )}
                  </div>
                </div>

                {/* Email */}
                {business.email && (
                  <div className="flex items-start gap-3">
                    <Mail className="h-5 w-5 text-naija-green" />
                    <div className="flex-1">
                      <p className="text-sm font-medium text-gray-400">Email</p>
                      <a
                        href={`mailto:${business.email}`}
                        className="text-white hover:text-naija-green"
                      >
                        {business.email}
                      </a>
                    </div>
                  </div>
                )}

                {/* Website */}
                {business.website && (
                  <div className="flex items-start gap-3">
                    <Globe className="h-5 w-5 text-naija-green" />
                    <div className="flex-1">
                      <p className="text-sm font-medium text-gray-400">Website</p>
                      <a
                        href={business.website}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="flex items-center gap-1 text-white hover:text-naija-green"
                      >
                        <span>Visit Website</span>
                        <ExternalLink className="h-3.5 w-3.5" />
                      </a>
                    </div>
                  </div>
                )}

                {/* WhatsApp */}
                {business.whatsapp && (
                  <div className="flex items-start gap-3">
                    <MessageCircle className="h-5 w-5 text-naija-green" />
                    <div className="flex-1">
                      <p className="text-sm font-medium text-gray-400">WhatsApp</p>
                      <a
                        href={`https://wa.me/${business.whatsapp.replace(/\D/g, "")}`}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="text-white hover:text-naija-green"
                      >
                        {formatNigerianPhone(business.whatsapp)}
                      </a>
                    </div>
                  </div>
                )}
              </div>
            </motion.div>

            {/* Business Hours */}
            {business.business_hours && (
              <motion.div
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: 0.2 }}
                className="rounded-2xl border border-dark-border bg-dark-card p-6"
              >
                <h2 className="mb-4 text-lg font-bold text-white">Business Hours</h2>
                <div className="space-y-2 text-sm">
                  {Object.entries(business.business_hours).map(([day, hours]: [string, any]) => (
                    <div key={day} className="flex justify-between">
                      <span className="capitalize text-gray-400">{day}</span>
                      <span className="font-medium text-white">
                        {hours.open} - {hours.close}
                      </span>
                    </div>
                  ))}
                </div>
              </motion.div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

// Business Directory page with filtering
// Requirements: 21.3, 21.4, 21.6

import { useState, useEffect } from "react";
import { BusinessCard } from "@/components/business/BusinessCard";
import { getBusinesses } from "@/lib/services/business";
import { createClient } from "@/lib/supabase/client";
import { motion } from "framer-motion";
import {
  Search,
  MapPin,
  Filter,
  Loader2,
  Building2,
  CheckCircle,
} from "lucide-react";
import { states } from "nigeria-states-lgas";

export default function BusinessDirectoryPage() {
  const [businesses, setBusinesses] = useState<any[]>([]);
  const [categories, setCategories] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState("");
  const [selectedCategory, setSelectedCategory] = useState<string>("");
  const [selectedState, setSelectedState] = useState<string>("");
  const [selectedLGA, setSelectedLGA] = useState<string>("");
  const [verifiedOnly, setVerifiedOnly] = useState(false);

  // Fetch categories on mount
  useEffect(() => {
    const fetchCategories = async () => {
      const supabase = createClient();
      const { data } = await supabase
        .from("categories")
        .select("id, name, icon")
        .order("display_order");

      if (data) {
        setCategories(data);
      }
    };

    fetchCategories();
  }, []);

  // Fetch businesses based on filters
  useEffect(() => {
    const fetchBusinesses = async () => {
      setLoading(true);
      try {
        const data = await getBusinesses({
          category_id: selectedCategory || undefined,
          state: selectedState || undefined,
          lga: selectedLGA || undefined,
          is_verified: verifiedOnly ? true : undefined,
          search: searchQuery || undefined,
          limit: 50,
        });

        setBusinesses(data);
      } catch (error) {
        console.error("Failed to fetch businesses:", error);
      } finally {
        setLoading(false);
      }
    };

    fetchBusinesses();
  }, [searchQuery, selectedCategory, selectedState, selectedLGA, verifiedOnly]);

  // Get LGAs for selected state
  const selectedStateData = Array.isArray(states) 
    ? states.find((s) => s.name === selectedState)
    : null;
  const lgas = selectedStateData?.lgas || [];

  return (
    <div className="min-h-screen bg-dark-bg pb-20">
      {/* Header */}
      <div className="border-b border-dark-border bg-dark-card/50 backdrop-blur-md">
        <div className="mx-auto max-w-7xl px-4 py-6">
          <div className="flex items-center gap-3">
            <div className="flex h-12 w-12 items-center justify-center rounded-xl bg-naija-green/20">
              <Building2 className="h-6 w-6 text-naija-green" />
            </div>
            <div>
              <h1 className="text-2xl font-bold text-white">
                Business Directory
              </h1>
              <p className="text-sm text-gray-400">
                Discover verified businesses across Nigeria
              </p>
            </div>
          </div>
        </div>
      </div>

      <div className="mx-auto max-w-7xl px-4 py-8">
        {/* Filters */}
        <div className="mb-8 space-y-4">
          {/* Search Bar */}
          <div className="relative">
            <Search className="absolute left-4 top-1/2 h-5 w-5 -translate-y-1/2 text-gray-400" />
            <input
              type="text"
              placeholder="Search businesses..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full rounded-xl border border-dark-border bg-dark-card py-3 pl-12 pr-4 text-white placeholder-gray-500 focus:border-naija-green focus:outline-none"
            />
          </div>

          {/* Filter Row */}
          <div className="flex flex-wrap items-center gap-3">
            <div className="flex items-center gap-2 text-gray-400">
              <Filter className="h-4 w-4" />
              <span className="text-sm font-medium">Filters:</span>
            </div>

            {/* Category Filter */}
            <select
              value={selectedCategory}
              onChange={(e) => setSelectedCategory(e.target.value)}
              className="rounded-lg border border-dark-border bg-dark-card px-4 py-2 text-sm text-white focus:border-naija-green focus:outline-none"
            >
              <option value="">All Categories</option>
              {categories.map((category) => (
                <option key={category.id} value={category.id}>
                  {category.name}
                </option>
              ))}
            </select>

            {/* State Filter */}
            <select
              value={selectedState}
              onChange={(e) => {
                setSelectedState(e.target.value);
                setSelectedLGA(""); // Reset LGA when state changes
              }}
              className="rounded-lg border border-dark-border bg-dark-card px-4 py-2 text-sm text-white focus:border-naija-green focus:outline-none"
            >
              <option value="">All States</option>
              {Array.isArray(states) && states.map((state) => (
                <option key={state.name} value={state.name}>
                  {state.name}
                </option>
              ))}
            </select>

            {/* LGA Filter */}
            {selectedState && (
              <select
                value={selectedLGA}
                onChange={(e) => setSelectedLGA(e.target.value)}
                className="rounded-lg border border-dark-border bg-dark-card px-4 py-2 text-sm text-white focus:border-naija-green focus:outline-none"
              >
                <option value="">All LGAs</option>
                {lgas.map((lga) => (
                  <option key={lga.name} value={lga.name}>
                    {lga.name}
                  </option>
                ))}
              </select>
            )}

            {/* Verified Only Toggle */}
            <button
              onClick={() => setVerifiedOnly(!verifiedOnly)}
              className={`flex items-center gap-2 rounded-lg border px-4 py-2 text-sm font-medium transition-colors ${
                verifiedOnly
                  ? "border-naija-green bg-naija-green/20 text-naija-green"
                  : "border-dark-border bg-dark-card text-gray-400 hover:text-white"
              }`}
            >
              <CheckCircle className="h-4 w-4" />
              <span>Verified Only</span>
            </button>

            {/* Clear Filters */}
            {(selectedCategory ||
              selectedState ||
              selectedLGA ||
              verifiedOnly ||
              searchQuery) && (
              <button
                onClick={() => {
                  setSelectedCategory("");
                  setSelectedState("");
                  setSelectedLGA("");
                  setVerifiedOnly(false);
                  setSearchQuery("");
                }}
                className="text-sm text-gray-400 hover:text-white"
              >
                Clear All
              </button>
            )}
          </div>
        </div>

        {/* Results Count */}
        <div className="mb-4 text-sm text-gray-400">
          {loading ? (
            <span>Loading businesses...</span>
          ) : (
            <span>
              Found {businesses.length} business{businesses.length !== 1 ? "es" : ""}
            </span>
          )}
        </div>

        {/* Loading State */}
        {loading && (
          <div className="flex items-center justify-center py-20">
            <Loader2 className="h-8 w-8 animate-spin text-naija-green" />
          </div>
        )}

        {/* Business Grid */}
        {!loading && businesses.length > 0 && (
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            className="grid gap-6 sm:grid-cols-2 lg:grid-cols-3"
          >
            {businesses.map((business, index) => (
              <motion.div
                key={business.id}
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: index * 0.05 }}
              >
                <BusinessCard business={business} />
              </motion.div>
            ))}
          </motion.div>
        )}

        {/* Empty State */}
        {!loading && businesses.length === 0 && (
          <div className="flex flex-col items-center justify-center py-20 text-center">
            <div className="mb-4 flex h-20 w-20 items-center justify-center rounded-full bg-dark-card">
              <Building2 className="h-10 w-10 text-gray-600" />
            </div>
            <h3 className="mb-2 text-xl font-semibold text-white">
              No businesses found
            </h3>
            <p className="max-w-md text-sm text-gray-400">
              Try adjusting your filters or search query to find what you're looking for.
            </p>
          </div>
        )}
      </div>
    </div>
  );
}

"use client";

/**
 * Live Stream Viewer Client Component
 *
 * Main component for viewing live streams with all interactive features.
 */

import { useState, useEffect } from "react";
import { useRouter } from "next/navigation";
import {
  LiveStreamPlayer,
  LiveChatPanel,
  ProductPins,
  LiveStreamControls,
  PurchaseModal,
} from "@/components/live";
import { ArrowLeft, Users } from "lucide-react";
import type { LiveSession } from "@/lib/types";

interface LiveStreamViewerProps {
  session: LiveSession;
  seller: {
    username: string;
    avatar_url: string | null;
    trust_score: number;
  };
  currentUserId?: string;
  isHost: boolean;
}

export function LiveStreamViewer({
  session,
  seller,
  currentUserId,
  isHost,
}: LiveStreamViewerProps) {
  const router = useRouter();
  const [viewerCount, setViewerCount] = useState(session.viewer_count);
  const [duration, setDuration] = useState(0);
  const [selectedProductId, setSelectedProductId] = useState<string | null>(
    null,
  );
  const [showPurchaseModal, setShowPurchaseModal] = useState(false);

  const isLive = session.stream_status === "live";
  const streamUrl = isLive
    ? session.stream_url || ""
    : session.recording_url || "";

  // Calculate duration
  useEffect(() => {
    if (!session.started_at) return;

    const updateDuration = () => {
      const startedAt = new Date(session.started_at!);
      const now = new Date();
      const minutes = Math.floor(
        (now.getTime() - startedAt.getTime()) / (1000 * 60),
      );
      setDuration(minutes);
    };

    updateDuration();
    const interval = setInterval(updateDuration, 60000); // Update every minute

    return () => clearInterval(interval);
  }, [session.started_at]);

  // Handle end stream
  const handleEndStream = async () => {
    try {
      const response = await fetch(`/api/live-sessions/${session.id}/end`, {
        method: "POST",
      });

      if (!response.ok) {
        throw new Error("Failed to end stream");
      }

      router.push("/analytics");
    } catch (error) {
      console.error("Error ending stream:", error);
      alert("Failed to end stream. Please try again.");
    }
  };

  // Handle pin product
  const handlePinProduct = () => {
    // Navigate to product selection page or open modal
    router.push(`/live/${session.id}/pin-product`);
  };

  // Handle purchase
  const handlePurchase = (listingId: string) => {
    setSelectedProductId(listingId);
    setShowPurchaseModal(true);
  };

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-gray-950">
      {/* Header */}
      <header className="sticky top-0 z-10 bg-white dark:bg-gray-900 border-b border-gray-200 dark:border-gray-800">
        <div className="max-w-7xl mx-auto px-4 py-3 flex items-center justify-between">
          <button
            onClick={() => router.back()}
            className="flex items-center gap-2 text-gray-600 dark:text-gray-400 hover:text-gray-900 dark:hover:text-white transition-colors"
          >
            <ArrowLeft className="w-5 h-5" />
            <span className="hidden sm:inline">Back</span>
          </button>

          <div className="flex items-center gap-3">
            {seller.avatar_url ? (
              <img
                src={seller.avatar_url}
                alt={seller.username}
                className="w-10 h-10 rounded-full object-cover"
              />
            ) : (
              <div className="w-10 h-10 rounded-full bg-gradient-to-br from-blue-500 to-purple-600 flex items-center justify-center text-white font-semibold">
                {seller.username[0].toUpperCase()}
              </div>
            )}
            <div>
              <h1 className="font-semibold text-gray-900 dark:text-white">
                {seller.username}
              </h1>
              <p className="text-xs text-gray-500 dark:text-gray-400">
                {isLive ? "Live now" : "Recorded session"}
              </p>
            </div>
          </div>

          <div className="flex items-center gap-2 text-gray-600 dark:text-gray-400">
            <Users className="w-5 h-5" />
            <span className="font-medium">{viewerCount}</span>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <div className="max-w-7xl mx-auto p-4">
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-4">
          {/* Left Column: Video and Products */}
          <div className="lg:col-span-2 space-y-4">
            {/* Video Player */}
            <LiveStreamPlayer
              sessionId={session.id}
              streamUrl={streamUrl}
              isHost={isHost}
              onViewerCountChange={setViewerCount}
            />

            {/* Session Info */}
            <div className="bg-white dark:bg-gray-900 rounded-lg border border-gray-200 dark:border-gray-800 p-4">
              <h2 className="text-xl font-bold text-gray-900 dark:text-white mb-2">
                {session.title}
              </h2>
              {session.description && (
                <p className="text-gray-600 dark:text-gray-400 text-sm">
                  {session.description}
                </p>
              )}
            </div>

            {/* Pinned Products */}
            {isLive && (
              <ProductPins
                sessionId={session.id}
                isHost={isHost}
                onPurchase={handlePurchase}
              />
            )}

            {/* Host Controls */}
            {isHost && isLive && (
              <LiveStreamControls
                sessionId={session.id}
                viewerCount={viewerCount}
                duration={duration}
                pinnedProductsCount={session.pinned_products?.length || 0}
                onEndStream={handleEndStream}
                onPinProduct={handlePinProduct}
              />
            )}
          </div>

          {/* Right Column: Chat */}
          <div className="lg:col-span-1">
            <div className="sticky top-20 h-[calc(100vh-6rem)]">
              <LiveChatPanel
                sessionId={session.id}
                currentUserId={currentUserId}
                isHost={isHost}
                className="h-full"
              />
            </div>
          </div>
        </div>
      </div>

      {/* Purchase Modal */}
      {selectedProductId && (
        <PurchaseModal
          listingId={selectedProductId}
          sessionId={session.id}
          isOpen={showPurchaseModal}
          onClose={() => {
            setShowPurchaseModal(false);
            setSelectedProductId(null);
          }}
          onSuccess={() => {
            setShowPurchaseModal(false);
            setSelectedProductId(null);
          }}
        />
      )}
    </div>
  );
}

