        {/* All Listings */}
        <section className="mb-8">
          <h2 className="mb-4 text-2xl font-bold text-gray-900">
            All Products ({listings.length})
          </h2>
          <StorefrontListings listings={listings} />
        </section>

        {/* Reviews */}
        {reviews.length > 0 && (
          <section className="mb-8">
