}

export function ModerationQueue({ mode = "reports" }: ModerationQueueProps) {
  const [reports, setReports] = useState<Report[]>([]);
  const [flaggedListings, setFlaggedListings] = useState<FlaggedListing[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [filter, setFilter] = useState<"pending" | "reviewed" | "all">(
    "pending",
  );
  const [page, setPage] = useState(0);
  const [hasMore, setHasMore] = useState(false);
  const [reviewingId, setReviewingId] = useState<string | null>(null);
  const [adminNotes, setAdminNotes] = useState<Record<string, string>>({});

  useEffect(() => {
    if (mode === "ai-moderation") {
      fetchFlaggedListings();
    } else {
      fetchReports();
    }
  }, [filter, page, mode]);

  const fetchReports = async () => {
    try {
      setIsLoading(true);
      const response = await fetch(
        `/api/admin/reports?status=${filter}&page=${page}&limit=20`,
      );
      if (response.ok) {
        const data: PaginatedResponse<Report> = await response.json();
        setReports(data.data);
        setHasMore(data.hasMore);
      }
    } catch (error) {
      console.error("Error fetching reports:", error);
    } finally {
      setIsLoading(false);
    }
  };

  const fetchFlaggedListings = async () => {
    try {
      setIsLoading(true);
      const response = await fetch(
        `/api/moderation/queue?status=${filter}&page=${page}&limit=20`,
      );
      if (response.ok) {
        const data = await response.json();
        setFlaggedListings(data.data);
        setHasMore(data.pagination.hasMore);
      }
    } catch (error) {
      console.error("Error fetching flagged listings:", error);
    } finally {
      setIsLoading(false);
    }
  };

  const handleAction = async (
    reportId: string,
    action: "approve" | "remove",
    status: "reviewed" | "resolved",
  ) => {
    try {
      const response = await fetch(`/api/admin/reports/${reportId}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ action, status }),
      });

      if (response.ok) {
        fetchReports();
      }
    } catch (error) {
      console.error("Error updating report:", error);
    }
  };

  const handleModerationReview = async (
    moderationId: string,
    decision: "approve" | "reject",
  ) => {
    try {
      setReviewingId(moderationId);
      const response = await fetch(`/api/moderation/${moderationId}/review`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          decision,
          notes: adminNotes[moderationId] || undefined,
        }),
      });

      if (response.ok) {
        // Clear notes for this item
        setAdminNotes((prev) => {
          const updated = { ...prev };
          delete updated[moderationId];
          return updated;
        });
        // Refresh the list
        fetchFlaggedListings();
      } else {
        const error = await response.json();
        console.error("Error reviewing moderation:", error);
        alert(`Failed to ${decision} listing: ${error.error}`);
      }
    } catch (error) {
      console.error("Error reviewing moderation:", error);
      alert(`Failed to ${decision} listing`);
    } finally {
      setReviewingId(null);
    }
  };

  const getSeverityColor = (severity: string) => {
    switch (severity) {
      case "high":
        return "text-red-500";
      case "medium":
        return "text-yellow-500";
      case "low":
        return "text-blue-500";
      default:
        return "text-gray-500";
    }
  };

  const getSeverityBadge = (severity: string) => {
    switch (severity) {
      case "high":
        return "bg-red-500/20 text-red-500";
      case "medium":
        return "bg-yellow-500/20 text-yellow-500";
      case "low":
        return "bg-blue-500/20 text-blue-500";
      default:
        return "bg-gray-500/20 text-gray-500";
    }
  };

  return (
    <div className="space-y-4">
      <div className="flex items-center gap-2">
        <Button
          variant={filter === "pending" ? "default" : "outline"}
          onClick={() => {
            setFilter("pending");
            setPage(0);
          }}
        >
          Pending
        </Button>
        <Button
          variant={filter === "reviewed" ? "default" : "outline"}
          onClick={() => {
            setFilter("reviewed");
            setPage(0);
          }}
        >
          Reviewed
        </Button>
        {mode === "reports" && (
          <Button
            variant={filter === "all" ? "default" : "outline"}
            onClick={() => {
              setFilter("all");
              setPage(0);
            }}
          >
            All
          </Button>
        )}
      </div>

      {isLoading ? (
        <div className="text-white">Loading...</div>
      ) : mode === "ai-moderation" ? (
        // AI Moderation Queue View
        flaggedListings.length === 0 ? (
          <div className="text-center py-12 text-gray-400">
            No {filter} flagged listings found
          </div>
        ) : (
          <div className="space-y-4">
            {flaggedListings.map((item) => (
              <div
                key={item.moderation_id}
                className="glass-card rounded-lg border border-dark-border bg-dark-card p-6"
              >
                <div className="flex items-start justify-between gap-4">
                  <div className="flex-1">
                    {/* Header with confidence score */}
                    <div className="flex items-center gap-3 mb-3">
                      <AlertTriangle className="h-5 w-5 text-yellow-500" />
                      <span className="text-lg font-semibold text-white">
                        {item.listing_title}
                      </span>
                      <span className="ml-auto text-sm font-medium text-naija-green">
                        Γéª{item.listing_price.toLocaleString()}
                      </span>
                    </div>

                    {/* Confidence Score */}
                    <div className="mb-3">
                      <div className="flex items-center gap-2">
                        <span className="text-sm text-gray-400">
                          Confidence Score:
                        </span>
                        <span
                          className={`text-sm font-bold ${
                            item.confidence_score > 85
                              ? "text-red-500"
                              : item.confidence_score > 60
                                ? "text-yellow-500"
                                : "text-blue-500"
                          }`}
                        >
                          {item.confidence_score.toFixed(1)}%
                        </span>
                      </div>
                      <div className="w-full bg-gray-700 rounded-full h-2 mt-1">
                        <div
                          className={`h-2 rounded-full ${
                            item.confidence_score > 85
                              ? "bg-red-500"
                              : item.confidence_score > 60
                                ? "bg-yellow-500"
                                : "bg-blue-500"
                          }`}
                          style={{ width: `${item.confidence_score}%` }}
                        />
                      </div>
                    </div>

                    {/* Violations */}
                    {item.violations && item.violations.length > 0 && (
                      <div className="mb-3">
                        <p className="text-sm font-medium text-gray-300 mb-2">
                          Violations Detected:
                        </p>
                        <div className="space-y-2">
                          {item.violations.map((violation, idx) => (
                            <div
                              key={idx}
                              className="flex items-start gap-2 p-2 bg-dark-bg rounded"
                            >
                              <span
                                className={`text-xs font-semibold px-2 py-1 rounded ${getSeverityBadge(violation.severity)}`}
                              >
                                {violation.severity.toUpperCase()}
                              </span>
                              <div className="flex-1">
                                <p className="text-sm font-medium text-white">
                                  {violation.type.replace(/_/g, " ")}
                                </p>
                                <p className="text-xs text-gray-400">
                                  {violation.details}
                                </p>
                                {violation.confidence && (
                                  <p className="text-xs text-gray-500 mt-1">
                                    Confidence:{" "}
                                    {violation.confidence.toFixed(1)}%
                                  </p>
                                )}
                              </div>
                            </div>
                          ))}
                        </div>
                      </div>
                    )}

                    {/* Seller Info */}
                    <div className="mb-3">
                      <p className="text-xs text-gray-500">
                        Seller: {item.seller_username} ({item.seller_email})
                      </p>
                      <p className="text-xs text-gray-500">
                        Flagged: {formatRelativeTime(item.flagged_at)}
                      </p>
                    </div>

                    {/* Admin Notes Input */}
                    {filter === "pending" && (
                      <div className="mt-3">
                        <label className="text-xs text-gray-400 block mb-1">
                          Admin Notes (optional):
                        </label>
                        <textarea
                          className="w-full bg-dark-bg border border-dark-border rounded p-2 text-sm text-white"
                          rows={2}
                          placeholder="Add notes about your decision..."
                          value={adminNotes[item.moderation_id] || ""}
                          onChange={(e) =>
                            setAdminNotes((prev) => ({
                              ...prev,
                              [item.moderation_id]: e.target.value,
                            }))
                          }
                        />
                      </div>
                    )}
                  </div>

                  {/* Action Buttons */}
                  {filter === "pending" && (
                    <div className="flex flex-col gap-2">
                      <Button
                        size="sm"
                        variant="outline"
                        onClick={() =>
                          handleModerationReview(item.moderation_id, "approve")
                        }
                        disabled={reviewingId === item.moderation_id}
                        title="Approve listing"
                        className="whitespace-nowrap"
                      >
                        <CheckCircle className="h-4 w-4 mr-1" />
                        Approve
                      </Button>
                      <Button
                        size="sm"
                        variant="destructive"
                        onClick={() =>
                          handleModerationReview(item.moderation_id, "reject")
                        }
                        disabled={reviewingId === item.moderation_id}
                        title="Reject listing"
                        className="whitespace-nowrap"
                      >
                        <XCircle className="h-4 w-4 mr-1" />
                        Reject
                      </Button>
                      <Button
                        size="sm"
                        variant="ghost"
                        onClick={() =>
                          window.open(`/listing/${item.listing_id}`, "_blank")
                        }
                        title="View listing"
                        className="whitespace-nowrap"
                      >
                        <Eye className="h-4 w-4 mr-1" />
                        View
                      </Button>
                    </div>
                  )}
                </div>
              </div>
            ))}

            {hasMore && (
              <div className="flex justify-center">
                <Button onClick={() => setPage(page + 1)} variant="outline">
                  Load More
                </Button>
              </div>
            )}
          </div>
        )
      ) : // Original Reports View
      reports.length === 0 ? (
        <div className="text-center py-12 text-gray-400">
          No {filter} reports found
        </div>
      ) : (
        <div className="space-y-4">
          {reports.map((report) => (
            <div
              key={report.id}
              className="glass-card rounded-lg border border-dark-border bg-dark-card p-6"
            >
              <div className="flex items-start justify-between">
                <div className="flex-1">
                  <div className="flex items-center gap-2 mb-2">
                    <span className="text-sm font-medium text-naija-green">
                      {report.reason}
                    </span>
                    <span className="text-xs text-gray-500">
                      {formatRelativeTime(report.created_at)}
                    </span>
                  </div>

                  {report.listing && (
                    <div className="mb-3">
                      <p className="text-white font-medium">
                        {report.listing.title}
                      </p>
                      <p className="text-sm text-gray-400 line-clamp-2">
                        {report.description}
                      </p>
                    </div>
                  )}

                  {report.reporter && (
                    <p className="text-xs text-gray-500">
                      Reported by: {report.reporter.username} (
                      {report.reporter.email})
                    </p>
                  )}

                  {report.admin_notes && (
                    <div className="mt-2 p-2 bg-dark-bg rounded text-sm text-gray-300">
                      <span className="font-medium">Admin notes:</span>{" "}
                      {report.admin_notes}
                    </div>
                  )}
                </div>

                {filter === "pending" && (
                  <div className="flex gap-2 ml-4">
                    <Button
                      size="sm"
                      variant="outline"
                      onClick={() =>
                        handleAction(report.id, "approve", "reviewed")
                      }
                      title="Approve listing"
                    >
                      <CheckCircle className="h-4 w-4" />
                    </Button>
                    <Button
                      size="sm"
                      variant="destructive"
                      onClick={() =>
                        handleAction(report.id, "remove", "resolved")
                      }
                      title="Remove listing"
                    >
                      <XCircle className="h-4 w-4" />
                    </Button>
                    {report.listing && (
                      <Button
                        size="sm"
                        variant="ghost"
                        onClick={() =>
                          window.open(`/listing/${report.listing_id}`, "_blank")
                        }
                        title="View listing"
                      >
                        <Eye className="h-4 w-4" />
                      </Button>
                    )}
                  </div>
                )}
              </div>
            </div>
          ))}

          {hasMore && (
            <div className="flex justify-center">
              <Button onClick={() => setPage(page + 1)} variant="outline">
                Load More
              </Button>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

/**
 * RejectListingModal Component
 * 
 * Client Component for admin listing rejection with reason input.
 * 
 * Features:
 * - Radix Dialog modal for rejection workflow
 * - Textarea for rejection reason (min 10 chars, max 500 chars)
 * - Character count display
 * - Client-side validation for reason length
 * - Submit via rejectListingAction Server Action
 * - Loading state during submission
 * - Close modal and show success message on completion
 * - Mobile-optimized touch-friendly design
 * 
 * Requirements: 3.6
 * Task: 8.4
 */

'use client';

import { useState } from 'react';
import { toast } from 'sonner';
import { rejectListingAction } from '@/lib/actions/admin-actions';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Textarea } from '@/components/ui/textarea';
import { Label } from '@/components/ui/label';

interface RejectListingModalProps {
  /** Whether the modal is open */
  open: boolean;
  /** Callback to close the modal */
  onOpenChange: (open: boolean) => void;
  /** Listing ID to reject */
  listingId: string;
  /** Listing title for display */
  listingTitle: string;
  /** Callback fired after successful rejection */
  onRejectSuccess?: () => void;
}

/**
 * Modal for rejecting a listing with a reason
 * 
 * Validates reason length client-side (10-500 characters) and shows
 * real-time character count. Submits rejection via Server Action and
 * displays success/error messages.
 * 
 * @example
 * ```tsx
 * <RejectListingModal
 *   open={showRejectModal}
 *   onOpenChange={setShowRejectModal}
 *   listingId={listing.id}
 *   listingTitle={listing.title}
 *   onRejectSuccess={() => router.refresh()}
 * />
 * ```
 */
export function RejectListingModal({
  open,
  onOpenChange,
  listingId,
  listingTitle,
  onRejectSuccess,
}: RejectListingModalProps) {
  const [reason, setReason] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [validationError, setValidationError] = useState<string | null>(null);

  // Character count
  const charCount = reason.length;
  const minChars = 10;
  const maxChars = 500;
  const isValid = charCount >= minChars && charCount <= maxChars;

  /**
   * Handle reason text change with validation
   */
  const handleReasonChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const value = e.target.value;
    setReason(value);

    // Clear validation error when user starts typing
    if (validationError) {
      setValidationError(null);
    }

    // Validate length in real-time
    if (value.length > maxChars) {
      setValidationError(`Rejection reason must be at most ${maxChars} characters`);
    } else if (value.length > 0 && value.length < minChars) {
      setValidationError(`Rejection reason must be at least ${minChars} characters`);
    }
  };

  /**
   * Handle form submission
   */
  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    // Client-side validation
    if (!reason.trim()) {
      setValidationError('Please provide a rejection reason');
      return;
    }

    if (!isValid) {
      setValidationError(
        charCount < minChars
          ? `Rejection reason must be at least ${minChars} characters`
          : `Rejection reason must be at most ${maxChars} characters`
      );
      return;
    }

    setIsSubmitting(true);
    setValidationError(null);

    try {
      // Submit via Server Action
      const result = await rejectListingAction(listingId, reason.trim());

      if (result.success) {
        // Success - close modal and show success message
        toast.success('Listing rejected successfully');
        handleClose();

        // Notify parent component
        onRejectSuccess?.();
      } else {
        // Show error from Server Action
        setValidationError(result.error);
        toast.error(result.error);
      }
    } catch (error) {
      console.error('Unexpected error during listing rejection:', error);
      const errorMessage = 'An unexpected error occurred. Please try again.';
      setValidationError(errorMessage);
      toast.error(errorMessage);
    } finally {
      setIsSubmitting(false);
    }
  };

  /**
   * Handle modal close - reset state
   */
  const handleClose = () => {
    setReason('');
    setValidationError(null);
    onOpenChange(false);
  };

  /**
   * Get character count color based on validity
   */
  const getCharCountColor = () => {
    if (charCount === 0) return 'text-muted-foreground';
    if (charCount < minChars) return 'text-orange-500';
    if (charCount > maxChars) return 'text-destructive';
    return 'text-green-600';
  };

  return (
    <Dialog open={open} onOpenChange={handleClose}>
      <DialogContent className="sm:max-w-[500px]">
        <form onSubmit={handleSubmit}>
          <DialogHeader>
            <DialogTitle>Reject Listing</DialogTitle>
            <DialogDescription>
              Provide a clear reason for rejecting "{listingTitle}". The listing
              creator will receive this feedback.
            </DialogDescription>
          </DialogHeader>

          <div className="grid gap-4 py-4">
            <div className="grid gap-2">
              <Label htmlFor="reason">
                Rejection Reason
                <span className="text-destructive ml-1">*</span>
              </Label>
              <Textarea
                id="reason"
                placeholder="Explain why this listing cannot be approved (e.g., inappropriate content, missing information, violates guidelines)..."
                value={reason}
                onChange={handleReasonChange}
                rows={5}
                className={`resize-none ${
                  validationError ? 'border-destructive focus-visible:ring-destructive' : ''
                }`}
                disabled={isSubmitting}
                aria-invalid={!!validationError}
                aria-describedby={validationError ? 'reason-error' : 'reason-hint'}
              />

              {/* Character count */}
              <div className="flex justify-between items-center text-sm">
                <span id="reason-hint" className="text-muted-foreground">
                  Minimum {minChars} characters required
                </span>
                <span className={getCharCountColor()}>
                  {charCount} / {maxChars}
                </span>
              </div>

              {/* Validation error */}
              {validationError && (
                <p
                  id="reason-error"
                  className="text-sm text-destructive"
                  role="alert"
                >
                  {validationError}
                </p>
              )}
            </div>
          </div>

          <DialogFooter>
            <Button
              type="button"
              variant="outline"
              onClick={handleClose}
              disabled={isSubmitting}
            >
              Cancel
            </Button>
            <Button
              type="submit"
              variant="destructive"
              disabled={!isValid || isSubmitting}
            >
              {isSubmitting ? 'Rejecting...' : 'Reject Listing'}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { useEffect, useState } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Ban, CheckCircle, Search, Crown, Shield } from "lucide-react";
import type { AdminUser, PaginatedResponse } from "@/lib/types";
import { formatDate } from "@/lib/utils";

export function UserManagement() {
  const [users, setUsers] = useState<AdminUser[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState("");
  const [filters, setFilters] = useState({
    is_premium: null as boolean | null,
    is_suspended: null as boolean | null,
    phone_verified: null as boolean | null,
  });
  const [page, setPage] = useState(0);
  const [hasMore, setHasMore] = useState(false);

  useEffect(() => {
    const timer = setTimeout(() => {
      fetchUsers();
    }, 300);
    return () => clearTimeout(timer);
  }, [searchQuery, filters, page]);

  const fetchUsers = async () => {
    try {
      setIsLoading(true);
      const params = new URLSearchParams({
        page: page.toString(),
        limit: "20",
      });

      if (searchQuery) params.append("search_query", searchQuery);
      if (filters.is_premium !== null)
        params.append("is_premium", filters.is_premium.toString());
      if (filters.is_suspended !== null)
        params.append("is_suspended", filters.is_suspended.toString());
      if (filters.phone_verified !== null)
        params.append("phone_verified", filters.phone_verified.toString());

      const response = await fetch(`/api/admin/users?${params}`);
      if (response.ok) {
        const data: PaginatedResponse<AdminUser> = await response.json();
        setUsers(data.data);
        setHasMore(data.hasMore);
      }
    } catch (error) {
      console.error("Error fetching users:", error);
    } finally {
      setIsLoading(false);
    }
  };

  const handleSuspend = async (userId: string, suspend: boolean) => {
    try {
      const response = await fetch(`/api/admin/users/${userId}/suspend`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ is_suspended: suspend }),
      });

      if (response.ok) {
        fetchUsers();
      }
    } catch (error) {
      console.error("Error updating user:", error);
    }
  };

  return (
    <div className="space-y-4">
      <div className="flex flex-col sm:flex-row gap-4">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-gray-400" />
          <Input
            placeholder="Search by username or email..."
            value={searchQuery}
            onChange={(e) => {
              setSearchQuery(e.target.value);
              setPage(0);
            }}
            className="pl-10"
          />
        </div>

        <div className="flex gap-2">
          <Button
            variant={filters.is_premium === true ? "default" : "outline"}
            size="sm"
            onClick={() => {
              setFilters({
                ...filters,
                is_premium: filters.is_premium === true ? null : true,
              });
              setPage(0);
            }}
          >
            <Crown className="h-4 w-4 mr-1" />
            Premium
          </Button>
          <Button
            variant={filters.is_suspended === true ? "default" : "outline"}
            size="sm"
            onClick={() => {
              setFilters({
                ...filters,
                is_suspended: filters.is_suspended === true ? null : true,
              });
              setPage(0);
            }}
          >
            <Ban className="h-4 w-4 mr-1" />
            Suspended
          </Button>
          <Button
            variant={filters.phone_verified === true ? "default" : "outline"}
            size="sm"
            onClick={() => {
              setFilters({
                ...filters,
                phone_verified: filters.phone_verified === true ? null : true,
              });
              setPage(0);
            }}
          >
            <Shield className="h-4 w-4 mr-1" />
            Verified
          </Button>
        </div>
      </div>

      {isLoading ? (
        <div className="text-white">Loading users...</div>
      ) : users.length === 0 ? (
        <div className="text-center py-12 text-gray-400">No users found</div>
      ) : (
        <div className="space-y-4">
          <div className="overflow-x-auto">
            <table className="w-full">
              <thead>
                <tr className="border-b border-dark-border">
                  <th className="text-left py-3 px-4 text-sm font-medium text-gray-400">
                    User
                  </th>
                  <th className="text-left py-3 px-4 text-sm font-medium text-gray-400">
                    Trust Score
                  </th>
                  <th className="text-left py-3 px-4 text-sm font-medium text-gray-400">
                    Listings
                  </th>
                  <th className="text-left py-3 px-4 text-sm font-medium text-gray-400">
                    Status
                  </th>
                  <th className="text-left py-3 px-4 text-sm font-medium text-gray-400">
                    Joined
                  </th>
                  <th className="text-right py-3 px-4 text-sm font-medium text-gray-400">
                    Actions
                  </th>
                </tr>
              </thead>
              <tbody>
                {users.map((user) => (
                  <tr
                    key={user.id}
                    className="border-b border-dark-border hover:bg-dark-card/50"
                  >
                    <td className="py-3 px-4">
                      <div className="flex items-center gap-3">
                        <div className="h-10 w-10 rounded-full bg-gradient-to-br from-naija-green to-neon-cyan flex items-center justify-center text-white font-bold">
                          {user.username[0].toUpperCase()}
                        </div>
                        <div>
                          <p className="text-white font-medium">
                            {user.username}
                          </p>
                          <p className="text-xs text-gray-400">{user.email}</p>
                        </div>
                      </div>
                    </td>
                    <td className="py-3 px-4">
                      <div className="flex items-center gap-2">
                        <div className="text-white font-medium">
                          {user.trust_score}
                        </div>
                        {user.phone_verified && (
                          <CheckCircle className="h-4 w-4 text-naija-green" />
                        )}
                        {user.is_premium && (
                          <Crown className="h-4 w-4 text-yellow-500" />
                        )}
                      </div>
                    </td>
                    <td className="py-3 px-4">
                      <div className="text-white">
                        {user.active_listings_count} / {user.listings_count}
                      </div>
                      <div className="text-xs text-gray-400">
                        active / total
                      </div>
                    </td>
                    <td className="py-3 px-4">
                      {user.is_suspended ? (
                        <span className="inline-flex items-center px-2 py-1 rounded-full text-xs font-medium bg-red-500/10 text-red-500">
                          Suspended
                        </span>
