                      ) : (
                        <Button
                          size="sm"
                          variant="destructive"
                          onClick={() => handleSuspend(user.id, true)}
                        >
                          Suspend
                        </Button>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

          {hasMore && (
            <div className="flex justify-center">
              <Button onClick={() => setPage(page + 1)} variant="outline">
                Load More
              </Button>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

/**
 * VendorApprovalCard Client Component
 * 
 * Displays vendor application details in a card format with approve/reject actions.
 * This component is used in the admin dashboard to review and approve/reject vendor applications.
 * 
 * Features:
 * - Display business name, description, contact details
 * - Display user information and submission date
 * - Approve button with loading state
 * - Reject button that opens a modal for rejection reason
 * - Success/error toast notifications
 * - Mobile-responsive card layout
 * 
 * Requirements: 4.3, 4.4, 4.6
 */

'use client';

import { useState } from 'react';
import { Loader2, Check, X, Mail, Phone, User, Calendar, Building2 } from 'lucide-react';
import { format } from 'date-fns';

import {
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Textarea } from '@/components/ui/textarea';
import { Label } from '@/components/ui/label';
import { Badge } from '@/components/ui/badge';

import { approveVendorAction, rejectVendorAction } from '@/lib/actions/admin-actions';
import type { VendorApplicationWithUser } from '@/lib/types/core';
import { toastSuccess, toastError } from '@/lib/utils/toast';

// ============================================================================
// Props Interface
// ============================================================================

export interface VendorApprovalCardProps {
  application: VendorApplicationWithUser;
  onApproved?: () => void;
  onRejected?: () => void;
}

// ============================================================================
// Component
// ============================================================================

export function VendorApprovalCard({
  application,
  onApproved,
  onRejected,
}: VendorApprovalCardProps) {
  // ============================================================================
  // State
  // ============================================================================

  const [isApproving, setIsApproving] = useState(false);
  const [isRejectDialogOpen, setIsRejectDialogOpen] = useState(false);
  const [isRejecting, setIsRejecting] = useState(false);
  const [rejectionReason, setRejectionReason] = useState('');
  const [reasonError, setReasonError] = useState<string | null>(null);

  // ============================================================================
  // Handlers
  // ============================================================================

  /**
   * Handle approval action
   * Requirements: 4.4
   */
  const handleApprove = async () => {
    setIsApproving(true);

    try {
      const result = await approveVendorAction(application.id);

      if (result.success) {
        toastSuccess('Vendor application approved successfully! ≡ƒÄë', `${application.business_name} is now a verified vendor.`);
        onApproved?.();
      } else {
        toastError('Failed to approve vendor application', result.error || 'An unexpected error occurred.');
      }
    } catch (error) {
      console.error('Error approving vendor:', error);
      toastError('Failed to approve vendor application', 'An unexpected error occurred. Please try again.');
    } finally {
      setIsApproving(false);
    }
  };

  /**
   * Handle opening reject dialog
   */
  const handleOpenRejectDialog = () => {
    setRejectionReason('');
    setReasonError(null);
    setIsRejectDialogOpen(true);
  };

  /**
   * Handle rejection action
   * Requirements: 4.6
   */
  const handleReject = async () => {
    // Validate rejection reason (minimum 10 characters)
    if (rejectionReason.trim().length < 10) {
      setReasonError('Rejection reason must be at least 10 characters');
      return;
    }

    if (rejectionReason.trim().length > 500) {
      setReasonError('Rejection reason must be at most 500 characters');
      return;
    }

    setReasonError(null);
    setIsRejecting(true);

    try {
      const result = await rejectVendorAction(application.id, rejectionReason.trim());

      if (result.success) {
        toastSuccess('Vendor application rejected', 'The applicant has been notified.');
        setIsRejectDialogOpen(false);
        onRejected?.();
      } else {
        toastError('Failed to reject vendor application', result.error || 'An unexpected error occurred.');
      }
    } catch (error) {
      console.error('Error rejecting vendor:', error);
      toastError('Failed to reject vendor application', 'An unexpected error occurred. Please try again.');
    } finally {
      setIsRejecting(false);
    }
  };

  /**
   * Handle rejection reason input change
   */
  const handleReasonChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    setRejectionReason(e.target.value);
    if (reasonError) {
      setReasonError(null);
    }
  };

  // ============================================================================
  // Format Date
  // ============================================================================

  const formattedDate = format(new Date(application.created_at), 'MMM d, yyyy');

  // ============================================================================
  // Render
  // ============================================================================

  return (
    <>
      <Card className="w-full">
        <CardHeader>
          <div className="flex flex-col gap-2 sm:flex-row sm:items-start sm:justify-between">
            <div className="flex-1">
              <CardTitle className="flex items-center gap-2 text-xl">
                <Building2 className="h-5 w-5 text-primary" />
                {application.business_name}
              </CardTitle>
              <CardDescription className="mt-1">
                Vendor Application
              </CardDescription>
            </div>
            <Badge variant="secondary" className="w-fit">
              {application.status}
            </Badge>
          </div>
        </CardHeader>

        <CardContent className="space-y-4">
          {/* Business Description */}
          <div>
            <h4 className="text-sm font-semibold mb-2">Business Description</h4>
            <p className="text-sm text-muted-foreground leading-relaxed">
              {application.business_description}
            </p>
          </div>

          {/* Contact Information */}
          <div className="grid gap-3 sm:grid-cols-2">
            <div className="flex items-start gap-2">
              <Mail className="h-4 w-4 text-muted-foreground mt-0.5 flex-shrink-0" />
              <div className="min-w-0 flex-1">
                <p className="text-xs text-muted-foreground">Contact Email</p>
                <p className="text-sm font-medium truncate">{application.contact_email}</p>
              </div>
            </div>

            <div className="flex items-start gap-2">
              <Phone className="h-4 w-4 text-muted-foreground mt-0.5 flex-shrink-0" />
              <div className="min-w-0 flex-1">
                <p className="text-xs text-muted-foreground">Contact Phone</p>
                <p className="text-sm font-medium">{application.contact_phone}</p>
              </div>
            </div>
          </div>

          {/* User Information */}
          <div className="grid gap-3 sm:grid-cols-2 pt-2 border-t">
            <div className="flex items-start gap-2">
              <User className="h-4 w-4 text-muted-foreground mt-0.5 flex-shrink-0" />
              <div className="min-w-0 flex-1">
                <p className="text-xs text-muted-foreground">Applicant</p>
                <p className="text-sm font-medium truncate">
                  {application.user?.full_name || 'Unknown User'}
                </p>
                <p className="text-xs text-muted-foreground truncate">
                  {application.user?.email || ''}
                </p>
              </div>
            </div>

            <div className="flex items-start gap-2">
              <Calendar className="h-4 w-4 text-muted-foreground mt-0.5 flex-shrink-0" />
              <div className="min-w-0 flex-1">
                <p className="text-xs text-muted-foreground">Submitted</p>
                <p className="text-sm font-medium">{formattedDate}</p>
              </div>
            </div>
          </div>
        </CardContent>

        <CardFooter className="flex flex-col gap-2 sm:flex-row sm:justify-end">
          <Button
            variant="outline"
            onClick={handleOpenRejectDialog}
            disabled={isApproving || isRejecting}
            className="w-full sm:w-auto"
          >
            <X className="h-4 w-4 mr-2" />
            Reject
          </Button>

          <Button
            onClick={handleApprove}
            disabled={isApproving || isRejecting}
            className="w-full sm:w-auto"
          >
            {isApproving ? (
              <>
                <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                Approving...
              </>
            ) : (
              <>
                <Check className="h-4 w-4 mr-2" />
                Approve
              </>
            )}
          </Button>
        </CardFooter>
      </Card>

      {/* Rejection Dialog */}
      <Dialog open={isRejectDialogOpen} onOpenChange={setIsRejectDialogOpen}>
        <DialogContent className="sm:max-w-[500px]">
          <DialogHeader>
            <DialogTitle>Reject Vendor Application</DialogTitle>
            <DialogDescription>
              Please provide a reason for rejecting {application.business_name}'s vendor application.
              The applicant will receive this feedback.
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-4 py-4">
            <div className="space-y-2">
              <Label htmlFor="rejection-reason">
                Rejection Reason <span className="text-destructive">*</span>
              </Label>
              <Textarea
                id="rejection-reason"
                placeholder="Explain why this vendor application cannot be approved at this time..."
                value={rejectionReason}
                onChange={handleReasonChange}
                rows={4}
                className={reasonError ? 'border-destructive' : ''}
                disabled={isRejecting}
              />
              {reasonError && (
                <p className="text-sm text-destructive">{reasonError}</p>
              )}
              <p className="text-xs text-muted-foreground">
                Minimum 10 characters, maximum 500 characters ({rejectionReason.length}/500)
              </p>
            </div>
          </div>

          <DialogFooter className="flex-col gap-2 sm:flex-row">
            <Button
              variant="outline"
              onClick={() => setIsRejectDialogOpen(false)}
              disabled={isRejecting}
              className="w-full sm:w-auto"
            >
              Cancel
            </Button>
            <Button
              variant="destructive"
              onClick={handleReject}
              disabled={isRejecting || rejectionReason.trim().length < 10}
              className="w-full sm:w-auto"
            >
              {isRejecting ? (
                <>
                  <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                  Rejecting...
                </>
              ) : (
                <>
                  <X className="h-4 w-4 mr-2" />
                  Reject Application
                </>
              )}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
}

"use client";

/**
 * Value Calculator Component
 *
 * Shows estimated value comparison between items in a barter exchange.
 * Displays value difference and helps users understand the exchange balance.
 *
 * Requirements: 12.9
 */

import { Card } from "@/components/ui/card";
import { ArrowLeftRight, TrendingUp, TrendingDown, Minus } from "lucide-react";

interface ValueCalculatorProps {
  item1: {
    title: string;
    price: number;
    image?: string;
  };
  item2: {
    title: string;
    price: number;
    image?: string;
  };
  cashAdjustment?: number;
  className?: string;
}

export function ValueCalculator({
  item1,
  item2,
  cashAdjustment = 0,
  className = "",
}: ValueCalculatorProps) {
  const valueDifference = item2.price - item1.price;
  const finalBalance = valueDifference - cashAdjustment;
  const percentageDifference =
    item1.price > 0 ? Math.abs((valueDifference / item1.price) * 100) : 0;

  return (
    <Card className={`p-6 ${className}`}>
      <h3 className="text-lg font-semibold mb-4">Value Comparison</h3>

      {/* Items Comparison */}
      <div className="grid grid-cols-[1fr,auto,1fr] gap-4 mb-6">
        {/* Item 1 */}
        <div className="space-y-2">
          {item1.image && (
            <div className="aspect-square rounded-lg overflow-hidden bg-muted">
              <img
                src={item1.image}
                alt={item1.title}
                className="w-full h-full object-cover"
              />
            </div>
          )}
          <div>
            <p className="text-sm font-medium truncate">{item1.title}</p>
            <p className="text-lg font-bold">Γéª{item1.price.toLocaleString()}</p>
          </div>
        </div>

        {/* Exchange Icon */}
        <div className="flex items-center justify-center">
          <div className="rounded-full bg-primary/10 p-3">
            <ArrowLeftRight className="h-6 w-6 text-primary" />
          </div>
        </div>

        {/* Item 2 */}
        <div className="space-y-2">
          {item2.image && (
            <div className="aspect-square rounded-lg overflow-hidden bg-muted">
              <img
                src={item2.image}
                alt={item2.title}
                className="w-full h-full object-cover"
              />
            </div>
          )}
          <div>
            <p className="text-sm font-medium truncate">{item2.title}</p>
            <p className="text-lg font-bold">Γéª{item2.price.toLocaleString()}</p>
          </div>
        </div>
      </div>

      {/* Value Analysis */}
      <div className="space-y-3 bg-muted/50 rounded-lg p-4">
        {/* Raw Value Difference */}
        <div className="flex items-center justify-between">
          <span className="text-sm text-muted-foreground">
            Value difference:
          </span>
          <div className="flex items-center gap-2">
            {valueDifference > 0 ? (
              <TrendingUp className="h-4 w-4 text-green-600" />
            ) : valueDifference < 0 ? (
              <TrendingDown className="h-4 w-4 text-red-600" />
            ) : (
              <Minus className="h-4 w-4 text-muted-foreground" />
            )}
            <span
              className={`font-semibold ${
                valueDifference > 0
                  ? "text-green-600"
                  : valueDifference < 0
                    ? "text-red-600"
                    : "text-muted-foreground"
              }`}
            >
              {valueDifference > 0 ? "+" : ""}Γéª
              {Math.abs(valueDifference).toLocaleString()}
            </span>
          </div>
        </div>

        {/* Percentage Difference */}
        {percentageDifference > 0 && (
          <div className="flex items-center justify-between text-sm">
            <span className="text-muted-foreground">
              Percentage difference:
            </span>
            <span className="font-medium">
              {percentageDifference.toFixed(1)}%
            </span>
          </div>
        )}

        {/* Cash Adjustment */}
        {cashAdjustment > 0 && (
          <>
            <div className="border-t pt-3 flex items-center justify-between">
              <span className="text-sm text-muted-foreground">
                Cash adjustment:
              </span>
              <span className="font-medium">
                -Γéª{cashAdjustment.toLocaleString()}
              </span>
            </div>

            {/* Final Balance */}
            <div className="border-t pt-3 flex items-center justify-between">
              <span className="text-sm font-semibold">Final balance:</span>
              <span
                className={`font-bold ${
                  finalBalance > 0
                    ? "text-green-600"
                    : finalBalance < 0
                      ? "text-red-600"
                      : "text-muted-foreground"
                }`}
              >
                {finalBalance === 0 ? (
                  "Even exchange"
                ) : (
                  <>
                    {finalBalance > 0 ? "+" : ""}Γéª
                    {Math.abs(finalBalance).toLocaleString()}
                  </>
                )}
              </span>
            </div>
          </>
        )}
      </div>

      {/* Exchange Fairness Indicator */}
      <div className="mt-4">
        {Math.abs(finalBalance) === 0 ? (
          <div className="bg-green-50 dark:bg-green-950/20 border border-green-200 dark:border-green-800 rounded-lg p-3 text-sm text-green-700 dark:text-green-400">
            Γ£ô This is an even exchange with balanced values
          </div>
        ) : Math.abs(finalBalance) < item1.price * 0.1 ? (
          <div className="bg-blue-50 dark:bg-blue-950/20 border border-blue-200 dark:border-blue-800 rounded-lg p-3 text-sm text-blue-700 dark:text-blue-400">
            Γä╣ This is a fairly balanced exchange (within 10% difference)
          </div>
        ) : (
          <div className="bg-yellow-50 dark:bg-yellow-950/20 border border-yellow-200 dark:border-yellow-800 rounded-lg p-3 text-sm text-yellow-700 dark:text-yellow-400">
            ΓÜá There&apos;s a significant value difference. Consider adding a cash
            adjustment.
          </div>
        )}
      </div>

      {/* Exchange Summary */}
      <div className="mt-4 text-sm text-muted-foreground">
        {finalBalance > 0 ? (
          <p>
            The person receiving <strong>{item2.title}</strong> would get an
            item worth{" "}
            <strong>Γéª{Math.abs(finalBalance).toLocaleString()}</strong> more.
          </p>
        ) : finalBalance < 0 ? (
          <p>
            The person receiving <strong>{item1.title}</strong> would get an
            item worth{" "}
            <strong>Γéª{Math.abs(finalBalance).toLocaleString()}</strong> more.
          </p>
        ) : (
          <p>Both items have equal value, making this a fair exchange.</p>
        )}
      </div>
    </Card>
  );
}

/**
 * Boost Performance Analytics Component
 * Displays performance metrics for boosted listings
 * Requirements: 14.8
 * Task: 34.9
 */

"use client";

import { useEffect, useState } from "react";
import { Eye, TrendingUp, MessageCircle, Zap, Clock } from "lucide-react";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Progress } from "@/components/ui/progress";
import type { Boost, BoostPerformance } from "@/lib/types";

interface BoostPerformanceAnalyticsProps {
  listingId: string;
}

interface BoostWithPerformance extends Boost {
  performance: BoostPerformance;
}

export function BoostPerformanceAnalytics({
  listingId,
}: BoostPerformanceAnalyticsProps) {
  const [boosts, setBoosts] = useState<BoostWithPerformance[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchBoostData();
  }, [listingId]);

  const fetchBoostData = async () => {
    try {
      const response = await fetch(`/api/boosts/${listingId}`);

      if (!response.ok) {
        throw new Error("Failed to fetch boost data");
      }

      const data = await response.json();
      setBoosts(data.active_boosts || []);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to load data");
    } finally {
      setIsLoading(false);
    }
  };

  const calculateTimeRemaining = (expiresAt: string) => {
    const now = new Date();
    const expiry = new Date(expiresAt);
    const diff = expiry.getTime() - now.getTime();

    if (diff <= 0) return "Expired";

    const hours = Math.floor(diff / (1000 * 60 * 60));
    const minutes = Math.floor((diff % (1000 * 60 * 60)) / (1000 * 60));

    if (hours > 24) {
      const days = Math.floor(hours / 24);
      return `${days}d ${hours % 24}h remaining`;
    }

    return `${hours}h ${minutes}m remaining`;
  };

  const calculateProgress = (startedAt: string, expiresAt: string) => {
    const start = new Date(startedAt).getTime();
    const end = new Date(expiresAt).getTime();
    const now = Date.now();

    const total = end - start;
    const elapsed = now - start;

    return Math.min(100, Math.max(0, (elapsed / total) * 100));
  };

  if (isLoading) {
    return (
      <Card>
        <CardContent className="py-8 text-center">
          <div className="animate-pulse">Loading boost data...</div>
        </CardContent>
      </Card>
    );
  }

  if (error) {
    return (
      <Card>
        <CardContent className="py-8 text-center text-destructive">
          {error}
        </CardContent>
      </Card>
    );
  }

  if (boosts.length === 0) {
    return (
      <Card>
        <CardContent className="py-8 text-center text-muted-foreground">
          <Zap className="mx-auto mb-2 h-8 w-8 opacity-50" />
          <p>No active boosts for this listing</p>
        </CardContent>
      </Card>
    );
  }

  return (
    <div className="space-y-4">
      {boosts.map((boost) => {
        const timeRemaining = calculateTimeRemaining(boost.expires_at);
        const progress = calculateProgress(boost.started_at, boost.expires_at);

        return (
          <Card key={boost.id}>
            <CardHeader>
              <div className="flex items-center justify-between">
                <CardTitle className="flex items-center gap-2">
                  <Zap className="h-5 w-5 text-amber-500" />
                  Active Boost
                </CardTitle>
                <span className="text-sm text-muted-foreground">
                  {boost.package_type.charAt(0).toUpperCase() +
                    boost.package_type.slice(1)}{" "}
                  Package
                </span>
              </div>
              <CardDescription className="flex items-center gap-2">
                <Clock className="h-4 w-4" />
                {timeRemaining}
              </CardDescription>
            </CardHeader>

            <CardContent className="space-y-4">
              <div>
                <div className="mb-2 flex justify-between text-sm">
                  <span className="text-muted-foreground">Time Progress</span>
                  <span className="font-medium">{Math.round(progress)}%</span>
                </div>
                <Progress value={progress} className="h-2" />
              </div>

              <div className="grid gap-4 sm:grid-cols-3">
                <div className="flex items-center gap-3 rounded-lg border p-3">
                  <div className="rounded-full bg-blue-100 p-2 dark:bg-blue-900">
                    <Eye className="h-4 w-4 text-blue-600 dark:text-blue-400" />
                  </div>
                  <div>
                    <p className="text-2xl font-bold">
                      {boost.performance.views_gained}
                    </p>
                    <p className="text-xs text-muted-foreground">
                      Views Gained
                    </p>
                  </div>
                </div>

                <div className="flex items-center gap-3 rounded-lg border p-3">
                  <div className="rounded-full bg-green-100 p-2 dark:bg-green-900">
                    <TrendingUp className="h-4 w-4 text-green-600 dark:text-green-400" />
                  </div>
                  <div>
                    <p className="text-2xl font-bold">
                      {boost.performance.impressions_gained}
                    </p>
                    <p className="text-xs text-muted-foreground">Impressions</p>
                  </div>
                </div>

                <div className="flex items-center gap-3 rounded-lg border p-3">
                  <div className="rounded-full bg-purple-100 p-2 dark:bg-purple-900">
                    <MessageCircle className="h-4 w-4 text-purple-600 dark:text-purple-400" />
                  </div>
                  <div>
                    <p className="text-2xl font-bold">
                      {boost.performance.messages_received}
                    </p>
                    <p className="text-xs text-muted-foreground">Messages</p>
                  </div>
                </div>
              </div>

              <div className="rounded-lg bg-muted p-3 text-sm">
                <p className="font-medium">Boost Details</p>
                <div className="mt-2 grid gap-1 text-muted-foreground">
                  <div className="flex justify-between">
                    <span>Started:</span>
                    <span>
                      {new Date(boost.started_at).toLocaleDateString()}
                    </span>
                  </div>
                  <div className="flex justify-between">
                    <span>Expires:</span>
                    <span>
                      {new Date(boost.expires_at).toLocaleDateString()}
                    </span>
                  </div>
                  <div className="flex justify-between">
                    <span>Duration:</span>
                    <span>{boost.duration_hours} hours</span>
                  </div>
                </div>
              </div>
            </CardContent>
          </Card>
        );
      })}
    </div>
  );
}

