"use client";

import { useState, useCallback, useRef } from "react";
import { motion, AnimatePresence } from "framer-motion";
import Image from "next/image";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Upload, X, Star, Image as ImageIcon, AlertCircle } from "lucide-react";
import { cn } from "@/lib/utils";

interface PhotoUploaderProps {
  photos: string[];
  primaryPhotoUrl?: string;
  onPhotosChange: (photos: File[]) => Promise<void>;
  onPrimaryPhotoChange: (url: string) => void;
  onPhotoRemove: (url: string) => void;
  maxPhotos?: number;
  maxFileSize?: number; // in MB
  disabled?: boolean;
}

const ACCEPTED_IMAGE_TYPES = ["image/jpeg", "image/jpg", "image/png", "image/webp"];
const DEFAULT_MAX_PHOTOS = 50;
const DEFAULT_MAX_FILE_SIZE = 5; // 5MB

export function PhotoUploader({
  photos,
  primaryPhotoUrl,
  onPhotosChange,
  onPrimaryPhotoChange,
  onPhotoRemove,
  maxPhotos = DEFAULT_MAX_PHOTOS,
  maxFileSize = DEFAULT_MAX_FILE_SIZE,
  disabled = false,
}: PhotoUploaderProps) {
  const [isDragging, setIsDragging] = useState(false);
  const [errors, setErrors] = useState<string[]>([]);
  const [isUploading, setIsUploading] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const validateFiles = useCallback((files: File[]): { valid: File[]; errors: string[] } => {
    const errors: string[] = [];
    const valid: File[] = [];

    // Check total count
    if (photos.length + files.length > maxPhotos) {
      errors.push(`Maximum ${maxPhotos} photos allowed. You can add ${maxPhotos - photos.length} more.`);
      return { valid: [], errors };
    }

    for (const file of files) {
      // Check file type
      if (!ACCEPTED_IMAGE_TYPES.includes(file.type)) {
        errors.push(`${file.name}: Invalid file type. Only JPEG, PNG, and WebP are accepted.`);
        continue;
      }

      // Check file size
      const fileSizeMB = file.size / (1024 * 1024);
      if (fileSizeMB > maxFileSize) {
        errors.push(`${file.name}: File size exceeds ${maxFileSize}MB limit.`);
        continue;
      }

      valid.push(file);
    }

    return { valid, errors };
  }, [photos.length, maxPhotos, maxFileSize]);

  const handleFileSelect = async (files: FileList | null) => {
    if (!files || disabled) return;

    const fileArray = Array.from(files);
    const { valid, errors: validationErrors } = validateFiles(fileArray);

    setErrors(validationErrors);

    if (valid.length > 0) {
      setIsUploading(true);
      try {
        await onPhotosChange(valid);
        setErrors([]);
      } catch (error) {
        setErrors([error instanceof Error ? error.message : "Failed to upload photos"]);
      } finally {
        setIsUploading(false);
      }
    }

    // Reset input
    if (fileInputRef.current) {
      fileInputRef.current.value = "";
    }
  };

  const handleDragOver = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if (!disabled) {
      setIsDragging(true);
    }
  }, [disabled]);

  const handleDragLeave = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragging(false);
  }, []);

  const handleDrop = useCallback(async (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragging(false);

    if (disabled) return;

    const files = e.dataTransfer.files;
    await handleFileSelect(files);
  }, [disabled, handleFileSelect]);

  const handleRemove = (url: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (!disabled) {
      onPhotoRemove(url);
      // If removing primary photo, clear it
      if (url === primaryPhotoUrl && photos.length > 1) {
        const nextPhoto = photos.find(p => p !== url);
        if (nextPhoto) {
          onPrimaryPhotoChange(nextPhoto);
        }
      }
    }
  };

  const handleSetPrimary = (url: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (!disabled) {
      onPrimaryPhotoChange(url);
    }
  };

  return (
    <div className="space-y-4">
      {/* Upload Area */}
      <Card
        className={cn(
          "relative border-2 border-dashed transition-all",
          isDragging && "border-blue-500 bg-blue-50 dark:bg-blue-950",
          disabled && "opacity-50 cursor-not-allowed",
          !disabled && "cursor-pointer hover:border-blue-400"
        )}
        onDragOver={handleDragOver}
        onDragLeave={handleDragLeave}
        onDrop={handleDrop}
        onClick={() => !disabled && fileInputRef.current?.click()}
      >
        <div className="p-8 text-center">
          <input
            ref={fileInputRef}
            type="file"
            multiple
            accept={ACCEPTED_IMAGE_TYPES.join(",")}
            onChange={(e) => handleFileSelect(e.target.files)}
            className="hidden"
            disabled={disabled}
          />
          
          <motion.div
            initial={{ scale: 1 }}
            animate={{ scale: isDragging ? 1.1 : 1 }}
            transition={{ duration: 0.2 }}
          >
            <Upload className="w-12 h-12 mx-auto mb-4 text-gray-400" />
          </motion.div>

          <h3 className="text-lg font-semibold mb-2">Upload Photos</h3>
          <p className="text-sm text-gray-600 dark:text-gray-400 mb-2">
            Drag and drop photos here, or click to select files
          </p>
          <p className="text-xs text-gray-500">
            {photos.length} / {maxPhotos} photos ΓÇó Max {maxFileSize}MB per file ΓÇó JPEG, PNG, WebP
          </p>

          {isUploading && (
            <div className="mt-4">
              <div className="animate-pulse text-sm text-blue-600">Uploading...</div>
            </div>
          )}
        </div>
      </Card>

      {/* Error Messages */}
      <AnimatePresence>
        {errors.length > 0 && (
          <motion.div
            initial={{ opacity: 0, y: -10 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -10 }}
          >
            <Card className="p-4 bg-red-50 dark:bg-red-950 border-red-200 dark:border-red-800">
              <div className="flex items-start">
                <AlertCircle className="w-5 h-5 text-red-600 mr-2 flex-shrink-0 mt-0.5" />
                <div className="flex-1">
                  <h4 className="text-sm font-semibold text-red-900 dark:text-red-100 mb-1">
                    Upload Errors
                  </h4>
                  <ul className="text-sm text-red-800 dark:text-red-200 space-y-1">
                    {errors.map((error, index) => (
                      <li key={index}>ΓÇó {error}</li>
                    ))}
                  </ul>
                </div>
              </div>
            </Card>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Photo Gallery Preview */}
      {photos.length > 0 && (
        <div>
          <div className="flex items-center justify-between mb-3">
            <h3 className="text-lg font-semibold">Photo Gallery</h3>
            <Badge variant="secondary">
              <ImageIcon className="w-3 h-3 mr-1" />
              {photos.length} photo{photos.length !== 1 ? 's' : ''}
            </Badge>
          </div>

          <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5 gap-4">
            <AnimatePresence>
              {photos.map((photoUrl, index) => (
                <motion.div
                  key={photoUrl}
                  initial={{ opacity: 0, scale: 0.8 }}
                  animate={{ opacity: 1, scale: 1 }}
                  exit={{ opacity: 0, scale: 0.8 }}
                  transition={{ duration: 0.2 }}
                  className="relative group"
                >
                  <Card className="relative aspect-square overflow-hidden">
                    <Image
                      src={photoUrl}
                      alt={`Photo ${index + 1}`}
                      fill
                      className="object-cover"
                      sizes="(max-width: 768px) 50vw, (max-width: 1024px) 33vw, 20vw"
                    />

                    {/* Primary Badge */}
                    {photoUrl === primaryPhotoUrl && (
                      <div className="absolute top-2 left-2 z-10">
                        <Badge className="bg-blue-600 text-white">
                          <Star className="w-3 h-3 mr-1 fill-current" />
                          Primary
                        </Badge>
                      </div>
                    )}

                    {/* Actions Overlay */}
                    {!disabled && (
                      <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center gap-2">
                        {photoUrl !== primaryPhotoUrl && (
                          <Button
                            size="sm"
                            variant="secondary"
                            onClick={(e) => handleSetPrimary(photoUrl, e)}
                            className="text-xs"
                          >
                            <Star className="w-3 h-3 mr-1" />
                            Set Primary
                          </Button>
                        )}
                        <Button
                          size="sm"
                          variant="destructive"
                          onClick={(e) => handleRemove(photoUrl, e)}
                        >
                          <X className="w-4 h-4" />
                        </Button>
                      </div>
                    )}
                  </Card>
                </motion.div>
              ))}
            </AnimatePresence>
          </div>

          {/* Helper Text */}
          {!primaryPhotoUrl && photos.length > 0 && (
            <p className="text-sm text-amber-600 dark:text-amber-400 mt-3 flex items-center">
              <AlertCircle className="w-4 h-4 mr-1" />
              Select a primary photo to display as your business thumbnail
            </p>
          )}
        </div>
      )}

      {/* Empty State */}
      {photos.length === 0 && !isUploading && (
        <Card className="p-8 text-center bg-gray-50 dark:bg-gray-900">
          <ImageIcon className="w-12 h-12 mx-auto mb-3 text-gray-400" />
          <p className="text-sm text-gray-600 dark:text-gray-400">
            No photos uploaded yet. Add photos to showcase your business!
          </p>
        </Card>
      )}
    </div>
  );
}

"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { z } from "zod";
import { motion, AnimatePresence } from "framer-motion";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Progress } from "@/components/ui/progress";
import { StateSelector, AreaSelector } from "@/components/location";
import { createBusiness } from "@/lib/services/business";
import { MapPin, Building2, Phone, Mail, Globe } from "lucide-react";

// Requirements: 21.1, 21.2, 21.6
// Business creation form with verification support

const businessSchema = z.object({
  name: z.string().min(3, "Business name must be at least 3 characters"),
  description: z.string().min(20, "Description must be at least 20 characters"),
  category_id: z.string().min(1, "Please select a category"),
  state: z.string().min(1, "Please select a state"),
  lga: z.string().min(1, "Please select an LGA"),
  ward: z.string().optional(),
  address: z.string().optional(),
  phone: z.string().min(10, "Phone number is required"),
  email: z.string().email("Valid email is required"),
  website: z.string().url("Valid URL required").optional().or(z.literal("")),
  whatsapp: z.string().optional(),
});

type BusinessFormData = z.infer<typeof businessSchema>;

interface BusinessCreationFormProps {
  categories: Array<{ id: string; name: string }>;
  nigerianStates: string[];
}

const STEPS = [
  { id: 1, name: "Basic Info", description: "Business details" },
  { id: 2, name: "Location", description: "Set your location" },
  { id: 3, name: "Contact", description: "Contact information" },
  { id: 4, name: "Review", description: "Review and create" },
];

export function BusinessCreationForm({
  categories,
  nigerianStates,
}: BusinessCreationFormProps) {
  const router = useRouter();
  const [currentStep, setCurrentStep] = useState(1);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const {
    register,
    handleSubmit,
    watch,
    setValue,
    formState: { errors },
  } = useForm<BusinessFormData>({
    resolver: zodResolver(businessSchema),
  });

  const selectedState = watch("state");

  const onSubmit = async (data: BusinessFormData) => {
    setIsSubmitting(true);
    setError(null);

    try {
      const business = await createBusiness({
        name: data.name,
        description: data.description,
        category_id: data.category_id,
        state: data.state,
        lga: data.lga,
        ward: data.ward,
        address: data.address,
        phone: data.phone,
        email: data.email,
        website: data.website || undefined,
        whatsapp: data.whatsapp,
      });

      // Redirect to business profile page
      router.push(`/business-profiles/${business.id}`);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to create business");
      setIsSubmitting(false);
    }
  };

  const nextStep = () => {
    if (currentStep < STEPS.length) {
      setCurrentStep(currentStep + 1);
    }
  };

  const prevStep = () => {
    if (currentStep > 1) {
      setCurrentStep(currentStep - 1);
    }
  };

  const canProceed = () => {
    switch (currentStep) {
      case 1:
        return watch("name") && watch("description") && watch("category_id");
      case 2:
        return watch("state") && watch("lga");
      case 3:
        return watch("phone") && watch("email");
      default:
        return true;
    }
  };

  const progress = (currentStep / STEPS.length) * 100;

  return (
    <div className="max-w-4xl mx-auto p-6">
      {/* Progress Bar */}
      <div className="mb-8">
        <div className="flex justify-between mb-4">
          {STEPS.map((step) => (
            <div
              key={step.id}
              className={`flex flex-col items-center ${
                step.id === currentStep
                  ? "text-naija-green"
                  : step.id < currentStep
                    ? "text-naija-green/70"
                    : "text-gray-400"
              }`}
            >
              <div
                className={`w-10 h-10 rounded-full flex items-center justify-center mb-2 ${
                  step.id === currentStep
                    ? "bg-naija-green text-white"
                    : step.id < currentStep
                      ? "bg-naija-green/70 text-white"
                      : "bg-gray-200 text-gray-400"
                }`}
              >
                {step.id}
              </div>
              <p className="text-sm font-medium">{step.name}</p>
              <p className="text-xs text-gray-500">{step.description}</p>
            </div>
          ))}
        </div>
        <Progress value={progress} className="h-2" />
      </div>

      {/* Error Display */}
      {error && (
        <div className="mb-4 p-4 bg-red-50 border border-red-200 rounded-lg text-red-600">
          {error}
        </div>
      )}

      {/* Form */}
      <form onSubmit={handleSubmit(onSubmit)} className="space-y-6">
        <AnimatePresence mode="wait">
          {/* Step 1: Basic Info */}
          {currentStep === 1 && (
            <motion.div
              key="step1"
              initial={{ opacity: 0, x: 20 }}
              animate={{ opacity: 1, x: 0 }}
              exit={{ opacity: 0, x: -20 }}
              className="space-y-6"
            >
              <div className="space-y-4">
                <div>
                  <Label htmlFor="name">
                    Business Name <span className="text-red-500">*</span>
                  </Label>
                  <div className="relative mt-1">
                    <Building2 className="absolute left-3 top-3 h-5 w-5 text-gray-400" />
                    <Input
                      id="name"
                      {...register("name")}
                      placeholder="Enter your business name"
                      className="pl-10"
                    />
                  </div>
                  {errors.name && (
                    <p className="text-sm text-red-500 mt-1">{errors.name.message}</p>
                  )}
                </div>

                <div>
                  <Label htmlFor="category_id">
                    Category <span className="text-red-500">*</span>
                  </Label>
                  <Select
                    onValueChange={(value) => setValue("category_id", value)}
                    defaultValue={watch("category_id")}
                  >
                    <SelectTrigger className="mt-1">
                      <SelectValue placeholder="Select a category" />
                    </SelectTrigger>
                    <SelectContent>
                      {categories.map((category) => (
                        <SelectItem key={category.id} value={category.id}>
                          {category.name}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                  {errors.category_id && (
                    <p className="text-sm text-red-500 mt-1">
                      {errors.category_id.message}
                    </p>
                  )}
                </div>

                <div>
                  <Label htmlFor="description">
                    Description <span className="text-red-500">*</span>
                  </Label>
                  <Textarea
                    id="description"
                    {...register("description")}
                    placeholder="Describe your business, products, and services..."
                    rows={5}
                    className="mt-1"
                  />
                  {errors.description && (
                    <p className="text-sm text-red-500 mt-1">
                      {errors.description.message}
                    </p>
                  )}
                </div>
              </div>
            </motion.div>
          )}

