"use client";

/**
 * Claim Business Form Component
 * Form for submitting business ownership claim with verification
 * Requirements: 23.2, 23.3, 23.4
 */

import { useState } from "react";
import { useRouter } from "next/navigation";
import { zodResolver } from "@hookform/resolvers/zod";
import { useForm } from "react-hook-form";
import * as z from "zod";
import { Button } from "@/components/ui/button";
import {
  Form,
  FormControl,
  FormDescription,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { toast } from "sonner";
import { Loader2, Upload, CheckCircle } from "lucide-react";

const claimFormSchema = z.object({
  claim_justification: z.string().min(50, "Please provide at least 50 characters explaining why you're claiming this business"),
  business_email: z.string().email("Please enter a valid business email address"),
  domain: z.string().optional().refine((val) => {
    if (!val) return true;
    return /^([a-z0-9]+(-[a-z0-9]+)*\.)+[a-z]{2,}$/i.test(val);
  }, "Please enter a valid domain (e.g., example.com)"),
});

type ClaimFormValues = z.infer<typeof claimFormSchema>;

interface ClaimBusinessFormProps {
  businessId: string;
  businessName: string;
  onSuccess?: () => void;
}

export function ClaimBusinessForm({
  businessId,
  businessName,
  onSuccess,
}: ClaimBusinessFormProps) {
  const router = useRouter();
  const [loading, setLoading] = useState(false);
  const [uploadedDocs, setUploadedDocs] = useState<{
    business_registration?: File;
    tax_id?: File;
  }>({});

  const form = useForm<ClaimFormValues>({
    resolver: zodResolver(claimFormSchema),
    defaultValues: {
      claim_justification: "",
      business_email: "",
      domain: "",
    },
  });

  const handleDocumentUpload = (type: "business_registration" | "tax_id") => (
    e: React.ChangeEvent<HTMLInputElement>
  ) => {
    const file = e.target.files?.[0];
    if (file) {
      // Validate file size (max 5MB)
      if (file.size > 5 * 1024 * 1024) {
        toast.error("File size must be less than 5MB");
        return;
      }

      // Validate file type
      const allowedTypes = ["application/pdf", "image/jpeg", "image/png", "image/jpg"];
      if (!allowedTypes.includes(file.type)) {
        toast.error("Only PDF, JPEG, and PNG files are allowed");
        return;
      }

      setUploadedDocs((prev) => ({ ...prev, [type]: file }));
      toast.success(`${type === "business_registration" ? "Business registration" : "Tax ID"} document uploaded`);
    }
  };

  const onSubmit = async (values: ClaimFormValues) => {
    setLoading(true);

    try {
      // Submit claim request
      const response = await fetch("/api/business-claims", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          business_profile_id: businessId,
          claim_justification: values.claim_justification,
          business_email: values.business_email,
          domain: values.domain || null,
        }),
      });

      if (!response.ok) {
        const error = await response.json();
        throw new Error(error.error || "Failed to submit claim");
      }

      const { claim } = await response.json();

      // Upload documents if provided
      if (uploadedDocs.business_registration || uploadedDocs.tax_id) {
        const uploads = [];

        if (uploadedDocs.business_registration) {
          uploads.push(
            fetch(`/api/business-claims/${claim.id}/documents`, {
              method: "POST",
              body: (() => {
                const formData = new FormData();
                formData.append("document_type", "business_registration");
                formData.append("file", uploadedDocs.business_registration);
                return formData;
              })(),
            })
          );
        }

        if (uploadedDocs.tax_id) {
          uploads.push(
            fetch(`/api/business-claims/${claim.id}/documents`, {
              method: "POST",
              body: (() => {
                const formData = new FormData();
                formData.append("document_type", "tax_id");
                formData.append("file", uploadedDocs.tax_id);
                return formData;
              })(),
            })
          );
        }

        await Promise.all(uploads);
      }

      toast.success(
        "Claim submitted successfully! Check your email to verify ownership.",
        { duration: 5000 }
      );

      onSuccess?.();
      router.refresh();
    } catch (error) {
      console.error("Claim submission error:", error);
      toast.error(
        error instanceof Error ? error.message : "Failed to submit claim"
      );
    } finally {
      setLoading(false);
    }
  };

  return (
    <Form {...form}>
      <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-6">
        <FormField
          control={form.control}
          name="business_email"
          render={({ field }) => (
            <FormItem>
              <FormLabel>Business Email *</FormLabel>
              <FormControl>
                <Input
                  placeholder="contact@example.com"
                  {...field}
                  disabled={loading}
                />
              </FormControl>
              <FormDescription>
                We'll send a verification email to this address
              </FormDescription>
              <FormMessage />
            </FormItem>
          )}
        />

        <FormField
          control={form.control}
          name="domain"
          render={({ field }) => (
            <FormItem>
              <FormLabel>Business Website (Optional)</FormLabel>
              <FormControl>
                <Input
                  placeholder="example.com"
                  {...field}
                  disabled={loading}
                />
              </FormControl>
              <FormDescription>
                Your business domain for additional verification
              </FormDescription>
              <FormMessage />
            </FormItem>
          )}
        />

        <FormField
          control={form.control}
          name="claim_justification"
          render={({ field }) => (
            <FormItem>
              <FormLabel>Why are you claiming this business? *</FormLabel>
              <FormControl>
                <Textarea
                  placeholder="I am the owner/manager of this business and can provide verification documents..."
                  rows={5}
                  {...field}
                  disabled={loading}
                />
              </FormControl>
              <FormDescription>
                Explain your relationship to this business (minimum 50 characters)
              </FormDescription>
              <FormMessage />
            </FormItem>
          )}
        />

        <div className="space-y-4">
          <div className="border-t pt-4">
            <h4 className="text-sm font-medium mb-3">
              Verification Documents (Optional but recommended)
            </h4>

            <div className="space-y-3">
              <div>
                <label className="text-sm font-medium text-muted-foreground mb-1 block">
                  Business Registration Document
                </label>
                <Input
                  type="file"
                  accept=".pdf,.jpg,.jpeg,.png"
                  onChange={handleDocumentUpload("business_registration")}
                  disabled={loading}
                  className="cursor-pointer"
                />
                {uploadedDocs.business_registration && (
                  <p className="text-xs text-green-600 mt-1 flex items-center">
                    <CheckCircle className="h-3 w-3 mr-1" />
                    {uploadedDocs.business_registration.name}
                  </p>
                )}
              </div>

              <div>
                <label className="text-sm font-medium text-muted-foreground mb-1 block">
                  Tax ID Document
                </label>
                <Input
                  type="file"
                  accept=".pdf,.jpg,.jpeg,.png"
                  onChange={handleDocumentUpload("tax_id")}
                  disabled={loading}
                  className="cursor-pointer"
                />
                {uploadedDocs.tax_id && (
                  <p className="text-xs text-green-600 mt-1 flex items-center">
                    <CheckCircle className="h-3 w-3 mr-1" />
                    {uploadedDocs.tax_id.name}
                  </p>
                )}
              </div>
            </div>

            <p className="text-xs text-muted-foreground mt-2">
              Accepted formats: PDF, JPEG, PNG (max 5MB per file)
            </p>
          </div>
        </div>

        <div className="flex items-center gap-3 pt-4">
          <Button type="submit" disabled={loading} className="flex-1">
            {loading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
            Submit Claim
          </Button>
        </div>

        <div className="text-xs text-muted-foreground space-y-1 bg-muted/50 p-3 rounded">
          <p className="font-medium">What happens next?</p>
          <ol className="list-decimal list-inside space-y-1 ml-2">
            <li>We'll send a verification email to your business email</li>
            <li>Our team will review your claim and documents</li>
            <li>You'll be notified within 3-5 business days</li>
            <li>Once approved, you'll have full control of this profile</li>
          </ol>
        </div>
      </form>
    </Form>
  );
}

"use client";

import { useEffect, useState } from "react";
import { fetchWithCacheFallback } from "@/lib/errors";
import { AlertTriangle, RefreshCw, Clock } from "lucide-react";
import { Button } from "@/components/ui/button";

interface DataWithCacheFallbackProps<T> {
  /**
   * Unique cache key for this data
   */
  cacheKey: string;

  /**
   * Function to fetch fresh data
   */
  fetchData: () => Promise<T>;

  /**
   * Cache TTL in milliseconds (default: 5 minutes)
   */
  cacheTTL?: number;

  /**
   * Render function for the data
   */
  children: (data: T, isStale: boolean) => React.ReactNode;

  /**
   * Loading component
   */
  loadingComponent?: React.ReactNode;

  /**
   * Error component (when no cache available)
   */
  errorComponent?: (error: Error, retry: () => void) => React.ReactNode;

  /**
   * Show stale data warning
   */
  showStaleWarning?: boolean;
}

/**
 * Component that fetches data with automatic cache fallback
 * Implements Requirement 19.4: Display cached content when API fails
 */
export function DataWithCacheFallback<T>({
  cacheKey,
  fetchData,
  cacheTTL = 5 * 60 * 1000,
  children,
  loadingComponent,
  errorComponent,
  showStaleWarning = true,
}: DataWithCacheFallbackProps<T>) {
  const [data, setData] = useState<T | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<Error | null>(null);
  const [isFromCache, setIsFromCache] = useState(false);

  const loadData = async () => {
    setIsLoading(true);
    setError(null);

    try {
      const result = await fetchWithCacheFallback(fetchData, {
        key: cacheKey,
        ttl: cacheTTL,
      });

      setData(result.data);
      setIsFromCache(result.fromCache);
    } catch (err) {
      setError(err as Error);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    loadData();
  }, [cacheKey]);

  if (isLoading && !data) {
    return (
      <>
        {loadingComponent || (
          <div className="flex items-center justify-center p-8">
            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-[#00ff41]" />
          </div>
        )}
      </>
    );
  }

  if (error && !data) {
    return (
      <>
        {errorComponent ? (
          errorComponent(error, loadData)
        ) : (
          <div className="bg-red-500/10 backdrop-blur-sm border border-red-500/20 rounded-lg p-6">
            <div className="flex items-start gap-4">
              <div className="bg-red-500/10 p-2 rounded border border-red-500/20">
                <AlertTriangle className="w-5 h-5 text-red-500" />
              </div>
              <div className="flex-1 space-y-3">
                <div>
                  <p className="text-sm font-medium text-white">
                    Failed to load data
                  </p>
                  <p className="text-xs text-gray-400 mt-1">
                    We couldn't fetch the latest data. Please try again.
                  </p>
                </div>
                <Button
                  onClick={loadData}
                  size="sm"
                  className="bg-[#00ff41] hover:bg-[#00cc33] text-black"
                >
                  <RefreshCw className="w-4 h-4 mr-2" />
                  Retry
                </Button>
              </div>
            </div>
          </div>
        )}
      </>
    );
  }

  if (!data) {
    return null;
  }

  return (
    <div className="relative">
      {isFromCache && showStaleWarning && (
        <div className="mb-4 bg-yellow-500/10 backdrop-blur-sm border border-yellow-500/20 rounded-lg p-3">
          <div className="flex items-start gap-3">
            <Clock className="w-4 h-4 text-yellow-500 mt-0.5" />
            <div className="flex-1">
              <p className="text-sm text-yellow-500">
                Showing cached content
              </p>
              <p className="text-xs text-gray-400 mt-1">
                We're having trouble connecting to the server. This data may be outdated.
              </p>
            </div>
            <Button
              onClick={loadData}
              size="sm"
              variant="ghost"
              className="text-yellow-500 hover:text-yellow-400 hover:bg-yellow-500/10"
            >
              <RefreshCw className="w-3 h-3 mr-1" />
              Refresh
            </Button>
          </div>
        </div>
      )}
      {children(data, isFromCache)}
    </div>
  );
}

/**
 * Error Boundary Component
 * Implements Requirements 19.5, 19.6, 19.7, 19.8
 * 
 * Catches React component errors and displays user-friendly fallback UI.
 * Integrates with Sentry for error tracking with full context.
 */

"use client";

import React from "react";
import * as Sentry from "@sentry/nextjs";
import { AlertTriangle, RefreshCw, Home } from "lucide-react";
import { Button } from "@/components/ui/button";
import Link from "next/link";

interface ErrorBoundaryProps {
  children: React.ReactNode;
  fallback?: React.ComponentType<ErrorFallbackProps>;
  onError?: (error: Error, errorInfo: React.ErrorInfo) => void;
}

interface ErrorBoundaryState {
  hasError: boolean;
  error: Error | null;
  errorInfo: React.ErrorInfo | null;
}

export interface ErrorFallbackProps {
  error: Error | null;
  errorInfo: React.ErrorInfo | null;
  resetError: () => void;
}

/**
 * Error Boundary class component that catches errors in child components
 * Requirement 19.5: Implement error boundaries to prevent full page crashes
 */
export class ErrorBoundary extends React.Component<
  ErrorBoundaryProps,
  ErrorBoundaryState
> {
  constructor(props: ErrorBoundaryProps) {
    super(props);
    this.state = { hasError: false, error: null, errorInfo: null };
  }

  /**
   * Update state when an error is caught
   */
  static getDerivedStateFromError(error: Error): Partial<ErrorBoundaryState> {
    return { hasError: true, error };
  }

  /**
   * Log error to Sentry and call custom error handler
   * Requirement 19.6: Log errors to error tracking service (Sentry) with context
   * Requirement 33.6: Log errors with context (user ID, session, stack trace)
   */
  componentDidCatch(error: Error, errorInfo: React.ErrorInfo) {
    // Update state with error info
    this.setState({ errorInfo });

    // Log to console for development
    if (process.env.NODE_ENV === "development") {
      console.error("Error caught by boundary:", error);
      console.error("Component stack:", errorInfo.componentStack);
    }

    // Requirement 33.6: Log to Sentry with full context
    Sentry.captureException(error, {
      contexts: {
        react: {
          componentStack: errorInfo.componentStack,
        },
      },
      tags: {
        errorBoundary: "true",
        component: this.extractComponentName(errorInfo.componentStack),
      },
      level: "error",
    });

    // Call custom error handler if provided
    if (this.props.onError) {
      this.props.onError(error, errorInfo);
    }
  }

  /**
   * Extract component name from stack trace for better error context
   */
  private extractComponentName(componentStack: string | null): string {
    if (!componentStack) return "unknown";
    
    const match = componentStack.match(/^\s+at\s+(\w+)/);
    return match ? match[1] : "unknown";
  }

  /**
   * Reset error state to retry rendering
   * Requirement 19.8: Provide retry and recovery options
   */
  resetError = () => {
    this.setState({ hasError: false, error: null, errorInfo: null });
  };

  render() {
    if (this.state.hasError) {
      const FallbackComponent = this.props.fallback || DefaultErrorFallback;
      return (
        <FallbackComponent
          error={this.state.error}
          errorInfo={this.state.errorInfo}
          resetError={this.resetError}
        />
      );
    }

    return this.props.children;
  }
}

/**
 * Default error fallback component
 * Requirement 19.7: Display user-friendly error messages without technical jargon
 * Requirement 19.8: Provide actionable recovery options (retry, refresh, contact support)
 */
function DefaultErrorFallback({ 
  error, 
  errorInfo, 
  resetError 
}: ErrorFallbackProps) {
  return (
    <div className="min-h-screen flex items-center justify-center p-4 bg-gradient-to-br from-gray-900 via-black to-gray-900">
      <div className="max-w-md w-full">
        <div className="bg-gray-900/50 backdrop-blur-xl border border-red-500/20 rounded-2xl p-8 shadow-2xl">
          <div className="flex flex-col items-center text-center space-y-6">
            {/* Error Icon */}
            <div className="relative">
              <div className="absolute inset-0 bg-red-500/20 blur-2xl rounded-full" />
              <div className="relative bg-red-500/10 p-4 rounded-full border border-red-500/30">
                <AlertTriangle className="w-12 h-12 text-red-500" />
              </div>
            </div>

            {/* Error Message - User-friendly, no technical jargon */}
