  // Form state
  const [formData, setFormData] = useState({
    business_name: '',
    business_description: '',
    contact_email: '',
    contact_phone: '',
  });

  // Real-time validation for touched fields
  useEffect(() => {
    if (touchedFields.size === 0) return;

    const errors: FieldError = {};

    touchedFields.forEach((field) => {
      try {
        // Validate individual field
        const fieldSchema = vendorApplicationSchema.shape[field as keyof typeof vendorApplicationSchema.shape];
        fieldSchema.parse(formData[field as keyof typeof formData]);
      } catch (error) {
        if (error instanceof z.ZodError) {
          errors[field as keyof FieldError] = error.errors[0].message;
        }
      }
    });

    setFieldErrors(errors);
  }, [formData, touchedFields]);

  const handleBlur = (fieldName: string) => {
    setTouchedFields((prev) => new Set([...prev, fieldName]));
  };

  const handleChange = (
    e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>
  ) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));

    // Clear server error when user starts typing
    if (serverError) {
      setServerError(null);
    }
  };

  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();

    // Clear previous messages
    setServerError(null);
    setSuccessMessage(null);

    // Mark all fields as touched for validation display
    setTouchedFields(new Set(['business_name', 'business_description', 'contact_email', 'contact_phone']));

    // Validate all fields
    const validation = vendorApplicationSchema.safeParse(formData);

    if (!validation.success) {
      const errors: FieldError = {};
      validation.error.errors.forEach((err) => {
        const field = err.path[0] as keyof FieldError;
        if (!errors[field]) {
          errors[field] = err.message;
        }
      });
      setFieldErrors(errors);
      return;
    }

    // Submit form
    setIsSubmitting(true);

    try {
      const formDataObj = new FormData();
      formDataObj.append('business_name', formData.business_name);
      formDataObj.append('business_description', formData.business_description);
      formDataObj.append('contact_email', formData.contact_email);
      formDataObj.append('contact_phone', formData.contact_phone);

      const result = await submitVendorApplicationAction(formDataObj);

      if (result.success) {
        const message = 'Your vendor application has been submitted successfully! We will review it and get back to you soon.';
        setSuccessMessage(message);
        toastSuccess('Application submitted', 'We will review it and get back to you soon');

        // Redirect after 2 seconds
        setTimeout(() => {
          router.push('/profile');
        }, 2000);
      } else {
        const errorMsg = result.error || 'Failed to submit application. Please try again.';
        setServerError(errorMsg);
        toastError('Submission failed', errorMsg);
      }
    } catch (error) {
      console.error('Unexpected error during vendor application:', error);
      const errorMsg = 'An unexpected error occurred. Please try again.';
      setServerError(errorMsg);
      toastError('Submission failed', errorMsg);
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <form
      onSubmit={handleSubmit}
      className={`space-y-6 ${className || ''}`}
      noValidate
    >
      {/* Server Error Message */}
      {serverError && (
        <div
          className="bg-red-50 border border-red-200 text-red-800 px-4 py-3 rounded-lg"
          role="alert"
        >
          <p className="font-medium">Error</p>
          <p className="text-sm">{serverError}</p>
        </div>
      )}

      {/* Success Message */}
      {successMessage && (
        <div
          className="bg-green-50 border border-green-200 text-green-800 px-4 py-3 rounded-lg"
          role="alert"
        >
          <p className="font-medium">Success!</p>
          <p className="text-sm">{successMessage}</p>
        </div>
      )}

      {/* Business Name */}
      <div>
        <label
          htmlFor="business_name"
          className="block text-sm font-medium text-gray-700 mb-2"
        >
          Business Name <span className="text-red-500">*</span>
        </label>
        <input
          type="text"
          id="business_name"
          name="business_name"
          value={formData.business_name}
          onChange={handleChange}
          onBlur={() => handleBlur('business_name')}
          disabled={isSubmitting}
          className={`w-full px-4 py-3 rounded-lg border ${
            fieldErrors.business_name && touchedFields.has('business_name')
              ? 'border-red-300 focus:border-red-500 focus:ring-red-500'
              : 'border-gray-300 focus:border-blue-500 focus:ring-blue-500'
          } focus:outline-none focus:ring-2 disabled:bg-gray-100 disabled:cursor-not-allowed`}
          placeholder="Enter your business name"
          aria-invalid={!!fieldErrors.business_name && touchedFields.has('business_name')}
          aria-describedby={fieldErrors.business_name ? 'business_name-error' : undefined}
        />
        {fieldErrors.business_name && touchedFields.has('business_name') && (
          <p
            id="business_name-error"
            className="mt-1 text-sm text-red-600"
            role="alert"
          >
            {fieldErrors.business_name}
          </p>
        )}
      </div>

      {/* Business Description */}
      <div>
        <label
          htmlFor="business_description"
          className="block text-sm font-medium text-gray-700 mb-2"
        >
          Business Description <span className="text-red-500">*</span>
        </label>
        <textarea
          id="business_description"
          name="business_description"
          value={formData.business_description}
          onChange={handleChange}
          onBlur={() => handleBlur('business_description')}
          disabled={isSubmitting}
          rows={5}
          className={`w-full px-4 py-3 rounded-lg border ${
            fieldErrors.business_description && touchedFields.has('business_description')
              ? 'border-red-300 focus:border-red-500 focus:ring-red-500'
              : 'border-gray-300 focus:border-blue-500 focus:ring-blue-500'
          } focus:outline-none focus:ring-2 disabled:bg-gray-100 disabled:cursor-not-allowed resize-none`}
          placeholder="Describe your business, services, and what makes you unique (20-500 characters)"
          aria-invalid={!!fieldErrors.business_description && touchedFields.has('business_description')}
          aria-describedby={fieldErrors.business_description ? 'business_description-error' : undefined}
        />
        <div className="mt-1 flex justify-between items-start">
          {fieldErrors.business_description && touchedFields.has('business_description') ? (
            <p
              id="business_description-error"
              className="text-sm text-red-600"
              role="alert"
            >
              {fieldErrors.business_description}
            </p>
          ) : (
            <p className="text-sm text-gray-500">
              {formData.business_description.length}/500 characters
            </p>
          )}
        </div>
      </div>

      {/* Contact Email */}
      <div>
        <label
          htmlFor="contact_email"
          className="block text-sm font-medium text-gray-700 mb-2"
        >
          Contact Email <span className="text-red-500">*</span>
        </label>
        <input
          type="email"
          id="contact_email"
          name="contact_email"
          value={formData.contact_email}
          onChange={handleChange}
          onBlur={() => handleBlur('contact_email')}
          disabled={isSubmitting}
          className={`w-full px-4 py-3 rounded-lg border ${
            fieldErrors.contact_email && touchedFields.has('contact_email')
              ? 'border-red-300 focus:border-red-500 focus:ring-red-500'
              : 'border-gray-300 focus:border-blue-500 focus:ring-blue-500'
          } focus:outline-none focus:ring-2 disabled:bg-gray-100 disabled:cursor-not-allowed`}
          placeholder="your.email@example.com"
          aria-invalid={!!fieldErrors.contact_email && touchedFields.has('contact_email')}
          aria-describedby={fieldErrors.contact_email ? 'contact_email-error' : undefined}
        />
        {fieldErrors.contact_email && touchedFields.has('contact_email') && (
          <p
            id="contact_email-error"
            className="mt-1 text-sm text-red-600"
            role="alert"
          >
            {fieldErrors.contact_email}
          </p>
        )}
      </div>

      {/* Contact Phone */}
      <div>
        <label
          htmlFor="contact_phone"
          className="block text-sm font-medium text-gray-700 mb-2"
        >
          Contact Phone <span className="text-red-500">*</span>
        </label>
        <input
          type="tel"
          id="contact_phone"
          name="contact_phone"
          value={formData.contact_phone}
          onChange={handleChange}
          onBlur={() => handleBlur('contact_phone')}
          disabled={isSubmitting}
          className={`w-full px-4 py-3 rounded-lg border ${
            fieldErrors.contact_phone && touchedFields.has('contact_phone')
              ? 'border-red-300 focus:border-red-500 focus:ring-red-500'
              : 'border-gray-300 focus:border-blue-500 focus:ring-blue-500'
          } focus:outline-none focus:ring-2 disabled:bg-gray-100 disabled:cursor-not-allowed`}
          placeholder="+234XXXXXXXXXX or 0XXXXXXXXXX"
          aria-invalid={!!fieldErrors.contact_phone && touchedFields.has('contact_phone')}
          aria-describedby={fieldErrors.contact_phone ? 'contact_phone-error contact_phone-help' : 'contact_phone-help'}
        />
        {fieldErrors.contact_phone && touchedFields.has('contact_phone') ? (
          <p
            id="contact_phone-error"
            className="mt-1 text-sm text-red-600"
            role="alert"
          >
            {fieldErrors.contact_phone}
          </p>
        ) : (
          <p
            id="contact_phone-help"
            className="mt-1 text-sm text-gray-500"
          >
            Nigerian phone format: +234XXXXXXXXXX or 0XXXXXXXXXX
          </p>
        )}
      </div>

      {/* Submit Button */}
      <div className="pt-4">
        <button
          type="submit"
          disabled={isSubmitting}
          className="w-full bg-blue-600 hover:bg-blue-700 text-white font-medium px-6 py-3 rounded-lg transition-colors disabled:bg-gray-400 disabled:cursor-not-allowed focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2"
        >
          {isSubmitting ? (
            <span className="flex items-center justify-center">
              <svg
                className="animate-spin -ml-1 mr-3 h-5 w-5 text-white"
                xmlns="http://www.w3.org/2000/svg"
                fill="none"
                viewBox="0 0 24 24"
                aria-hidden="true"
              >
                <circle
                  className="opacity-25"
                  cx="12"
                  cy="12"
                  r="10"
                  stroke="currentColor"
                  strokeWidth="4"
                />
                <path
                  className="opacity-75"
                  fill="currentColor"
                  d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"
                />
              </svg>
              Submitting...
            </span>
          ) : (
            'Submit Application'
          )}
        </button>
      </div>

      {/* Info Text */}
      <p className="text-sm text-gray-600 text-center">
        Your application will be reviewed by our team. You'll receive an email notification once it's been processed.
      </p>
    </form>
  );
}

'use client';

/**
 * GDPR Cookie Consent Banner
 * Requirements: 18.9, 30.10, 31.6, 31.7, 31.8
 */

import { useState, useEffect } from 'react';
import { X } from 'lucide-react';
import { Button } from '@/components/ui/button';
import {
  getCookieConsent,
  setCookieConsent,
  CookieConsentPreferences,
} from '@/lib/gdpr/cookie-consent';

export function CookieConsentBanner() {
  const [showBanner, setShowBanner] = useState(false);
  const [showDetails, setShowDetails] = useState(false);
  const [preferences, setPreferences] = useState<CookieConsentPreferences>({
    necessary: true,
    analytics: false,
    marketing: false,
    functional: false,
  });

  useEffect(() => {
    // Check if user has already given consent
    const consent = getCookieConsent();
    if (!consent) {
      // Delay showing banner to avoid CLS
      setTimeout(() => setShowBanner(true), 1000);
    }
  }, []);

  const handleAcceptAll = () => {
    const allConsent: CookieConsentPreferences = {
      necessary: true,
      analytics: true,
      marketing: true,
      functional: true,
    };

    setCookieConsent(allConsent);
    setShowBanner(false);
  };

  const handleAcceptSelected = () => {
    setCookieConsent(preferences);
    setShowBanner(false);
  };

  const handleRejectAll = () => {
    const minimalConsent: CookieConsentPreferences = {
      necessary: true,
      analytics: false,
      marketing: false,
      functional: false,
    };

    setCookieConsent(minimalConsent);
    setShowBanner(false);
  };

  if (!showBanner) return null;

  return (
    <div
      className="fixed bottom-0 left-0 right-0 z-50 bg-background border-t shadow-lg"
      role="dialog"
      aria-labelledby="cookie-consent-title"
      aria-describedby="cookie-consent-description"
    >
      <div className="container mx-auto px-4 py-6 max-w-6xl">
        <div className="flex flex-col gap-4">
          <div className="flex items-start justify-between gap-4">
            <div className="flex-1">
              <h2
                id="cookie-consent-title"
                className="text-lg font-semibold mb-2"
              >
                We value your privacy
              </h2>
              <p
                id="cookie-consent-description"
                className="text-sm text-muted-foreground mb-4"
              >
                We use cookies to enhance your browsing experience, analyze site
                traffic, and personalize content. By clicking "Accept All", you
                consent to our use of cookies.
              </p>
            </div>
            <button
              onClick={() => setShowBanner(false)}
              className="text-muted-foreground hover:text-foreground p-1"
              aria-label="Dismiss cookie banner"
            >
              <X className="h-5 w-5" />
            </button>
          </div>

          {showDetails && (
            <div className="space-y-3 pb-4 border-t pt-4">
              <div className="flex items-center justify-between">
                <div>
                  <p className="font-medium text-sm">Necessary Cookies</p>
                  <p className="text-xs text-muted-foreground">
                    Required for basic site functionality
                  </p>
                </div>
                <input
                  type="checkbox"
                  checked={preferences.necessary}
                  disabled
                  className="h-4 w-4"
                  aria-label="Necessary cookies (required)"
                />
              </div>

              <div className="flex items-center justify-between">
                <div>
                  <p className="font-medium text-sm">Analytics Cookies</p>
                  <p className="text-xs text-muted-foreground">
                    Help us improve by tracking site usage
                  </p>
                </div>
                <input
                  type="checkbox"
                  checked={preferences.analytics}
                  onChange={(e) =>
                    setPreferences({ ...preferences, analytics: e.target.checked })
                  }
                  className="h-4 w-4"
                  aria-label="Analytics cookies"
                />
              </div>

              <div className="flex items-center justify-between">
                <div>
                  <p className="font-medium text-sm">Marketing Cookies</p>
                  <p className="text-xs text-muted-foreground">
                    Used for personalized advertising
                  </p>
                </div>
                <input
                  type="checkbox"
                  checked={preferences.marketing}
                  onChange={(e) =>
                    setPreferences({ ...preferences, marketing: e.target.checked })
                  }
                  className="h-4 w-4"
                  aria-label="Marketing cookies"
                />
              </div>

              <div className="flex items-center justify-between">
                <div>
                  <p className="font-medium text-sm">Functional Cookies</p>
                  <p className="text-xs text-muted-foreground">
                    Enable enhanced functionality and personalization
                  </p>
                </div>
                <input
                  type="checkbox"
                  checked={preferences.functional}
                  onChange={(e) =>
                    setPreferences({ ...preferences, functional: e.target.checked })
                  }
                  className="h-4 w-4"
                  aria-label="Functional cookies"
                />
              </div>
            </div>
          )}

          <div className="flex flex-wrap gap-2 items-center">
            <Button onClick={handleAcceptAll} size="sm">
              Accept All
            </Button>
            <Button
              onClick={handleRejectAll}
              variant="outline"
              size="sm"
            >
              Reject All
            </Button>
            {showDetails ? (
              <Button
                onClick={handleAcceptSelected}
                variant="secondary"
                size="sm"
              >
                Save Preferences
              </Button>
            ) : (
              <Button
                onClick={() => setShowDetails(true)}
                variant="ghost"
                size="sm"
              >
                Customize
              </Button>
            )}
            <a
              href="/privacy"
              className="text-sm text-muted-foreground hover:text-foreground underline ml-auto"
            >
              Privacy Policy
            </a>
          </div>
        </div>
      </div>
    </div>
  );
}

'use client';

/**
 * Privacy Settings Component
 * Requirements: 18.9, 30.10, 31.6, 31.7, 31.8
 * 
 * Provides comprehensive GDPR compliance controls:
 * - Cookie consent management
 * - Data export (Right to Data Portability - Article 20)
 * - Data deletion (Right to be Forgotten - Article 17)
 * - Privacy preferences management
 */

import { useState } from 'react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert';
import { Download, Trash2, Shield, Cookie, AlertTriangle, CheckCircle } from 'lucide-react';
import { getCookieConsent, setCookieConsent, type CookieConsentPreferences } from '@/lib/gdpr/cookie-consent';
import { toast } from 'sonner';

interface PrivacySettingsProps {
  userId: string;
  userEmail: string;
  deletionScheduledAt: string | null;
  accountStatus: string;
}

export function PrivacySettings({
  userId,
  userEmail,
  deletionScheduledAt,
  accountStatus,
}: PrivacySettingsProps) {
  const [isExporting, setIsExporting] = useState(false);
  const [isSchedulingDeletion, setIsSchedulingDeletion] = useState(false);
  const [isCancellingDeletion, setIsCancellingDeletion] = useState(false);
  const [showDeletionConfirm, setShowDeletionConfirm] = useState(false);

  // Get current cookie preferences
  const currentConsent = getCookieConsent() || {
    necessary: true,
    analytics: false,
    marketing: false,
    functional: false,
  };

  const [cookiePreferences, setCookiePreferences] = useState<CookieConsentPreferences>(currentConsent);

  const handleExportData = async (format: 'json' | 'csv') => {
    setIsExporting(true);
    try {
      // Open the export endpoint in a new window to trigger download
      window.open(`/api/gdpr/export?format=${format}`, '_blank');

      toast.success('Data Export Started', {
        description: `Your data is being prepared for download in ${format.toUpperCase()} format.`,
      });
    } catch (error) {
      toast.error('Export Failed', {
        description: 'Failed to export your data. Please try again.',
      });
    } finally {
      setIsExporting(false);
    }
  };

  const handleScheduleDeletion = async () => {
    setIsSchedulingDeletion(true);
    try {
      const response = await fetch('/api/gdpr/delete', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'schedule', gracePeriodDays: 30 }),
      });

      if (!response.ok) {
        throw new Error('Failed to schedule deletion');
      }

      const data = await response.json();

      toast.success('Deletion Scheduled', {
        description: `Your account will be permanently deleted on ${new Date(data.scheduledDate).toLocaleDateString()}. You have 30 days to cancel this request.`,
      });

      // Reload the page to show updated status
      window.location.reload();
    } catch (error) {
      toast.error('Deletion Failed', {
        description: 'Failed to schedule account deletion. Please try again.',
      });
    } finally {
      setIsSchedulingDeletion(false);
      setShowDeletionConfirm(false);
    }
  };

  const handleCancelDeletion = async () => {
    setIsCancellingDeletion(true);
    try {
      const response = await fetch('/api/gdpr/delete', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'cancel' }),
      });

      if (!response.ok) {
        throw new Error('Failed to cancel deletion');
      }

      toast.success('Deletion Cancelled', {
        description: 'Your account deletion request has been cancelled successfully.',
      });

      // Reload the page to show updated status
      window.location.reload();
    } catch (error) {
      toast.error('Cancellation Failed', {
        description: 'Failed to cancel account deletion. Please try again.',
      });
    } finally {
      setIsCancellingDeletion(false);
    }
  };

  const handleUpdateCookiePreferences = () => {
    setCookieConsent(cookiePreferences);
    toast.success('Preferences Saved', {
      description: 'Your cookie preferences have been updated.',
    });
  };

  return (
    <div className="space-y-6">
      {/* Deletion Scheduled Alert */}
      {deletionScheduledAt && accountStatus === 'deletion_scheduled' && (
        <Alert className="border-destructive">
          <AlertTriangle className="h-4 w-4" />
          <AlertTitle>Account Deletion Scheduled</AlertTitle>
          <AlertDescription>
            Your account is scheduled for deletion on {new Date(deletionScheduledAt).toLocaleDateString()}.
            <div className="mt-2">
              <Button
                variant="outline"
                size="sm"
                onClick={handleCancelDeletion}
                disabled={isCancellingDeletion}
              >
                {isCancellingDeletion ? 'Cancelling...' : 'Cancel Deletion'}
              </Button>
            </div>
          </AlertDescription>
        </Alert>
      )}

      {/* Cookie Preferences */}
      <Card>
        <CardHeader>
          <div className="flex items-center gap-2">
            <Cookie className="h-5 w-5" />
            <CardTitle>Cookie Preferences</CardTitle>
          </div>
          <CardDescription>
            Manage your cookie and tracking preferences. Changes take effect immediately.
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="space-y-3">
            <div className="flex items-center justify-between">
              <div>
                <p className="font-medium text-sm">Necessary Cookies</p>
                <p className="text-xs text-muted-foreground">
                  Required for basic site functionality (always enabled)
                </p>
              </div>
              <input
                type="checkbox"
                checked={cookiePreferences.necessary}
                disabled
                className="h-4 w-4"
                aria-label="Necessary cookies (required)"
              />
            </div>

            <div className="flex items-center justify-between">
              <div>
                <p className="font-medium text-sm">Analytics Cookies</p>
                <p className="text-xs text-muted-foreground">
                  Help us improve by tracking site usage
                </p>
              </div>
              <input
                type="checkbox"
                checked={cookiePreferences.analytics}
                onChange={(e) =>
                  setCookiePreferences({ ...cookiePreferences, analytics: e.target.checked })
                }
                className="h-4 w-4"
                aria-label="Analytics cookies"
              />
            </div>

            <div className="flex items-center justify-between">
              <div>
                <p className="font-medium text-sm">Marketing Cookies</p>
                <p className="text-xs text-muted-foreground">
                  Used for personalized advertising
                </p>
              </div>
              <input
                type="checkbox"
                checked={cookiePreferences.marketing}
                onChange={(e) =>
                  setCookiePreferences({ ...cookiePreferences, marketing: e.target.checked })
                }
                className="h-4 w-4"
                aria-label="Marketing cookies"
              />
            </div>

            <div className="flex items-center justify-between">
              <div>
                <p className="font-medium text-sm">Functional Cookies</p>
                <p className="text-xs text-muted-foreground">
                  Enable enhanced functionality and personalization
                </p>
              </div>
              <input
                type="checkbox"
                checked={cookiePreferences.functional}
                onChange={(e) =>
                  setCookiePreferences({ ...cookiePreferences, functional: e.target.checked })
                }
                className="h-4 w-4"
                aria-label="Functional cookies"
              />
            </div>
          </div>

          <Button onClick={handleUpdateCookiePreferences} className="w-full">
            Save Cookie Preferences
          </Button>
        </CardContent>
      </Card>

      {/* Data Export */}
      <Card>
        <CardHeader>
          <div className="flex items-center gap-2">
            <Download className="h-5 w-5" />
            <CardTitle>Export Your Data</CardTitle>
          </div>
          <CardDescription>
            Download all your personal data in a portable format (GDPR Article 20: Right to Data Portability)
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="space-y-2">
            <p className="text-sm text-muted-foreground">
              Your data export includes:
            </p>
            <ul className="text-sm text-muted-foreground list-disc list-inside space-y-1">
              <li>Profile information</li>
              <li>Listings you've created</li>
              <li>Reviews you've written</li>
              <li>Saved items and interactions</li>
