"use client";

import { useState, useEffect, useRef, useCallback } from "react";
import { motion, AnimatePresence, useReducedMotion } from "framer-motion";
import { Search, X, Loader2, TrendingUp, Package, User } from "lucide-react";
import { cn } from "@/lib/utils";
import type { HeroSearchBarProps, AutocompleteResult } from "./types";

/**
 * HeroSearchBar Component
 * 
 * Prominent search bar with semantic and keyword autocomplete.
 * Requirements: 12.1, 12.2, 12.3, 12.4, 12.5, 12.6, 12.7, 12.9
 * 
 * Features:
 * - Debounced search input (300ms delay)
 * - Hybrid search (keyword + semantic with pgvector)
 * - Keyboard navigation (arrow keys, Enter, Escape)
 * - Up to 8 suggestions (listings, categories, vendors)
 * - Highlighted matching text in suggestions
 * - Focus ring and expand animation
 */

// Debounce hook
function useDebouncedCallback<T extends (...args: never[]) => void>(
  callback: T,
  delay: number
): T {
  const timeoutRef = useRef<NodeJS.Timeout | null>(null);

  useEffect(() => {
    return () => {
      if (timeoutRef.current) {
        clearTimeout(timeoutRef.current);
      }
    };
  }, []);

  return useCallback(
    ((...args: Parameters<T>) => {
      if (timeoutRef.current) {
        clearTimeout(timeoutRef.current);
      }
      timeoutRef.current = setTimeout(() => {
        callback(...args);
      }, delay);
    }) as T,
    [callback, delay]
  );
}

// Animation variants for dropdown
const dropdownVariants = {
  hidden: { opacity: 0, y: -10, scale: 0.95 },
  visible: {
    opacity: 1,
    y: 0,
    scale: 1,
    transition: { duration: 200, ease: "easeOut" },
  },
  exit: {
    opacity: 0,
    y: -10,
    scale: 0.95,
    transition: { duration: 150, ease: "easeIn" },
  },
};

const itemVariants = {
  hidden: { opacity: 0, x: -10 },
  visible: (i: number) => ({
    opacity: 1,
    x: 0,
    transition: { delay: i * 50, duration: 150 },
  }),
};

// Default mock results for demonstration
const mockResults: AutocompleteResult[] = [
  {
    type: "listing",
    id: "1",
    title: "iPhone 15 Pro Max 256GB",
    subtitle: "Γéª850,000 ΓÇó Lagos",
    thumbnail: undefined,
    url: "/listing/1",
  },
  {
    type: "category",
    id: "electronics",
    title: "Electronics",
    subtitle: "12.5K listings",
    url: "/categories/electronics",
  },
  {
    type: "vendor",
    id: "v1",
    title: "TechHub Nigeria",
    subtitle: "Γ¡É 4.9 ΓÇó 234 listings",
    url: "/store/v1",
  },
];

// Get icon for result type
function getResultIcon(type: AutocompleteResult["type"]) {
  switch (type) {
    case "listing":
      return Package;
    case "category":
      return TrendingUp;
    case "vendor":
      return User;
    default:
      return Search;
  }
}

// Highlight matching text
function highlightMatch(text: string, query: string) {
  if (!query.trim()) return text;
  
  const regex = new RegExp(`(${query.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")})`, "gi");
  const parts = text.split(regex);
  
  return parts.map((part, i) =>
    regex.test(part) ? (
      <mark key={i} className="bg-naija-green/30 text-white rounded px-0.5">
        {part}
      </mark>
    ) : (
      part
    )
  );
}

/**
 * HeroSearchBar - Search component with autocomplete
 * Requirements: 12.1, 12.2, 12.3, 12.4, 12.5, 12.6, 12.7, 12.9
 */
export function HeroSearchBar({
  placeholder = "Search for anything...",
  className,
  onSearch,
}: HeroSearchBarProps) {
  const [query, setQuery] = useState("");
  const [results, setResults] = useState<AutocompleteResult[]>([]);
  const [isOpen, setIsOpen] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [selectedIndex, setSelectedIndex] = useState(-1);
  const inputRef = useRef<HTMLInputElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const prefersReducedMotion = useReducedMotion();

  // Fetch autocomplete results
  const fetchResults = useCallback(async (searchQuery: string) => {
    if (searchQuery.length < 2) {
      setResults([]);
      setIsOpen(false);
      return;
    }

    setIsLoading(true);
    
    try {
      // Call semantic search API with autocomplete mode
      // Requirements: 12.2, 12.3, 22.3, 22.4
      const response = await fetch(
        `/api/search/semantic?q=${encodeURIComponent(searchQuery)}&mode=autocomplete&limit=8`
      );
      
      if (!response.ok) {
        throw new Error("Search failed");
      }
      
      const data = await response.json();
      const suggestions = data.suggestions || [];
      
      setResults(suggestions.slice(0, 8)); // Max 8 results - Requirement 12.4
      setIsOpen(true);
    } catch (error) {
      console.error("Search error:", error);
      // Fallback to empty results on error
      setResults([]);
    } finally {
      setIsLoading(false);
    }
  }, []);

  // Debounced search - 300ms delay (Requirement 12.7)
  const debouncedFetchResults = useDebouncedCallback(fetchResults, 300);

  // Handle input change
  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value;
    setQuery(value);
    setSelectedIndex(-1);
    debouncedFetchResults(value);
  };

  // Handle keyboard navigation - Requirement 12.9
  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (!isOpen || results.length === 0) return;

    switch (e.key) {
      case "ArrowDown":
        e.preventDefault();
        setSelectedIndex((prev) =>
          prev < results.length - 1 ? prev + 1 : 0
        );
        break;
      case "ArrowUp":
        e.preventDefault();
        setSelectedIndex((prev) =>
          prev > 0 ? prev - 1 : results.length - 1
        );
        break;
      case "Enter":
        e.preventDefault();
        if (selectedIndex >= 0 && results[selectedIndex]) {
          handleSelectResult(results[selectedIndex]);
        } else if (query.trim()) {
          handleSearch();
        }
        break;
      case "Escape":
        e.preventDefault();
        setIsOpen(false);
        setSelectedIndex(-1);
        inputRef.current?.blur();
        break;
    }
  };

  // Handle result selection
  const handleSelectResult = (result: AutocompleteResult) => {
    setQuery(result.title);
    setIsOpen(false);
    setSelectedIndex(-1);
    
    if (onSearch) {
      onSearch(result.title);
    }
    
    // Navigate to result URL
    window.location.href = result.url;
  };

  // Handle search submit
  const handleSearch = () => {
    if (!query.trim()) return;
    
    setIsOpen(false);
    
    if (onSearch) {
      onSearch(query);
    }
    
    // Navigate to search page
    window.location.href = `/search?q=${encodeURIComponent(query)}`;
  };

  // Clear search
  const handleClear = () => {
    setQuery("");
    setResults([]);
    setIsOpen(false);
    setSelectedIndex(-1);
    inputRef.current?.focus();
  };

  // Close on outside click
  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (
        containerRef.current &&
        !containerRef.current.contains(e.target as Node)
      ) {
        setIsOpen(false);
        setSelectedIndex(-1);
      }
    };

    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  return (
    <div ref={containerRef} className={cn("relative", className)}>
      {/* Search Input Container - Requirement 12.1 */}
      <motion.div
        initial={false}
        animate={{
          scale: isOpen ? 1.02 : 1,
          boxShadow: isOpen
            ? "0 0 0 2px rgba(0, 200, 83, 0.5)"
            : "0 0 0 1px rgba(255, 255, 255, 0.1)",
        }}
        transition={{ duration: 200 }}
        className="relative flex items-center bg-dark-card/80 backdrop-blur-xl rounded-2xl border border-dark-border overflow-hidden"
      >
        {/* Search Icon */}
        <div className="pl-5 flex items-center pointer-events-none">
          <Search
            className="h-5 w-5 text-gray-400"
            aria-hidden="true"
          />
        </div>

        {/* Input */}
        <input
          ref={inputRef}
          type="text"
          value={query}
          onChange={handleInputChange}
          onKeyDown={handleKeyDown}
          onFocus={() => {
            if (query.length >= 2 && results.length > 0) {
              setIsOpen(true);
            }
          }}
          placeholder={placeholder}
          autoComplete="off"
          aria-label="Search marketplace"
          aria-expanded={isOpen}
          aria-controls="search-results"
          aria-activedescendant={
            selectedIndex >= 0 ? `result-${selectedIndex}` : undefined
          }
          className="flex-1 bg-transparent px-4 py-4 text-white placeholder-gray-400 focus:outline-none min-h-[44px]"
        />

        {/* Loading or Clear Button */}
        <div className="pr-3 flex items-center">
          {isLoading ? (
            <Loader2
              className="h-5 w-5 text-naija-green animate-spin"
              aria-hidden="true"
            />
          ) : query ? (
            <button
              type="button"
              onClick={handleClear}
              aria-label="Clear search"
              className="p-2 rounded-lg hover:bg-gray-700/50 text-gray-400 hover:text-white transition-colors min-h-[44px] min-w-[44px] flex items-center justify-center focus:outline-none focus-visible:ring-2 focus-visible:ring-naija-green"
            >
              <X className="h-4 w-4" />
            </button>
          ) : null}
        </div>
      </motion.div>

      {/* Autocomplete Dropdown - Requirement 12.4 */}
      <AnimatePresence>
        {isOpen && results.length > 0 && (
          <motion.div
            id="search-results"
            initial="hidden"
            animate="visible"
            exit="exit"
            variants={prefersReducedMotion ? {} : dropdownVariants}
            className="absolute top-full left-0 right-0 mt-2 bg-dark-card/95 backdrop-blur-xl border border-dark-border rounded-xl shadow-2xl overflow-hidden z-50"
            role="listbox"
            aria-label="Search suggestions"
          >
            <div className="max-h-80 overflow-y-auto">
              {results.map((result, index) => {
                const Icon = getResultIcon(result.type);
                const isSelected = index === selectedIndex;

                return (
                  <motion.button
                    key={`${result.type}-${result.id}`}
                    id={`result-${index}`}
                    custom={index}
                    initial="hidden"
                    animate="visible"
                    variants={prefersReducedMotion ? {} : itemVariants}
                    onClick={() => handleSelectResult(result)}
                    onMouseEnter={() => setSelectedIndex(index)}
                    role="option"
                    aria-selected={isSelected}
                    className={cn(
                      "w-full flex items-center gap-3 px-4 py-3 text-left transition-colors min-h-[44px] focus:outline-none",
                      isSelected
                        ? "bg-naija-green/20 text-white"
                        : "hover:bg-gray-700/50 text-white"
                    )}
                  >
                    {/* Thumbnail or Icon */}
                    <div
                      className={cn(
                        "w-10 h-10 rounded-lg flex items-center justify-center flex-shrink-0",
                        result.type === "listing"
                          ? "bg-naija-green/20"
                          : result.type === "category"
                          ? "bg-neon-cyan/20"
                          : "bg-neon-purple/20"
                      )}
                    >
                      {result.thumbnail ? (
                        <img
                          src={result.thumbnail}
                          alt=""
                          className="w-full h-full object-cover rounded-lg"
                        />
                      ) : (
                        <Icon
                          className={cn(
                            "h-5 w-5",
                            result.type === "listing"
                              ? "text-naija-green"
                              : result.type === "category"
                              ? "text-neon-cyan"
                              : "text-neon-purple"
                          )}
                          aria-hidden="true"
                        />
                      )}
                    </div>

                    {/* Content */}
                    <div className="flex-1 min-w-0">
                      <div className="font-medium truncate">
                        {/* Highlight matching text - Requirement 12.6 */}
                        {highlightMatch(result.title, query)}
                      </div>
                      {result.subtitle && (
                        <div className="text-sm text-gray-400 truncate">
                          {result.subtitle}
                        </div>
                      )}
                    </div>

                    {/* Type Badge */}
                    <span
                      className={cn(
                        "text-xs px-2 py-1 rounded-full flex-shrink-0",
                        result.type === "listing"
                          ? "bg-naija-green/20 text-naija-green"
                          : result.type === "category"
                          ? "bg-neon-cyan/20 text-neon-cyan"
                          : "bg-neon-purple/20 text-neon-purple"
                      )}
                    >
                      {result.type}
                    </span>
                  </motion.button>
                );
              })}
            </div>

            {/* Footer hint */}
            <div className="px-4 py-2 border-t border-dark-border bg-gray-800/50">
              <p className="text-xs text-gray-500 flex items-center gap-2">
                <span>ΓåæΓåô to navigate</span>
                <span>ΓÇó</span>
                <span>Enter to select</span>
                <span>ΓÇó</span>
                <span>Esc to close</span>
              </p>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* No results message */}
      <AnimatePresence>
        {isOpen && query.length >= 2 && !isLoading && results.length === 0 && (
          <motion.div
            initial="hidden"
            animate="visible"
            exit="exit"
            variants={prefersReducedMotion ? {} : dropdownVariants}
            className="absolute top-full left-0 right-0 mt-2 bg-dark-card/95 backdrop-blur-xl border border-dark-border rounded-xl shadow-2xl p-6 text-center z-50"
          >
            <Search className="h-8 w-8 text-gray-600 mx-auto mb-2" aria-hidden="true" />
            <p className="text-gray-400">No results found for &quot;{query}&quot;</p>
            <p className="text-sm text-gray-500 mt-1">
              Try different keywords or browse categories
            </p>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { motion } from "framer-motion";
import {
  Package,
  AlertTriangle,
  TrendingUp,
  DollarSign,
  Loader2,
  Plus,
  Edit,
  History,
  Download,
  Upload,
  Search,
  Filter,
  X,
} from "lucide-react";
import type { InventoryItem, InventorySummary } from "@/lib/types";
import { StockUpdateModal } from "./stock-update-modal";
import { VariantManager } from "./variant-manager";
import { StockHistoryModal } from "./stock-history-modal";
import { BulkUpdateModal } from "./bulk-update-modal";

interface InventoryManagerProps {
  userId: string;
}

export function InventoryManager({ userId }: InventoryManagerProps) {
  const [inventory, setInventory] = useState<InventoryItem[]>([]);
  const [summary, setSummary] = useState<InventorySummary | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState("");
  const [filterSoldOut, setFilterSoldOut] = useState(false);
  const [filterLowStock, setFilterLowStock] = useState(false);
  const [selectedItem, setSelectedItem] = useState<InventoryItem | null>(null);
  const [showUpdateModal, setShowUpdateModal] = useState(false);
  const [showVariantModal, setShowVariantModal] = useState(false);
  const [showHistoryModal, setShowHistoryModal] = useState(false);
  const [showBulkModal, setShowBulkModal] = useState(false);

  useEffect(() => {
    fetchInventory();
    fetchSummary();
  }, [filterSoldOut, filterLowStock]);

  const fetchInventory = async () => {
    try {
      const params = new URLSearchParams();
      if (filterSoldOut) params.append("is_sold_out", "true");
      if (filterLowStock) params.append("is_low_stock", "true");

      const response = await fetch(`/api/inventory?${params.toString()}`);

      if (!response.ok) {
        throw new Error("Failed to fetch inventory");
      }

      const data = await response.json();
      setInventory(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to load inventory");
    } finally {
      setIsLoading(false);
    }
  };

  const fetchSummary = async () => {
    try {
      const response = await fetch("/api/inventory/summary");

      if (!response.ok) {
        throw new Error("Failed to fetch summary");
      }

      const data = await response.json();
      setSummary(data);
    } catch (err) {
      console.error("Failed to fetch summary:", err);
    }
  };

  const handleUpdateStock = (item: InventoryItem) => {
    setSelectedItem(item);
    setShowUpdateModal(true);
  };

  const handleManageVariants = (item: InventoryItem) => {
    setSelectedItem(item);
    setShowVariantModal(true);
  };

  const handleViewHistory = (item: InventoryItem) => {
    setSelectedItem(item);
    setShowHistoryModal(true);
  };

  const handleStockUpdated = () => {
    fetchInventory();
    fetchSummary();
    setShowUpdateModal(false);
    setShowVariantModal(false);
    setShowBulkModal(false);
  };

  const filteredInventory = inventory.filter((item) => {
    if (!searchQuery) return true;
    const listing = item.listing as any;
    return listing?.title?.toLowerCase().includes(searchQuery.toLowerCase());
  });

  if (isLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <Loader2 className="w-8 h-8 text-naija-orange animate-spin" />
      </div>
    );
  }

  if (error) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="text-center">
          <AlertTriangle className="w-12 h-12 text-red-500 mx-auto mb-4" />
          <p className="text-white text-lg">{error}</p>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        className="flex items-center justify-between flex-wrap gap-4"
      >
        <div>
          <h1 className="text-3xl font-bold text-white mb-2">
            Inventory Management
          </h1>
          <p className="text-gray-400">
            Track and manage your stock levels across all listings
          </p>
        </div>
        <button
          type="button"
          onClick={() => setShowBulkModal(true)}
          className="flex items-center gap-2 px-4 py-2 bg-naija-orange hover:bg-naija-orange/90 text-white rounded-lg font-medium transition-colors"
        >
          <Upload className="w-4 h-4" />
          Bulk Update
        </button>
      </motion.div>

      {/* Summary Cards */}
      {summary && (
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.1 }}
          className="grid grid-cols-2 md:grid-cols-4 gap-4"
        >
          <div className="bg-dark-card border border-dark-border rounded-xl p-4">
            <div className="flex items-center gap-2 mb-2">
              <Package className="w-4 h-4 text-neon-cyan" />
              <span className="text-xs text-gray-400">Total Items</span>
            </div>
            <p className="text-2xl font-bold text-white">
              {summary.totalItems}
            </p>
          </div>

          <div className="bg-dark-card border border-dark-border rounded-xl p-4">
            <div className="flex items-center gap-2 mb-2">
              <DollarSign className="w-4 h-4 text-naija-green" />
              <span className="text-xs text-gray-400">Total Value</span>
            </div>
            <p className="text-2xl font-bold text-white">
              Γéª{summary.totalValue.toLocaleString()}
            </p>
          </div>

          <div className="bg-dark-card border border-dark-border rounded-xl p-4">
            <div className="flex items-center gap-2 mb-2">
              <AlertTriangle className="w-4 h-4 text-yellow-500" />
              <span className="text-xs text-gray-400">Low Stock</span>
            </div>
            <p className="text-2xl font-bold text-white">
              {summary.lowStockItems}
            </p>
          </div>

          <div className="bg-dark-card border border-dark-border rounded-xl p-4">
            <div className="flex items-center gap-2 mb-2">
              <X className="w-4 h-4 text-red-500" />
              <span className="text-xs text-gray-400">Sold Out</span>
            </div>
            <p className="text-2xl font-bold text-white">
              {summary.soldOutItems}
            </p>
          </div>
        </motion.div>
      )}

      {/* Low Stock Alerts */}
      {summary && summary.lowStockItems > 0 && (
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.2 }}
          className="bg-yellow-500/10 border border-yellow-500/30 rounded-xl p-4"
        >
          <div className="flex items-start gap-3">
            <AlertTriangle className="w-5 h-5 text-yellow-500 flex-shrink-0 mt-0.5" />
            <div>
              <h3 className="text-white font-semibold mb-1">Low Stock Alert</h3>
              <p className="text-gray-300 text-sm">
                You have {summary.lowStockItems} item
                {summary.lowStockItems !== 1 ? "s" : ""} running low on stock.
                Consider restocking soon to avoid running out.
              </p>
            </div>
          </div>
        </motion.div>
      )}

      {/* Search and Filters */}
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ delay: 0.3 }}
        className="bg-dark-card border border-dark-border rounded-xl p-4"
      >
        <div className="flex flex-col md:flex-row gap-4">
          <div className="flex-1 relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
            <input
              type="text"
              placeholder="Search listings..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full pl-10 pr-4 py-2 bg-dark-bg border border-dark-border rounded-lg text-white placeholder-gray-500 focus:outline-none focus:border-naija-orange"
            />
          </div>
          <div className="flex gap-2">
            <button
              type="button"
              onClick={() => setFilterLowStock(!filterLowStock)}
              className={`px-4 py-2 rounded-lg font-medium transition-colors ${
                filterLowStock
                  ? "bg-yellow-500 text-white"
                  : "bg-dark-bg text-gray-400 hover:text-white"
              }`}
            >
              Low Stock
            </button>
            <button
              type="button"
              onClick={() => setFilterSoldOut(!filterSoldOut)}
              className={`px-4 py-2 rounded-lg font-medium transition-colors ${
                filterSoldOut
                  ? "bg-red-500 text-white"
                  : "bg-dark-bg text-gray-400 hover:text-white"
              }`}
            >
              Sold Out
            </button>
          </div>
        </div>
      </motion.div>

      {/* Inventory Table */}
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ delay: 0.4 }}
        className="bg-dark-card border border-dark-border rounded-xl overflow-hidden"
      >
        <div className="overflow-x-auto">
          {filteredInventory.length === 0 ? (
            <div className="p-12 text-center">
              <Package className="w-16 h-16 text-gray-600 mx-auto mb-4" />
              <h3 className="text-xl font-semibold text-white mb-2">
                No inventory items found
              </h3>
              <p className="text-gray-400 mb-6">
                {searchQuery
                  ? "Try adjusting your search or filters"
                  : "Create listings and set stock quantities to get started"}
              </p>
            </div>
          ) : (
            <table className="w-full">
              <thead className="bg-dark-bg">
                <tr>
                  <th className="text-left text-xs text-gray-400 font-medium p-4">
                    Listing
                  </th>
                  <th className="text-right text-xs text-gray-400 font-medium p-4">
                    Stock
                  </th>
                  <th className="text-right text-xs text-gray-400 font-medium p-4">
                    Threshold
                  </th>
                  <th className="text-right text-xs text-gray-400 font-medium p-4">
                    Unit Price
                  </th>
                  <th className="text-right text-xs text-gray-400 font-medium p-4">
                    Total Value
                  </th>
                  <th className="text-center text-xs text-gray-400 font-medium p-4">
                    Status
                  </th>
                  <th className="text-center text-xs text-gray-400 font-medium p-4">
                    Actions
                  </th>
                </tr>
              </thead>
              <tbody>
                {filteredInventory.map((item) => {
                  const listing = item.listing as any;
                  const isLowStock =
                    item.stock_quantity > 0 &&
                    item.stock_quantity <= item.low_stock_threshold;

                  return (
                    <tr
                      key={item.id}
                      className="border-t border-dark-border hover:bg-dark-bg/50"
                    >
                      <td className="p-4">
                        <div className="flex items-center gap-3">
                          {listing?.thumbnail_url && (
                            <img
                              src={listing.thumbnail_url}
                              alt={listing.title}
                              className="w-12 h-12 rounded-lg object-cover"
                            />
                          )}
                          <div>
                            <p className="text-white font-medium text-sm">
                              {listing?.title || "Unknown"}
                            </p>
                            {item.has_variants && (
                              <span className="text-xs text-neon-cyan">
                                {(item.variants as any[]).length} variants
                              </span>
                            )}
                          </div>
                        </div>
                      </td>
                      <td className="p-4 text-right">
                        <span
                          className={`text-sm font-semibold ${
                            item.is_sold_out
                              ? "text-red-500"
                              : isLowStock
                                ? "text-yellow-500"
                                : "text-white"
                          }`}
                        >
                          {item.stock_quantity}
                        </span>
                      </td>
                      <td className="p-4 text-right text-gray-400 text-sm">
                        {item.low_stock_threshold}
                      </td>
                      <td className="p-4 text-right text-white text-sm">
                        Γéª{item.unit_price.toLocaleString()}
                      </td>
                      <td className="p-4 text-right text-white text-sm font-semibold">
                        Γéª{item.total_value.toLocaleString()}
                      </td>
                      <td className="p-4 text-center">
                        {item.is_sold_out ? (
                          <span className="inline-flex items-center gap-1 px-2 py-1 bg-red-500/20 text-red-500 text-xs font-medium rounded-full">
                            <X className="w-3 h-3" />
                            Sold Out
                          </span>
                        ) : isLowStock ? (
                          <span className="inline-flex items-center gap-1 px-2 py-1 bg-yellow-500/20 text-yellow-500 text-xs font-medium rounded-full">
                            <AlertTriangle className="w-3 h-3" />
                            Low Stock
                          </span>
                        ) : (
                          <span className="inline-flex items-center gap-1 px-2 py-1 bg-green-500/20 text-green-500 text-xs font-medium rounded-full">
                            In Stock
                          </span>
                        )}
                      </td>
                      <td className="p-4">
                        <div className="flex items-center justify-center gap-2">
                          <button
                            type="button"
                            onClick={() => handleUpdateStock(item)}
                            className="p-2 hover:bg-dark-bg rounded-lg transition-colors"
                            title="Update stock"
                          >
                            <Edit className="w-4 h-4 text-gray-400 hover:text-white" />
                          </button>
                          {item.has_variants && (
                            <button
                              type="button"
                              onClick={() => handleManageVariants(item)}
                              className="p-2 hover:bg-dark-bg rounded-lg transition-colors"
                              title="Manage variants"
                            >
                              <Package className="w-4 h-4 text-gray-400 hover:text-white" />
                            </button>
                          )}
                          <button
                            type="button"
                            onClick={() => handleViewHistory(item)}
                            className="p-2 hover:bg-dark-bg rounded-lg transition-colors"
                            title="View history"
                          >
                            <History className="w-4 h-4 text-gray-400 hover:text-white" />
                          </button>
                        </div>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          )}
        </div>
      </motion.div>

      {/* Modals */}
      {showUpdateModal && selectedItem && (
        <StockUpdateModal
          item={selectedItem}
          onClose={() => setShowUpdateModal(false)}
          onSuccess={handleStockUpdated}
        />
      )}

      {showVariantModal && selectedItem && (
        <VariantManager
          item={selectedItem}
          onClose={() => setShowVariantModal(false)}
          onSuccess={handleStockUpdated}
        />
      )}

      {showHistoryModal && selectedItem && (
        <StockHistoryModal
          listingId={selectedItem.listing_id}
          onClose={() => setShowHistoryModal(false)}
        />
      )}

      {showBulkModal && (
        <BulkUpdateModal
          onClose={() => setShowBulkModal(false)}
          onSuccess={handleStockUpdated}
        />
      )}
    </div>
  );
}

"use client";

import { useState } from "react";
import { X, Loader2, Package } from "lucide-react";
import type { InventoryItem } from "@/lib/types";

interface StockUpdateModalProps {
  item: InventoryItem;
  onClose: () => void;
  onSuccess: () => void;
}

export function StockUpdateModal({
  item,
  onClose,
  onSuccess,
}: StockUpdateModalProps) {
  const [stockQuantity, setStockQuantity] = useState(item.stock_quantity);
  const [lowStockThreshold, setLowStockThreshold] = useState(
    item.low_stock_threshold,
  );
  const [unitPrice, setUnitPrice] = useState(item.unit_price);
  const [notes, setNotes] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    setError(null);

    try {
      const response = await fetch(`/api/inventory/${item.listing_id}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          stock_quantity: stockQuantity,
          low_stock_threshold: lowStockThreshold,
          unit_price: unitPrice,
          notes,
        }),
      });

      if (!response.ok) {
        const data = await response.json();
        throw new Error(data.error || "Failed to update stock");
      }

      onSuccess();
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to update stock");
    } finally {
      setIsSubmitting(false);
    }
  };

  const listing = item.listing as any;

  return (
    <div className="fixed inset-0 bg-black/80 flex items-center justify-center z-50 p-4">
      <div className="bg-dark-card border border-dark-border rounded-2xl max-w-md w-full p-6">
        <div className="flex items-center justify-between mb-6">
          <div className="flex items-center gap-2">
            <Package className="w-5 h-5 text-naija-orange" />
            <h2 className="text-xl font-bold text-white">Update Stock</h2>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="text-gray-400 hover:text-white"
            aria-label="Close modal"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        <div className="mb-4 p-3 bg-dark-bg rounded-lg">
          <p className="text-white font-medium text-sm">
            {listing?.title || "Unknown Listing"}
          </p>
          <p className="text-gray-400 text-xs mt-1">
            Current stock: {item.stock_quantity}
          </p>
        </div>

        {error && (
          <div className="mb-4 p-3 bg-red-500/10 border border-red-500/30 rounded-lg">
            <p className="text-red-500 text-sm">{error}</p>
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label
              htmlFor="stock-quantity"
              className="block text-sm font-medium text-gray-300 mb-2"
            >
              Stock Quantity
            </label>
            <input
              id="stock-quantity"
              type="number"
              min="0"
              value={stockQuantity}
              onChange={(e) => setStockQuantity(parseInt(e.target.value) || 0)}
              className="w-full px-4 py-2 bg-dark-bg border border-dark-border rounded-lg text-white focus:outline-none focus:border-naija-orange"
              required
            />
          </div>

          <div>
            <label
              htmlFor="low-stock-threshold"
              className="block text-sm font-medium text-gray-300 mb-2"
            >
              Low Stock Threshold
            </label>
            <input
              id="low-stock-threshold"
              type="number"
              min="0"
              value={lowStockThreshold}
              onChange={(e) =>
                setLowStockThreshold(parseInt(e.target.value) || 0)
              }
              className="w-full px-4 py-2 bg-dark-bg border border-dark-border rounded-lg text-white focus:outline-none focus:border-naija-orange"
              required
            />
            <p className="text-xs text-gray-500 mt-1">
              You'll be notified when stock falls below this level
            </p>
          </div>

          <div>
            <label
              htmlFor="unit-price"
              className="block text-sm font-medium text-gray-300 mb-2"
            >
              Unit Price (Γéª)
            </label>
            <input
              id="unit-price"
              type="number"
              min="0"
              step="0.01"
              value={unitPrice}
              onChange={(e) => setUnitPrice(parseFloat(e.target.value) || 0)}
              className="w-full px-4 py-2 bg-dark-bg border border-dark-border rounded-lg text-white focus:outline-none focus:border-naija-orange"
              required
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-300 mb-2">
              Notes (Optional)
            </label>
            <textarea
              value={notes}
              onChange={(e) => setNotes(e.target.value)}
              rows={3}
              className="w-full px-4 py-2 bg-dark-bg border border-dark-border rounded-lg text-white focus:outline-none focus:border-naija-orange resize-none"
              placeholder="Reason for stock update..."
            />
          </div>

          <div className="flex gap-3 pt-4">
            <button
              type="button"
              onClick={onClose}
              className="flex-1 px-4 py-2 bg-dark-bg hover:bg-dark-border text-white rounded-lg font-medium transition-colors"
            >
              Cancel
            </button>
            <button
              type="submit"
              disabled={isSubmitting}
              className="flex-1 px-4 py-2 bg-naija-orange hover:bg-naija-orange/90 text-white rounded-lg font-medium transition-colors disabled:opacity-50 flex items-center justify-center gap-2"
            >
              {isSubmitting ? (
                <>
                  <Loader2 className="w-4 h-4 animate-spin" />
                  Updating...
                </>
              ) : (
                "Update Stock"
              )}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import { X, Loader2, Plus, Trash2, Package } from "lucide-react";
import type { InventoryItem, InventoryVariant } from "@/lib/types";

interface VariantManagerProps {
  item: InventoryItem;
  onClose: () => void;
  onSuccess: () => void;
}

export function VariantManager({
  item,
  onClose,
  onSuccess,
}: VariantManagerProps) {
  const [variants, setVariants] = useState<InventoryVariant[]>(
    (item.variants as InventoryVariant[]) || [],
  );
  const [unitPrice, setUnitPrice] = useState(item.unit_price);
  const [lowStockThreshold, setLowStockThreshold] = useState(
    item.low_stock_threshold,
  );
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const addVariant = () => {
    setVariants([
      ...variants,
      {
        id: `variant-${Date.now()}`,
        name: "",
        attributes: {},
        stock: 0,
      },
    ]);
  };

  const removeVariant = (index: number) => {
    setVariants(variants.filter((_, i) => i !== index));
  };

  const updateVariant = (
    index: number,
    field: keyof InventoryVariant,
    value: any,
  ) => {
    const updated = [...variants];
    updated[index] = { ...updated[index], [field]: value };
    setVariants(updated);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    setError(null);

    // Validate variants
    if (variants.length === 0) {
      setError("At least one variant is required");
      setIsSubmitting(false);
      return;
    }

    for (const variant of variants) {
      if (!variant.name.trim()) {
        setError("All variants must have a name");
        setIsSubmitting(false);
        return;
      }
    }

    try {
      const response = await fetch(
        `/api/inventory/${item.listing_id}/variants`,
        {
          method: "PUT",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            variants,
            unit_price: unitPrice,
            low_stock_threshold: lowStockThreshold,
          }),
        },
      );

      if (!response.ok) {
        const data = await response.json();
        throw new Error(data.error || "Failed to update variants");
      }

      onSuccess();
    } catch (err) {
      setError(
        err instanceof Error ? err.message : "Failed to update variants",
      );
    } finally {
      setIsSubmitting(false);
    }
  };

  const listing = item.listing as any;
  const totalStock = variants.reduce((sum, v) => sum + v.stock, 0);

  return (
    <div className="fixed inset-0 bg-black/80 flex items-center justify-center z-50 p-4 overflow-y-auto">
      <div className="bg-dark-card border border-dark-border rounded-2xl max-w-2xl w-full p-6 my-8">
        <div className="flex items-center justify-between mb-6">
          <div className="flex items-center gap-2">
            <Package className="w-5 h-5 text-naija-orange" />
            <h2 className="text-xl font-bold text-white">Manage Variants</h2>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="text-gray-400 hover:text-white"
            aria-label="Close modal"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        <div className="mb-4 p-3 bg-dark-bg rounded-lg">
          <p className="text-white font-medium text-sm">
            {listing?.title || "Unknown Listing"}
          </p>
          <p className="text-gray-400 text-xs mt-1">
            Total stock across variants: {totalStock}
          </p>
        </div>

        {error && (
          <div className="mb-4 p-3 bg-red-500/10 border border-red-500/30 rounded-lg">
            <p className="text-red-500 text-sm">{error}</p>
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label
                htmlFor="variant-unit-price"
                className="block text-sm font-medium text-gray-300 mb-2"
              >
                Unit Price (Γéª)
              </label>
              <input
                id="variant-unit-price"
                type="number"
                min="0"
                step="0.01"
                value={unitPrice}
                onChange={(e) => setUnitPrice(parseFloat(e.target.value) || 0)}
                className="w-full px-4 py-2 bg-dark-bg border border-dark-border rounded-lg text-white focus:outline-none focus:border-naija-orange"
                required
              />
            </div>

            <div>
              <label
                htmlFor="variant-threshold"
                className="block text-sm font-medium text-gray-300 mb-2"
              >
                Low Stock Threshold
              </label>
              <input
                id="variant-threshold"
                type="number"
                min="0"
                value={lowStockThreshold}
                onChange={(e) =>
                  setLowStockThreshold(parseInt(e.target.value) || 0)
                }
                className="w-full px-4 py-2 bg-dark-bg border border-dark-border rounded-lg text-white focus:outline-none focus:border-naija-orange"
                required
              />
            </div>
          </div>

          <div>
            <div className="flex items-center justify-between mb-3">
              <label className="block text-sm font-medium text-gray-300">
                Variants
              </label>
              <button
                type="button"
                onClick={addVariant}
                className="flex items-center gap-1 px-3 py-1 bg-naija-orange hover:bg-naija-orange/90 text-white text-sm rounded-lg transition-colors"
              >
                <Plus className="w-4 h-4" />
                Add Variant
              </button>
            </div>

            <div className="space-y-3 max-h-96 overflow-y-auto">
              {variants.map((variant, index) => (
                <div
                  key={variant.id}
                  className="p-4 bg-dark-bg border border-dark-border rounded-lg"
                >
                  <div className="flex items-start gap-3">
                    <div className="flex-1 space-y-3">
                      <div className="grid grid-cols-2 gap-3">
                        <div>
                          <label
                            htmlFor={`variant-name-${index}`}
                            className="block text-xs text-gray-400 mb-1"
                          >
                            Variant Name
                          </label>
                          <input
                            id={`variant-name-${index}`}
                            type="text"
                            value={variant.name}
                            onChange={(e) =>
                              updateVariant(index, "name", e.target.value)
                            }
                            placeholder="e.g., Red - Large"
                            className="w-full px-3 py-2 bg-dark-card border border-dark-border rounded-lg text-white text-sm focus:outline-none focus:border-naija-orange"
                            required
                          />
                        </div>

                        <div>
                          <label
                            htmlFor={`variant-stock-${index}`}
                            className="block text-xs text-gray-400 mb-1"
                          >
                            Stock Quantity
                          </label>
                          <input
                            id={`variant-stock-${index}`}
                            type="number"
                            min="0"
                            value={variant.stock}
                            onChange={(e) =>
                              updateVariant(
                                index,
                                "stock",
                                parseInt(e.target.value) || 0,
                              )
                            }
                            className="w-full px-3 py-2 bg-dark-card border border-dark-border rounded-lg text-white text-sm focus:outline-none focus:border-naija-orange"
                            required
                          />
                        </div>
                      </div>

                      <div>
                        <label
                          htmlFor={`variant-sku-${index}`}
                          className="block text-xs text-gray-400 mb-1"
                        >
                          SKU (Optional)
                        </label>
                        <input
                          id={`variant-sku-${index}`}
                          type="text"
                          value={variant.sku || ""}
                          onChange={(e) =>
                            updateVariant(index, "sku", e.target.value)
                          }
                          placeholder="e.g., PROD-RED-L"
                          className="w-full px-3 py-2 bg-dark-card border border-dark-border rounded-lg text-white text-sm focus:outline-none focus:border-naija-orange"
                        />
                      </div>
                    </div>

                    <button
                      type="button"
                      onClick={() => removeVariant(index)}
                      className="p-2 text-red-500 hover:bg-red-500/10 rounded-lg transition-colors"
                      aria-label="Remove variant"
                    >
                      <Trash2 className="w-4 h-4" />
                    </button>
                  </div>
                </div>
              ))}

              {variants.length === 0 && (
                <div className="p-8 text-center border-2 border-dashed border-dark-border rounded-lg">
                  <Package className="w-12 h-12 text-gray-600 mx-auto mb-2" />
                  <p className="text-gray-400 text-sm">
                    No variants yet. Click "Add Variant" to get started.
                  </p>
                </div>
              )}
            </div>
          </div>

          <div className="flex gap-3 pt-4">
            <button
              type="button"
              onClick={onClose}
              className="flex-1 px-4 py-2 bg-dark-bg hover:bg-dark-border text-white rounded-lg font-medium transition-colors"
            >
              Cancel
            </button>
            <button
              type="submit"
              disabled={isSubmitting}
              className="flex-1 px-4 py-2 bg-naija-orange hover:bg-naija-orange/90 text-white rounded-lg font-medium transition-colors disabled:opacity-50 flex items-center justify-center gap-2"
            >
              {isSubmitting ? (
                <>
                  <Loader2 className="w-4 h-4 animate-spin" />
                  Saving...
                </>
              ) : (
                "Save Variants"
              )}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

