"use client";

/**
 * Live Chat Panel Component
 *
 * Displays real-time chat messages and allows viewers to send messages.
 * Uses Supabase Realtime for instant message delivery.
 *
 * Requirements: 2.3
 * Task: 19.3
 */

import { useEffect, useRef, useState } from "react";
import { Send, Trash2, AlertCircle } from "lucide-react";
import { createClient } from "@/lib/supabase/client";
import type { RealtimeChannel } from "@supabase/supabase-js";
import type { LiveChatMessage } from "@/lib/types";

interface LiveChatPanelProps {
  sessionId: string;
  currentUserId?: string;
  isHost?: boolean;
  className?: string;
}

interface ChatMessageWithUser extends Omit<LiveChatMessage, "user"> {
  user?: {
    username: string;
    avatar_url: string | null;
  };
}

export function LiveChatPanel({
  sessionId,
  currentUserId,
  isHost = false,
  className = "",
}: LiveChatPanelProps) {
  const [messages, setMessages] = useState<ChatMessageWithUser[]>([]);
  const [newMessage, setNewMessage] = useState("");
  const [isSending, setIsSending] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const channelRef = useRef<RealtimeChannel | null>(null);

  // Auto-scroll to latest message
  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  // Subscribe to real-time chat messages
  useEffect(() => {
    const supabase = createClient();

    // Fetch initial messages
    const fetchMessages = async () => {
      const { data, error } = await (supabase.from("live_chat_messages") as any)
        .select(
          `
          *,
          user:users!user_id(username, avatar_url)
        `,
        )
        .eq("session_id", sessionId)
        .eq("is_deleted", false)
        .order("created_at", { ascending: true })
        .limit(100);

      if (error) {
        console.error("Failed to fetch messages:", error);
        return;
      }

      setMessages((data as any) || []);
    };

    fetchMessages();

    // Subscribe to new messages
    const channel = supabase
      .channel(`live-chat-${sessionId}`)
      .on(
        "postgres_changes",
        {
          event: "INSERT",
          schema: "public",
          table: "live_chat_messages",
          filter: `session_id=eq.${sessionId}`,
        },
        async (payload: any) => {
          // Fetch user info for the new message
          const { data: userData } = await (supabase.from("users") as any)
            .select("username, avatar_url")
            .eq("id", payload.new.user_id)
            .single();

          const newMsg: any = {
            ...payload.new,
            user: userData || undefined,
          };

          setMessages((prev) => [...prev, newMsg]);
        },
      )
      .on(
        "postgres_changes",
        {
          event: "UPDATE",
          schema: "public",
          table: "live_chat_messages",
          filter: `session_id=eq.${sessionId}`,
        },
        (payload: any) => {
          // Handle message deletion or flagging
          setMessages((prev: any) =>
            prev.map((msg: any) =>
              msg.id === payload.new.id ? { ...msg, ...payload.new } : msg,
            ),
          );
        },
      )
      .subscribe();

    channelRef.current = channel;

    return () => {
      channel.unsubscribe();
    };
  }, [sessionId]);

  // Send message
  const handleSendMessage = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!newMessage.trim() || !currentUserId) {
      return;
    }

    // Validate message length (max 500 characters)
    if (newMessage.length > 500) {
      setError("Message is too long (max 500 characters)");
      return;
    }

    setIsSending(true);
    setError(null);

    try {
      const supabase = createClient();

      const { error: insertError } = await supabase
        .from("live_chat_messages")
        .insert({
          session_id: sessionId,
          user_id: currentUserId,
          message: newMessage.trim(),
        });

      if (insertError) {
        throw insertError;
      }

      setNewMessage("");
    } catch (err) {
      console.error("Failed to send message:", err);
      setError("Failed to send message. Please try again.");
    } finally {
      setIsSending(false);
    }
  };

  // Delete message (host only)
  const handleDeleteMessage = async (messageId: string) => {
    if (!isHost) return;

    try {
      const supabase = createClient();

      const { error: deleteError } = await supabase
        .from("live_chat_messages")
        .update({ is_deleted: true })
        .eq("id", messageId);

      if (deleteError) {
        throw deleteError;
      }

      // Remove from local state
      setMessages((prev) => prev.filter((msg) => msg.id !== messageId));
    } catch (err) {
      console.error("Failed to delete message:", err);
    }
  };

  return (
    <div
      className={`flex flex-col h-full bg-white dark:bg-gray-900 rounded-lg border border-gray-200 dark:border-gray-800 ${className}`}
    >
      {/* Header */}
      <div className="px-4 py-3 border-b border-gray-200 dark:border-gray-800">
        <h3 className="text-lg font-semibold text-gray-900 dark:text-white">
          Live Chat
        </h3>
        <p className="text-sm text-gray-500 dark:text-gray-400">
          {messages.length} messages
        </p>
      </div>

      {/* Messages Container */}
      <div
        className="flex-1 overflow-y-auto px-4 py-3 space-y-3"
        role="log"
        aria-live="polite"
        aria-label="Live chat messages"
      >
        {messages.length === 0 ? (
          <div className="flex items-center justify-center h-full text-gray-500 dark:text-gray-400 text-sm">
            No messages yet. Be the first to chat!
          </div>
        ) : (
          messages
            .filter((msg) => !msg.is_deleted)
            .map((msg) => (
              <div
                key={msg.id}
                className="flex items-start gap-2 group"
                role="article"
              >
                {/* Avatar */}
                <div className="flex-shrink-0">
                  {msg.user?.avatar_url ? (
                    <img
                      src={msg.user.avatar_url}
                      alt={msg.user.username}
                      className="w-8 h-8 rounded-full object-cover"
                    />
                  ) : (
                    <div className="w-8 h-8 rounded-full bg-gradient-to-br from-blue-500 to-purple-600 flex items-center justify-center text-white text-sm font-semibold">
                      {msg.user?.username?.[0]?.toUpperCase() || "?"}
                    </div>
                  )}
                </div>

                {/* Message Content */}
                <div className="flex-1 min-w-0">
                  <div className="flex items-baseline gap-2">
                    <span className="font-semibold text-sm text-gray-900 dark:text-white">
                      {msg.user?.username || "Anonymous"}
                    </span>
                    <span className="text-xs text-gray-500 dark:text-gray-400">
                      {new Date(msg.created_at).toLocaleTimeString([], {
                        hour: "2-digit",
                        minute: "2-digit",
                      })}
                    </span>
                  </div>
                  <p className="text-sm text-gray-700 dark:text-gray-300 break-words">
                    {msg.message}
                  </p>
                  {msg.is_flagged && (
                    <div className="flex items-center gap-1 mt-1 text-xs text-amber-600 dark:text-amber-400">
                      <AlertCircle className="w-3 h-3" />
                      <span>Flagged for review</span>
                    </div>
                  )}
                </div>

                {/* Delete Button (Host Only) */}
                {isHost && (
                  <button
                    type="button"
                    onClick={() => handleDeleteMessage(msg.id)}
                    className="opacity-0 group-hover:opacity-100 transition-opacity p-1 hover:bg-red-100 dark:hover:bg-red-900/20 rounded"
                    aria-label="Delete message"
                  >
                    <Trash2 className="w-4 h-4 text-red-600 dark:text-red-400" />
                  </button>
                )}
              </div>
            ))
        )}
        <div ref={messagesEndRef} />
      </div>

      {/* Message Input */}
      {currentUserId ? (
        <form
          onSubmit={handleSendMessage}
          className="px-4 py-3 border-t border-gray-200 dark:border-gray-800"
        >
          {error && (
            <div className="mb-2 text-sm text-red-600 dark:text-red-400">
              {error}
            </div>
          )}
          <div className="flex items-center gap-2">
            <input
              type="text"
              value={newMessage}
              onChange={(e) => setNewMessage(e.target.value)}
              placeholder="Send a message..."
              maxLength={500}
              disabled={isSending}
              className="flex-1 px-3 py-2 border border-gray-300 dark:border-gray-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 dark:bg-gray-800 dark:text-white disabled:opacity-50"
              aria-label="Chat message input"
            />
            <button
              type="submit"
              disabled={isSending || !newMessage.trim()}
              className="p-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
              aria-label="Send message"
            >
              <Send className="w-5 h-5" />
            </button>
          </div>
          <div className="mt-1 text-xs text-gray-500 dark:text-gray-400">
            {newMessage.length}/500 characters
          </div>
        </form>
      ) : (
        <div className="px-4 py-3 border-t border-gray-200 dark:border-gray-800 text-center text-sm text-gray-500 dark:text-gray-400">
          Sign in to chat
        </div>
      )}
    </div>
  );
}

"use client";

/**
 * LogisticsSelector Component
 * Task 30.1: Display all partner options with cost comparison
 * Requirements: 8.1, 8.10
 */

import { useState, useEffect } from "react";
import { Check, Truck, Clock, DollarSign } from "lucide-react";
import type { ShippingQuote, GetQuotesRequest } from "@/lib/types/logistics";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";

interface LogisticsSelectorProps {
  orderId: string;
  quoteRequest: GetQuotesRequest;
  onSelect: (quote: ShippingQuote) => void;
  selectedQuoteId?: string;
}

export function LogisticsSelector({
  orderId,
  quoteRequest,
  onSelect,
  selectedQuoteId,
}: LogisticsSelectorProps) {
  const [quotes, setQuotes] = useState<ShippingQuote[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchQuotes();
  }, []);

  const fetchQuotes = async () => {
    try {
      setLoading(true);
      setError(null);

      const response = await fetch("/api/logistics/quotes", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(quoteRequest),
      });

      if (!response.ok) {
        throw new Error("Failed to fetch shipping quotes");
      }

      const data = await response.json();
      setQuotes(data.quotes || []);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An error occurred");
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <div className="space-y-4">
        <h3 className="text-lg font-semibold">Select Logistics Partner</h3>
        {[1, 2, 3].map((i) => (
          <Card key={i}>
            <CardContent className="p-4">
              <Skeleton className="h-20 w-full" />
            </CardContent>
          </Card>
        ))}
      </div>
    );
  }

  if (error) {
    return (
      <Card className="border-destructive">
        <CardContent className="p-4">
          <p className="text-destructive text-sm">{error}</p>
          <Button
            onClick={fetchQuotes}
            variant="outline"
            size="sm"
            className="mt-2"
          >
            Retry
          </Button>
        </CardContent>
      </Card>
    );
  }

  if (quotes.length === 0) {
    return (
      <Card>
        <CardContent className="p-4">
          <p className="text-muted-foreground text-sm">
            No logistics partners available for this route.
          </p>
        </CardContent>
      </Card>
    );
  }

  // Find the cheapest quote
  const cheapestQuote = quotes.reduce((min, quote) =>
    quote.quotedPrice < min.quotedPrice ? quote : min,
  );

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h3 className="text-lg font-semibold">Select Logistics Partner</h3>
        <Badge variant="secondary" className="text-xs">
          {quotes.length} options available
        </Badge>
      </div>

      <div className="grid gap-3 md:grid-cols-2">
        {quotes.map((quote) => {
          const isSelected = selectedQuoteId === quote.id;
          const isCheapest = quote.id === cheapestQuote.id;

          return (
            <Card
              key={quote.id}
              className={`cursor-pointer transition-all hover:shadow-md ${
                isSelected
                  ? "border-primary ring-2 ring-primary ring-offset-2"
                  : ""
              }`}
              onClick={() => onSelect(quote)}
            >
              <CardHeader className="pb-3">
                <div className="flex items-start justify-between">
                  <div className="flex items-center gap-2">
                    <Truck className="h-5 w-5 text-primary" />
                    <CardTitle className="text-base">
                      {quote.providerName}
                    </CardTitle>
                  </div>
                  {isSelected && (
                    <Check
                      className="h-5 w-5 text-primary"
                      aria-label="Selected"
                    />
                  )}
                </div>
              </CardHeader>

              <CardContent className="space-y-3">
                {/* Price */}
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-2 text-sm text-muted-foreground">
                    <DollarSign className="h-4 w-4" />
                    <span>Shipping Cost</span>
                  </div>
                  <div className="flex items-center gap-2">
                    <span className="text-lg font-bold">
                      Γéª{quote.quotedPrice.toLocaleString()}
                    </span>
                    {isCheapest && (
                      <Badge variant="default" className="text-xs">
                        Best Price
                      </Badge>
                    )}
                  </div>
                </div>

                {/* Delivery Time */}
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-2 text-sm text-muted-foreground">
                    <Clock className="h-4 w-4" />
                    <span>Delivery Time</span>
                  </div>
                  <span className="text-sm font-medium">
                    {quote.estimatedDeliveryTime}
                  </span>
                </div>

                {/* Valid Until */}
                <div className="text-xs text-muted-foreground">
                  Quote valid until{" "}
                  {new Date(quote.validUntil).toLocaleDateString()}
                </div>
              </CardContent>
            </Card>
          );
        })}
      </div>

      {/* Cost Comparison Summary */}
      <Card className="bg-muted/50">
        <CardContent className="p-4">
          <div className="flex items-center justify-between text-sm">
            <span className="text-muted-foreground">Price Range:</span>
            <span className="font-medium">
              Γéª{Math.min(...quotes.map((q) => q.quotedPrice)).toLocaleString()}{" "}
              - Γéª
              {Math.max(...quotes.map((q) => q.quotedPrice)).toLocaleString()}
            </span>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

"use client";

/**
 * TrackingDashboard Component
 * Task 30.3: Display real-time tracking status and estimated delivery time
 * Requirements: 8.3, 8.5
 */

import { useState, useEffect } from "react";
import { Package, MapPin, Clock, Phone, AlertCircle } from "lucide-react";
import type { TrackingInfo, ShipmentStatus } from "@/lib/types/logistics";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";
import { Alert, AlertDescription } from "@/components/ui/alert";

interface TrackingDashboardProps {
  shipmentId: string;
  onRefresh?: () => void;
}

const statusConfig: Record<
  ShipmentStatus,
  {
    label: string;
    color: string;
    variant: "default" | "secondary" | "destructive" | "outline";
  }
> = {
  pending: {
    label: "Pending Pickup",
    color: "text-gray-500",
    variant: "secondary",
  },
  picked_up: { label: "Picked Up", color: "text-blue-500", variant: "default" },
  in_transit: {
    label: "In Transit",
    color: "text-blue-600",
    variant: "default",
  },
  out_for_delivery: {
    label: "Out for Delivery",
    color: "text-orange-500",
    variant: "default",
  },
  delivered: {
    label: "Delivered",
    color: "text-green-600",
    variant: "default",
  },
  failed: {
    label: "Delivery Failed",
    color: "text-red-600",
    variant: "destructive",
  },
};

export function TrackingDashboard({
  shipmentId,
  onRefresh,
}: TrackingDashboardProps) {
  const [trackingInfo, setTrackingInfo] = useState<TrackingInfo | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [refreshing, setRefreshing] = useState(false);

  useEffect(() => {
    fetchTrackingInfo();
    // Set up polling for real-time updates every 30 seconds
    const interval = setInterval(fetchTrackingInfo, 30000);
    return () => clearInterval(interval);
  }, [shipmentId]);

  const fetchTrackingInfo = async () => {
    try {
      setError(null);
      if (!loading) setRefreshing(true);

      const response = await fetch(`/api/logistics/track/${shipmentId}`);

      if (!response.ok) {
        throw new Error("Failed to fetch tracking information");
      }

      const data = await response.json();
      setTrackingInfo(data.trackingInfo);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An error occurred");
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  };

  const handleRefresh = () => {
    fetchTrackingInfo();
    onRefresh?.();
  };

  if (loading) {
    return (
      <div className="space-y-4">
        <Card>
          <CardHeader>
            <Skeleton className="h-6 w-48" />
          </CardHeader>
          <CardContent className="space-y-4">
            <Skeleton className="h-20 w-full" />
            <Skeleton className="h-32 w-full" />
          </CardContent>
        </Card>
      </div>
    );
  }

  if (error || !trackingInfo) {
    return (
      <Alert variant="destructive">
        <AlertCircle className="h-4 w-4" />
        <AlertDescription>
          {error || "Unable to load tracking information"}
        </AlertDescription>
        <Button
          onClick={handleRefresh}
          variant="outline"
          size="sm"
          className="mt-2"
        >
          Retry
        </Button>
      </Alert>
    );
  }

  const { shipment, provider, history } = trackingInfo;
  const statusInfo = statusConfig[shipment.status];

  return (
    <div className="space-y-4">
      {/* Header Card */}
      <Card>
        <CardHeader>
          <div className="flex items-start justify-between">
            <div className="space-y-1">
              <CardTitle className="flex items-center gap-2">
                <Package className="h-5 w-5" />
                Tracking: {shipment.trackingNumber}
              </CardTitle>
              <p className="text-sm text-muted-foreground">
                via {provider.name}
              </p>
            </div>
            <Button
              onClick={handleRefresh}
              variant="outline"
              size="sm"
              disabled={refreshing}
            >
              {refreshing ? "Updating..." : "Refresh"}
            </Button>
          </div>
        </CardHeader>

        <CardContent className="space-y-4">
          {/* Current Status */}
          <div className="flex items-center justify-between rounded-lg border p-4">
            <div className="space-y-1">
              <p className="text-sm text-muted-foreground">Current Status</p>
              <Badge variant={statusInfo.variant} className="text-sm">
                {statusInfo.label}
              </Badge>
            </div>
            <Package className={`h-8 w-8 ${statusInfo.color}`} />
          </div>

          {/* Current Location */}
          {shipment.currentLocation && (
            <div className="flex items-start gap-3 rounded-lg border p-4">
              <MapPin className="h-5 w-5 text-primary mt-0.5" />
              <div className="space-y-1">
                <p className="text-sm font-medium">Current Location</p>
                <p className="text-sm text-muted-foreground">
                  {shipment.currentLocation}
                </p>
              </div>
            </div>
          )}

          {/* Estimated Delivery */}
          {shipment.estimatedDelivery && shipment.status !== "delivered" && (
            <div className="flex items-start gap-3 rounded-lg border p-4">
              <Clock className="h-5 w-5 text-primary mt-0.5" />
              <div className="space-y-1">
                <p className="text-sm font-medium">Estimated Delivery</p>
                <p className="text-sm text-muted-foreground">
                  {new Date(shipment.estimatedDelivery).toLocaleDateString(
                    "en-US",
                    {
                      weekday: "long",
                      year: "numeric",
                      month: "long",
                      day: "numeric",
                    },
                  )}
                </p>
              </div>
            </div>
          )}

          {/* Actual Delivery */}
          {shipment.actualDelivery && (
            <div className="flex items-start gap-3 rounded-lg border border-green-200 bg-green-50 p-4">
              <Clock className="h-5 w-5 text-green-600 mt-0.5" />
              <div className="space-y-1">
                <p className="text-sm font-medium text-green-900">
                  Delivered On
                </p>
                <p className="text-sm text-green-700">
                  {new Date(shipment.actualDelivery).toLocaleDateString(
                    "en-US",
                    {
                      weekday: "long",
                      year: "numeric",
                      month: "long",
                      day: "numeric",
                      hour: "2-digit",
                      minute: "2-digit",
                    },
                  )}
                </p>
              </div>
            </div>
          )}

          {/* Delivery Person Contact (when out for delivery) */}
          {shipment.status === "out_for_delivery" &&
            shipment.deliveryPerson && (
              <div className="flex items-start gap-3 rounded-lg border border-orange-200 bg-orange-50 p-4">
                <Phone className="h-5 w-5 text-orange-600 mt-0.5" />
                <div className="flex-1 space-y-2">
                  <p className="text-sm font-medium text-orange-900">
                    Delivery Person
                  </p>
                  <div className="space-y-1">
                    <p className="text-sm text-orange-700">
                      {shipment.deliveryPerson.name}
                    </p>
                    <a
                      href={`tel:${shipment.deliveryPerson.phone}`}
                      className="text-sm font-medium text-orange-600 hover:underline"
                    >
                      {shipment.deliveryPerson.phone}
                    </a>
                  </div>
                </div>
              </div>
            )}

          {/* Delivery Failure */}
          {shipment.status === "failed" && shipment.failureReason && (
            <Alert variant="destructive">
              <AlertCircle className="h-4 w-4" />
              <AlertDescription>
                <p className="font-medium">Delivery Failed</p>
                <p className="text-sm mt-1">{shipment.failureReason}</p>
                {shipment.failureTimestamp && (
                  <p className="text-xs mt-1">
                    Failed at:{" "}
                    {new Date(shipment.failureTimestamp).toLocaleString()}
                  </p>
                )}
              </AlertDescription>
            </Alert>
          )}
        </CardContent>
      </Card>

      {/* Delivery Addresses */}
      <Card>
        <CardHeader>
          <CardTitle className="text-base">Delivery Details</CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="space-y-2">
            <p className="text-sm font-medium">From</p>
            <p className="text-sm text-muted-foreground">
              {shipment.pickupAddress.street}, {shipment.pickupAddress.city},{" "}
              {shipment.pickupAddress.state}
            </p>
            <p className="text-xs text-muted-foreground">
              Contact: {shipment.pickupAddress.contactName} (
              {shipment.pickupAddress.contactPhone})
            </p>
          </div>

          <div className="border-t pt-4 space-y-2">
            <p className="text-sm font-medium">To</p>
            <p className="text-sm text-muted-foreground">
              {shipment.deliveryAddress.street}, {shipment.deliveryAddress.city}
              , {shipment.deliveryAddress.state}
            </p>
            <p className="text-xs text-muted-foreground">
              Contact: {shipment.deliveryAddress.contactName} (
              {shipment.deliveryAddress.contactPhone})
            </p>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

"use client";

/**
 * TrackingPage Component
 * Comprehensive tracking page combining all logistics components
 * Tasks: 30.1, 30.3, 30.5, 30.10
 */

import { useState, useEffect } from "react";
import type { TrackingInfo } from "@/lib/types/logistics";
import { TrackingDashboard } from "./tracking-dashboard";
import { DeliveryTimeline } from "./delivery-timeline";
import { DeliveryRating } from "./delivery-rating";
import { Skeleton } from "@/components/ui/skeleton";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { AlertCircle } from "lucide-react";

interface TrackingPageProps {
  shipmentId: string;
}

export function TrackingPage({ shipmentId }: TrackingPageProps) {
  const [trackingInfo, setTrackingInfo] = useState<TrackingInfo | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchTrackingInfo();
  }, [shipmentId]);

  const fetchTrackingInfo = async () => {
    try {
      setLoading(true);
      setError(null);

      const response = await fetch(`/api/logistics/track/${shipmentId}`);

      if (!response.ok) {
        throw new Error("Failed to fetch tracking information");
      }

      const data = await response.json();
      setTrackingInfo(data.trackingInfo);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An error occurred");
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <div className="container max-w-4xl mx-auto p-4 space-y-6">
        <Skeleton className="h-64 w-full" />
        <Skeleton className="h-96 w-full" />
      </div>
    );
  }

  if (error || !trackingInfo) {
    return (
      <div className="container max-w-4xl mx-auto p-4">
        <Alert variant="destructive">
          <AlertCircle className="h-4 w-4" />
          <AlertDescription>
            {error || "Unable to load tracking information"}
          </AlertDescription>
        </Alert>
      </div>
    );
  }

  const { shipment, provider, history } = trackingInfo;
  const canRate = shipment.status === "delivered" && !shipment.deliveryRating;

  return (
    <div className="container max-w-4xl mx-auto p-4 space-y-6">
      {/* Main Tracking Dashboard */}
      <TrackingDashboard
        shipmentId={shipmentId}
        onRefresh={fetchTrackingInfo}
      />

      {/* Delivery Timeline */}
      <DeliveryTimeline currentStatus={shipment.status} history={history} />

      {/* Delivery Rating (only show if delivered and not yet rated) */}
      {canRate && (
        <DeliveryRating
          shipmentId={shipmentId}
          providerName={provider.name}
          onRatingSubmitted={fetchTrackingInfo}
        />
      )}

      {/* Show existing rating if already rated */}
      {shipment.deliveryRating && (
        <DeliveryRating
          shipmentId={shipmentId}
          providerName={provider.name}
          existingRating={shipment.deliveryRating}
          existingReview={shipment.deliveryReview}
        />
      )}
    </div>
  );
}

"use client";

/**
 * Meetup Check-In Component
 * Allows users to check in at meetup location
 * Requirements: 21.5, 21.10
 */

import { useState } from "react";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import {
  MapPin,
  CheckCircle,
  Clock,
  User,
  AlertCircle,
  Share2,
} from "lucide-react";
import { format } from "date-fns";

interface Meetup {
  id: string;
  location_name: string;
  location_address: string;
  scheduled_time: Date;
  buyer_checked_in: boolean;
  seller_checked_in: boolean;
  buyer_checked_in_at?: Date;
  seller_checked_in_at?: Date;
  status: string;
}

interface MeetupCheckInProps {
  meetup: Meetup;
  userType: "buyer" | "seller";
  onCheckIn?: () => void;
  onComplete?: () => void;
}

export function MeetupCheckIn({
  meetup,
  userType,
  onCheckIn,
  onComplete,
}: MeetupCheckInProps) {
  const [loading, setLoading] = useState(false);
  const [showLocationShare, setShowLocationShare] = useState(false);

  const isUserCheckedIn =
    userType === "buyer" ? meetup.buyer_checked_in : meetup.seller_checked_in;
  const isOtherCheckedIn =
    userType === "buyer" ? meetup.seller_checked_in : meetup.buyer_checked_in;
  const bothCheckedIn = meetup.buyer_checked_in && meetup.seller_checked_in;

  const handleCheckIn = async () => {
    try {
      setLoading(true);

      const response = await fetch(`/api/meetups/${meetup.id}/check-in`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ userType }),
      });

      if (!response.ok) throw new Error("Failed to check in");

      const data = await response.json();

      if (data.bothCheckedIn) {
        // Both parties checked in, show completion prompt
        onComplete?.();
      } else {
        onCheckIn?.();
      }
    } catch (error) {
      console.error("Error checking in:", error);
      alert("Failed to check in");
    } finally {
      setLoading(false);
    }
  };

  const handleShareLocation = () => {
    if (navigator.share && navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (position) => {
          const { latitude, longitude } = position.coords;
          const locationUrl = `https://www.google.com/maps?q=${latitude},${longitude}`;

          navigator
            .share({
              title: "My Current Location",
              text: "I'm at the meetup location",
              url: locationUrl,
            })
            .catch((error) => console.error("Error sharing:", error));
        },
        (error) => {
          console.error("Error getting location:", error);
          alert("Unable to get your location");
        },
      );
    } else {
      alert("Location sharing is not supported on this device");
    }
  };

  return (
    <div className="space-y-4">
      {/* Meetup Details */}
      <Card className="p-6">
        <div className="flex items-start gap-4 mb-4">
          <MapPin className="h-6 w-6 text-primary mt-1" />
          <div className="flex-1">
            <h3 className="font-semibold text-lg mb-1">
              {meetup.location_name}
            </h3>
            <p className="text-sm text-muted-foreground mb-2">
              {meetup.location_address}
            </p>
            <div className="flex items-center gap-2 text-sm text-muted-foreground">
              <Clock className="h-4 w-4" />
              {format(new Date(meetup.scheduled_time), "PPpp")}
            </div>
          </div>
        </div>

        {/* Check-in Status */}
        <div className="space-y-3 mb-4">
          <div
            className={`flex items-center gap-3 p-3 rounded-lg ${
              isUserCheckedIn ? "bg-green-50" : "bg-muted/50"
            }`}
          >
            {isUserCheckedIn ? (
              <CheckCircle className="h-5 w-5 text-green-500" />
            ) : (
              <User className="h-5 w-5 text-muted-foreground" />
            )}
            <div className="flex-1">
              <p className="font-medium">
                You ({userType === "buyer" ? "Buyer" : "Seller"})
              </p>
              {isUserCheckedIn && meetup[`${userType}_checked_in_at`] && (
                <p className="text-xs text-muted-foreground">
                  Checked in at{" "}
                  {format(new Date(meetup[`${userType}_checked_in_at`]!), "p")}
                </p>
              )}
            </div>
            {isUserCheckedIn && (
              <span className="text-sm text-green-600 font-medium">
                Checked In
              </span>
            )}
          </div>

          <div
            className={`flex items-center gap-3 p-3 rounded-lg ${
              isOtherCheckedIn ? "bg-green-50" : "bg-muted/50"
            }`}
          >
            {isOtherCheckedIn ? (
              <CheckCircle className="h-5 w-5 text-green-500" />
            ) : (
              <User className="h-5 w-5 text-muted-foreground" />
            )}
            <div className="flex-1">
              <p className="font-medium">
                {userType === "buyer" ? "Seller" : "Buyer"}
              </p>
              {isOtherCheckedIn &&
                meetup[
                  `${userType === "buyer" ? "seller" : "buyer"}_checked_in_at`
                ] && (
                  <p className="text-xs text-muted-foreground">
                    Checked in at{" "}
                    {format(
                      new Date(
                        meetup[
                          `${userType === "buyer" ? "seller" : "buyer"}_checked_in_at`
                        ]!,
                      ),
                      "p",
                    )}
                  </p>
                )}
            </div>
            {isOtherCheckedIn && (
              <span className="text-sm text-green-600 font-medium">
                Checked In
              </span>
            )}
          </div>
        </div>

        {/* Actions */}
        {!isUserCheckedIn && (
          <div className="space-y-3">
            <Button
              onClick={handleCheckIn}
              disabled={loading}
              className="w-full"
            >
              <CheckCircle className="h-4 w-4 mr-2" />
              {loading ? "Checking In..." : "Check In at Location"}
            </Button>

            <Button
              variant="outline"
              onClick={handleShareLocation}
              className="w-full"
            >
              <Share2 className="h-4 w-4 mr-2" />
              Share Live Location
            </Button>
          </div>
        )}

        {/* Completion Prompt */}
        {bothCheckedIn && (
          <div className="bg-green-50 border border-green-200 rounded-lg p-4">
            <div className="flex items-start gap-3">
              <CheckCircle className="h-5 w-5 text-green-500 mt-0.5" />
              <div>
                <p className="font-medium text-green-900 mb-1">
                  Both parties have checked in!
                </p>
                <p className="text-sm text-green-700 mb-3">
                  Please complete the transaction and confirm when done.
                </p>
                <Button size="sm" onClick={onComplete}>
                  Complete Transaction
                </Button>
              </div>
            </div>
          </div>
        )}

        {/* Waiting Message */}
        {isUserCheckedIn && !isOtherCheckedIn && (
          <div className="bg-blue-50 border border-blue-200 rounded-lg p-4">
            <div className="flex items-start gap-3">
              <AlertCircle className="h-5 w-5 text-blue-500 mt-0.5" />
              <div>
                <p className="font-medium text-blue-900 mb-1">
                  Waiting for other party
                </p>
                <p className="text-sm text-blue-700">
                  The {userType === "buyer" ? "seller" : "buyer"} hasn't checked
                  in yet. You'll be notified when they arrive.
                </p>
              </div>
            </div>
          </div>
        )}
      </Card>
    </div>
  );
}

"use client";

/**
 * Meetup Coordinator Component
 * Displays safe location suggestions and handles meetup scheduling
 * Requirements: 21.1, 21.2, 21.3, 21.4, 21.5, 21.6, 21.7, 21.8
 */

import { useState, useEffect } from "react";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  MapPin,
  Clock,
  Shield,
  CheckCircle,
  AlertTriangle,
  Navigation,
  Calendar,
  X,
} from "lucide-react";
import { format } from "date-fns";

interface SafeLocation {
  id: string;
  name: string;
  type: string;
  address: string;
  latitude: number;
  longitude: number;
  distance_from_buyer?: number;
  distance_from_seller?: number;
}

interface MeetupCoordinatorProps {
  transactionId: string;
  buyerId: string;
  sellerId: string;
  buyerLocation?: { lat: number; lng: number };
  sellerLocation?: { lat: number; lng: number };
  onScheduled?: (meetupId: string) => void;
}

export function MeetupCoordinator({
  transactionId,
  buyerId,
  sellerId,
  buyerLocation,
  sellerLocation,
  onScheduled,
}: MeetupCoordinatorProps) {
  const [safeLocations, setSafeLocations] = useState<SafeLocation[]>([]);
  const [selectedLocation, setSelectedLocation] = useState<SafeLocation | null>(
    null,
  );
  const [scheduledTime, setScheduledTime] = useState("");
  const [loading, setLoading] = useState(false);
  const [showSafetyTips, setShowSafetyTips] = useState(false);
  const [safetyTips, setSafetyTips] = useState<string[]>([]);
  const [safetyTipsAcknowledged, setSafetyTipsAcknowledged] = useState(false);

  useEffect(() => {
    if (buyerLocation && sellerLocation) {
      fetchSafeLocations();
    }
    fetchSafetyTips();
  }, [buyerLocation, sellerLocation]);

  const fetchSafeLocations = async () => {
    if (!buyerLocation || !sellerLocation) return;

    try {
      const response = await fetch(
        `/api/meetups/safe-locations?` +
          `buyerLat=${buyerLocation.lat}&buyerLng=${buyerLocation.lng}&` +
          `sellerLat=${sellerLocation.lat}&sellerLng=${sellerLocation.lng}`,
      );

      if (!response.ok) throw new Error("Failed to fetch safe locations");

      const data = await response.json();
      setSafeLocations(data.locations || []);
    } catch (error) {
      console.error("Error fetching safe locations:", error);
    }
  };

  const fetchSafetyTips = async () => {
    try {
      const response = await fetch("/api/meetups/safety-tips");
      if (!response.ok) throw new Error("Failed to fetch safety tips");

      const data = await response.json();
      setSafetyTips(data.tips || []);
    } catch (error) {
      console.error("Error fetching safety tips:", error);
    }
  };

  const handleScheduleMeetup = async () => {
    if (!selectedLocation || !scheduledTime || !safetyTipsAcknowledged) {
      alert("Please select a location, time, and acknowledge safety tips");
      return;
    }

    try {
      setLoading(true);

      const response = await fetch("/api/meetups", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          transaction_id: transactionId,
          buyer_id: buyerId,
          seller_id: sellerId,
          location_name: selectedLocation.name,
          location_address: selectedLocation.address,
          location_latitude: selectedLocation.latitude,
          location_longitude: selectedLocation.longitude,
          scheduled_time: new Date(scheduledTime).toISOString(),
        }),
      });

      if (!response.ok) throw new Error("Failed to schedule meetup");

      const data = await response.json();
      onScheduled?.(data.meetup.id);
    } catch (error) {
      console.error("Error scheduling meetup:", error);
      alert("Failed to schedule meetup");
    } finally {
      setLoading(false);
    }
  };

  const getLocationTypeIcon = (type: string) => {
    switch (type) {
      case "police_station":
        return <Shield className="h-5 w-5 text-blue-500" />;
      case "bank":
        return <MapPin className="h-5 w-5 text-green-500" />;
      case "shopping_mall":
        return <MapPin className="h-5 w-5 text-purple-500" />;
      default:
        return <MapPin className="h-5 w-5 text-gray-500" />;
    }
  };

  const getLocationTypeLabel = (type: string) => {
    return type
      .split("_")
      .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
      .join(" ");
  };

  return (
    <div className="space-y-6">
      {/* Safety Tips Modal */}
      {showSafetyTips && (
        <Card className="p-6 border-2 border-yellow-500">
          <div className="flex items-start justify-between mb-4">
            <div className="flex items-center gap-2">
              <AlertTriangle className="h-6 w-6 text-yellow-500" />
              <h3 className="text-lg font-semibold">Safety Tips</h3>
            </div>
            <Button
              variant="ghost"
              size="sm"
              onClick={() => setShowSafetyTips(false)}
            >
              <X className="h-4 w-4" />
            </Button>
          </div>

          <div className="space-y-3 mb-4">
            {safetyTips.map((tip, index) => (
              <div key={index} className="flex items-start gap-2">
                <CheckCircle className="h-4 w-4 text-green-500 mt-0.5 flex-shrink-0" />
                <p className="text-sm text-muted-foreground">{tip}</p>
              </div>
            ))}
          </div>

          <div className="flex items-center gap-2">
            <input
              type="checkbox"
              id="acknowledge-tips"
              checked={safetyTipsAcknowledged}
              onChange={(e) => setSafetyTipsAcknowledged(e.target.checked)}
              className="rounded border-gray-300"
              aria-label="Acknowledge safety tips"
              title="Check to confirm you have read and understood the safety tips"
            />
            <Label
              htmlFor="acknowledge-tips"
              className="text-sm cursor-pointer"
            >
              I have read and understood these safety tips
            </Label>
          </div>
        </Card>
      )}

      {/* Header */}
      <div className="flex items-center justify-between">
        <h2 className="text-2xl font-bold">Schedule Safe Meetup</h2>
        <Button
          variant="outline"
          size="sm"
          onClick={() => setShowSafetyTips(true)}
        >
          <Shield className="h-4 w-4 mr-2" />
          Safety Tips
        </Button>
      </div>

      {/* Safe Locations */}
      <div>
        <h3 className="text-lg font-semibold mb-4">Verified Safe Locations</h3>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {safeLocations.map((location) => (
            <Card
              key={location.id}
              className={`p-4 cursor-pointer transition-all ${
                selectedLocation?.id === location.id
                  ? "border-2 border-primary bg-primary/5"
                  : "hover:border-primary/50"
              }`}
              onClick={() => setSelectedLocation(location)}
            >
              <div className="flex items-start gap-3">
                <div className="mt-1">{getLocationTypeIcon(location.type)}</div>
                <div className="flex-1 min-w-0">
                  <div className="flex items-start justify-between mb-2">
                    <div>
                      <h4 className="font-semibold truncate">
                        {location.name}
                      </h4>
                      <p className="text-sm text-muted-foreground">
                        {getLocationTypeLabel(location.type)}
                      </p>
                    </div>
                    {selectedLocation?.id === location.id && (
                      <CheckCircle className="h-5 w-5 text-primary flex-shrink-0" />
                    )}
                  </div>

                  <p className="text-sm text-muted-foreground mb-3">
                    {location.address}
                  </p>

                  <div className="flex items-center gap-4 text-xs text-muted-foreground">
                    {location.distance_from_buyer !== undefined && (
                      <div className="flex items-center gap-1">
                        <Navigation className="h-3 w-3" />
                        <span>
                          {location.distance_from_buyer.toFixed(1)}km from you
                        </span>
                      </div>
                    )}
                    {location.distance_from_seller !== undefined && (
                      <div className="flex items-center gap-1">
                        <Navigation className="h-3 w-3" />
                        <span>
                          {location.distance_from_seller.toFixed(1)}km from
                          seller
                        </span>
                      </div>
                    )}
                  </div>
                </div>
              </div>
            </Card>
          ))}
        </div>

        {safeLocations.length === 0 && (
          <Card className="p-8">
            <div className="text-center text-muted-foreground">
              <MapPin className="h-12 w-12 mx-auto mb-4 opacity-50" />
              <p>
                Enable location access to see safe meetup locations near you
              </p>
            </div>
          </Card>
        )}
      </div>

      {/* Schedule Time */}
      {selectedLocation && (
        <Card className="p-6">
          <h3 className="text-lg font-semibold mb-4">Select Date & Time</h3>
          <div className="space-y-4">
            <div>
              <Label htmlFor="scheduled-time">Meetup Time</Label>
              <div className="flex items-center gap-2 mt-2">
                <Calendar className="h-5 w-5 text-muted-foreground" />
                <Input
                  id="scheduled-time"
                  type="datetime-local"
                  value={scheduledTime}
                  onChange={(e) => setScheduledTime(e.target.value)}
                  min={new Date().toISOString().slice(0, 16)}
                  className="flex-1"
                />
              </div>
            </div>

            {scheduledTime && (
              <div className="bg-muted/50 rounded-lg p-4">
                <div className="flex items-start gap-3">
                  <Clock className="h-5 w-5 text-primary mt-0.5" />
                  <div>
                    <p className="font-medium mb-1">Meetup Summary</p>
                    <p className="text-sm text-muted-foreground mb-2">
                      {selectedLocation.name}
                    </p>
                    <p className="text-sm text-muted-foreground">
                      {format(new Date(scheduledTime), "PPpp")}
                    </p>
                  </div>
                </div>
              </div>
            )}

            <div className="flex gap-2">
              <Button
                onClick={handleScheduleMeetup}
                disabled={loading || !scheduledTime || !safetyTipsAcknowledged}
                className="flex-1"
              >
                {loading ? "Scheduling..." : "Schedule Meetup"}
              </Button>
              <Button
                variant="outline"
                onClick={() => {
                  setSelectedLocation(null);
                  setScheduledTime("");
                }}
              >
                Cancel
              </Button>
            </div>

            {!safetyTipsAcknowledged && (
              <p className="text-sm text-yellow-600 flex items-center gap-2">
                <AlertTriangle className="h-4 w-4" />
                Please read and acknowledge the safety tips before scheduling
              </p>
            )}
          </div>
        </Card>
      )}
    </div>
  );
}

"use client";

import { useNotifications } from "@/lib/hooks/useNotifications";
import { NotificationItem } from "./notification-item";
import { Button } from "@/components/ui/button";
import { Check, Settings, Trash2 } from "lucide-react";
import Link from "next/link";
import { motion } from "framer-motion";

interface NotificationDropdownProps {
  onClose: () => void;
}

export function NotificationDropdown({ onClose }: NotificationDropdownProps) {
  const { notifications, isLoading, markAllAsRead } = useNotifications();

  const handleMarkAllAsRead = async () => {
    try {
      await markAllAsRead();
    } catch (error) {
      console.error("Error marking all as read:", error);
    }
  };

  return (
    <div className="w-[400px] max-w-[calc(100vw-2rem)] bg-dark-card border border-dark-border rounded-lg shadow-2xl overflow-hidden">
      {/* Header */}
      <div className="p-4 border-b border-dark-border bg-dark-bg">
        <div className="flex items-center justify-between mb-3">
          <h3 className="text-lg font-bold text-white">Notifications</h3>
          <Link
            href="/notifications/preferences"
            onClick={onClose}
            className="p-2 hover:bg-dark-card rounded-full transition-colors"
          >
            <Settings className="w-5 h-5 text-gray-400 hover:text-white" />
          </Link>
        </div>

        {notifications.length > 0 && (
          <Button
            variant="ghost"
            size="sm"
            onClick={handleMarkAllAsRead}
            className="w-full text-naija-green hover:text-naija-green hover:bg-naija-green/10"
          >
            <Check className="w-4 h-4 mr-2" />
            Mark all as read
          </Button>
        )}
      </div>

      {/* Notification List */}
      <div className="max-h-[500px] overflow-y-auto">
        {isLoading ? (
          <div className="flex items-center justify-center py-12">
            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-naija-green" />
          </div>
        ) : notifications.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-12 px-4 text-gray-400">
            <div className="w-16 h-16 rounded-full bg-dark-bg flex items-center justify-center mb-4">
              <Check className="w-8 h-8" />
            </div>
            <p className="text-center">You're all caught up!</p>
            <p className="text-sm text-center mt-1">No new notifications</p>
          </div>
        ) : (
          <div className="divide-y divide-dark-border">
            {notifications.slice(0, 10).map((notification, index) => (
              <motion.div
                key={notification.id}
                initial={{ opacity: 0, x: -20 }}
                animate={{ opacity: 1, x: 0 }}
                transition={{ delay: index * 0.05 }}
              >
                <NotificationItem
                  notification={notification}
                  onClose={onClose}
                />
              </motion.div>
            ))}
          </div>
        )}
      </div>

      {/* Footer */}
      {notifications.length > 10 && (
        <div className="p-3 border-t border-dark-border bg-dark-bg">
          <Link
            href="/notifications"
            onClick={onClose}
            className="block text-center text-sm text-naija-green hover:text-neon-cyan transition-colors"
          >
            View all notifications
          </Link>
        </div>
      )}
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { motion } from "framer-motion";
import { Plus, Briefcase } from "lucide-react";
import { Button } from "@/components/ui/button";
import { PortfolioGrid } from "./portfolio-grid";
import { PortfolioUploadModal } from "./portfolio-upload-modal";
import { PortfolioLightbox } from "./portfolio-lightbox";
import { CVUpload } from "./cv-upload";
import { SkillsList } from "./skills-list";
import { PortfolioItem, User } from "@/lib/types";
import { toast } from "sonner";

interface PortfolioSectionProps {
  user: User;
  isOwner?: boolean;
}

export function PortfolioSection({
  user,
  isOwner = false,
}: PortfolioSectionProps) {
  const [portfolioItems, setPortfolioItems] = useState<PortfolioItem[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isUploadModalOpen, setIsUploadModalOpen] = useState(false);
  const [lightboxIndex, setLightboxIndex] = useState<number | null>(null);

  // Fetch portfolio items
  useEffect(() => {
    fetchPortfolioItems();
  }, [user.id]);

  const fetchPortfolioItems = async () => {
    try {
      const response = await fetch(`/api/portfolio?user_id=${user.id}`);
      if (!response.ok) throw new Error("Failed to fetch portfolio");

      const { data } = await response.json();
      setPortfolioItems(data || []);
    } catch (error) {
      console.error("Error fetching portfolio:", error);
      toast.error("Failed to load portfolio");
    } finally {
      setIsLoading(false);
    }
  };

  const handleUpload = async (data: {
    title: string;
    description: string;
    file: File;
  }) => {
    try {
      // Upload media first
      const formData = new FormData();
      formData.append("file", data.file);

      const uploadResponse = await fetch("/api/portfolio/upload", {
        method: "POST",
        body: formData,
      });

      if (!uploadResponse.ok) throw new Error("Failed to upload media");

      const { url, media_type } = await uploadResponse.json();

      // Create portfolio item
      const createResponse = await fetch("/api/portfolio", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          title: data.title,
          description: data.description,
          media_url: url,
          media_type,
          display_order: portfolioItems.length,
        }),
      });

      if (!createResponse.ok)
        throw new Error("Failed to create portfolio item");

      const { data: newItem } = await createResponse.json();
      setPortfolioItems([...portfolioItems, newItem]);
      toast.success("Portfolio item added successfully");
    } catch (error) {
      console.error("Error uploading portfolio item:", error);
      throw error;
    }
  };

  const handleDelete = async (id: string) => {
    if (!confirm("Are you sure you want to delete this portfolio item?"))
      return;

    try {
      const response = await fetch(`/api/portfolio/${id}`, {
        method: "DELETE",
      });

      if (!response.ok) throw new Error("Failed to delete portfolio item");

      setPortfolioItems(portfolioItems.filter((item) => item.id !== id));
      toast.success("Portfolio item deleted");
    } catch (error) {
      console.error("Error deleting portfolio item:", error);
      toast.error("Failed to delete portfolio item");
    }
  };

  const handleCVUpload = async (file: File) => {
    try {
      const formData = new FormData();
      formData.append("file", file);

      const response = await fetch("/api/portfolio/cv", {
        method: "POST",
        body: formData,
      });

      if (!response.ok) throw new Error("Failed to upload CV");

      const { url } = await response.json();
      toast.success("CV uploaded successfully");

      // Update local user state (you might want to refresh user data)
      window.location.reload();
    } catch (error) {
      console.error("Error uploading CV:", error);
      throw error;
    }
  };

  const handleCVDelete = async () => {
    try {
      const response = await fetch("/api/portfolio/cv", {
        method: "DELETE",
      });

      if (!response.ok) throw new Error("Failed to delete CV");

      toast.success("CV deleted");
      window.location.reload();
    } catch (error) {
      console.error("Error deleting CV:", error);
      throw error;
    }
  };

  const handleSkillsUpdate = async (skills: string[]) => {
    try {
      const response = await fetch("/api/portfolio/skills", {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ skills }),
      });

      if (!response.ok) throw new Error("Failed to update skills");

      toast.success("Skills updated successfully");
    } catch (error) {
      console.error("Error updating skills:", error);
      throw error;
    }
  };

  // Don't show portfolio section if user is not a service provider or job seeker
  if (!isOwner && !user.is_service_provider && !user.is_job_seeker) {
    return null;
  }

  return (
    <div className="space-y-8">
      {/* Service Provider Portfolio */}
      {(user.is_service_provider || isOwner) && (
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          className="bg-dark-card border border-dark-border rounded-lg p-6"
        >
          <div className="flex items-center justify-between mb-6">
            <div className="flex items-center gap-3">
              <div className="bg-naija-green/10 rounded-lg p-3">
                <Briefcase className="w-6 h-6 text-naija-green" />
              </div>
              <div>
                <h2 className="text-xl font-bold text-white">Portfolio</h2>
                <p className="text-sm text-gray-400">Showcase your best work</p>
              </div>
            </div>

            {isOwner && (
              <Button
                onClick={() => setIsUploadModalOpen(true)}
                className="flex items-center gap-2"
              >
                <Plus className="w-4 h-4" />
                Add Item
              </Button>
            )}
          </div>

          {isLoading ? (
            <div className="text-center py-12 text-gray-400">
              Loading portfolio...
            </div>
          ) : (
            <PortfolioGrid
              items={portfolioItems}
              onItemClick={(item) => {
                const index = portfolioItems.findIndex((i) => i.id === item.id);
                setLightboxIndex(index);
              }}
              editable={isOwner}
              onDelete={handleDelete}
            />
          )}
        </motion.div>
      )}

      {/* Job Seeker CV and Skills */}
      {(user.is_job_seeker || isOwner) && (
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.1 }}
          className="bg-dark-card border border-dark-border rounded-lg p-6 space-y-6"
        >
          {isOwner && (
            <CVUpload
              currentCvUrl={user.cv_url ?? undefined}
              onUpload={handleCVUpload}
              onDelete={handleCVDelete}
            />
          )}

          {!isOwner && user.cv_url && (
            <div>
              <h3 className="text-lg font-semibold text-white mb-4">
                CV / Resume
              </h3>
              <a
                href={user.cv_url}
                target="_blank"
                rel="noopener noreferrer"
                className="inline-flex items-center gap-2 bg-naija-green hover:bg-naija-green/80 text-white px-4 py-2 rounded-lg transition-colors"
              >
                Download CV
              </a>
            </div>
          )}

          <SkillsList
            skills={user.skills || []}
            editable={isOwner}
            onUpdate={handleSkillsUpdate}
          />
        </motion.div>
      )}

      {/* Upload Modal */}
      <PortfolioUploadModal
        isOpen={isUploadModalOpen}
        onClose={() => setIsUploadModalOpen(false)}
        onUpload={handleUpload}
      />

      {/* Lightbox */}
      {lightboxIndex !== null && (
        <PortfolioLightbox
          items={portfolioItems}
          currentIndex={lightboxIndex}
          isOpen={lightboxIndex !== null}
          onClose={() => setLightboxIndex(null)}
          onNavigate={setLightboxIndex}
        />
      )}
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import {
  Swords,
  TrendingDown,
  TrendingUp,
  Clock,
  CheckCircle,
  XCircle,
  Trophy,
  Zap,
} from "lucide-react";
import {
  PriceDropBattle,
  BattleOffer,
  PriceDropBattleService,
} from "@/lib/services/price-drop-battle";

interface PriceDropBattleGameProps {
  battle: PriceDropBattle;
  userId: string;
  onBattleUpdate?: (battle: PriceDropBattle) => void;
  onBattleComplete?: (battle: PriceDropBattle) => void;
}

const battleService = new PriceDropBattleService();

export function PriceDropBattleGame({
  battle: initialBattle,
  userId,
  onBattleUpdate,
  onBattleComplete,
}: PriceDropBattleGameProps) {
  const [battle, setBattle] = useState<PriceDropBattle>(initialBattle);
  const [offers, setOffers] = useState<BattleOffer[]>([]);
  const [counterOffer, setCounterOffer] = useState<string>("");
  const [message, setMessage] = useState<string>("");
  const [loading, setLoading] = useState(false);
  const [timeRemaining, setTimeRemaining] = useState<number>(0);
  const [showCelebration, setShowCelebration] = useState(false);

  const userRole = battleService.getUserRole(battle, userId);
  const isUserTurn = battleService.isUserTurn(battle, userId);
  const savings = battleService.calculateSavings(battle);
  const savingsPercentage = battleService.calculateSavingsPercentage(battle);

  useEffect(() => {
    loadOffers();
  }, [battle.id]);

  useEffect(() => {
    // Update time remaining every second
    const interval = setInterval(() => {
      const remaining = battleService.getTimeRemaining(battle);
      setTimeRemaining(remaining);

      if (remaining === 0 && battle.status === "active") {
        // Battle expired, reload
        reloadBattle();
      }
    }, 1000);

    return () => clearInterval(interval);
  }, [battle]);

  const loadOffers = async () => {
    try {
      const data = await battleService.getBattleOffers(battle.id);
      setOffers(data);
    } catch (error) {
      console.error("Failed to load offers:", error);
    }
  };

  const reloadBattle = async () => {
    try {
      const updated = await battleService.getBattleById(battle.id);
      if (updated) {
        setBattle(updated);
        onBattleUpdate?.(updated);
      }
    } catch (error) {
      console.error("Failed to reload battle:", error);
    }
  };

  const handleMakeOffer = async () => {
    if (!counterOffer || loading) return;

    const offerAmount = parseFloat(counterOffer);
    if (isNaN(offerAmount) || offerAmount <= 0) return;

    setLoading(true);
    try {
      await battleService.makeCounterOffer(battle.id, offerAmount, message);
      await reloadBattle();
      await loadOffers();
      setCounterOffer("");
      setMessage("");
    } catch (error: any) {
      alert(error.message || "Failed to make offer");
    } finally {
      setLoading(false);
    }
  };

  const handleAcceptOffer = async () => {
    if (loading) return;

    setLoading(true);
    try {
      const updated = await battleService.acceptOffer(battle.id);
      setBattle(updated);
      setShowCelebration(true);
      onBattleComplete?.(updated);

      // Trigger celebration effect
      setTimeout(() => setShowCelebration(false), 3000);
    } catch (error: any) {
      alert(error.message || "Failed to accept offer");
    } finally {
      setLoading(false);
    }
  };

  const handleRejectBattle = async () => {
    if (loading) return;
    if (!confirm("Are you sure you want to reject this negotiation?")) return;

    setLoading(true);
    try {
      const updated = await battleService.rejectBattle(battle.id);
      setBattle(updated);
      onBattleComplete?.(updated);
    } catch (error: any) {
      alert(error.message || "Failed to reject battle");
    } finally {
      setLoading(false);
    }
  };

  const formatTime = (ms: number): string => {
    const minutes = Math.floor(ms / 60000);
    const seconds = Math.floor((ms % 60000) / 1000);
    return `${minutes}:${seconds.toString().padStart(2, "0")}`;
  };

  const formatCurrency = (amount: number): string => {
    return `Γéª${amount.toLocaleString()}`;
  };

  if (battle.status === "accepted") {
    return (
      <div className="rounded-lg border-2 border-green-500 bg-green-50 p-8 text-center">
        {showCelebration && (
          <div className="mb-4 animate-bounce">
            <Trophy className="mx-auto h-16 w-16 text-yellow-500" />
          </div>
        )}
        <CheckCircle className="mx-auto h-12 w-12 text-green-600" />
        <h3 className="mt-4 text-2xl font-bold text-gray-900">
          Deal Accepted! ≡ƒÄë
        </h3>
        <p className="mt-2 text-lg text-gray-700">
          Final Price:{" "}
          {formatCurrency(battle.final_price || battle.current_offer)}
        </p>
        <p className="mt-1 text-green-600">
          Saved {formatCurrency(savings)} ({savingsPercentage.toFixed(1)}% off)
        </p>
      </div>
    );
  }

  if (battle.status === "rejected" || battle.status === "cancelled") {
    return (
      <div className="rounded-lg border-2 border-red-500 bg-red-50 p-8 text-center">
        <XCircle className="mx-auto h-12 w-12 text-red-600" />
        <h3 className="mt-4 text-2xl font-bold text-gray-900">Battle Ended</h3>
        <p className="mt-2 text-gray-700">
          This negotiation was {battle.status}
        </p>
      </div>
    );
  }

  if (battle.status === "expired") {
    return (
      <div className="rounded-lg border-2 border-gray-500 bg-gray-50 p-8 text-center">
        <Clock className="mx-auto h-12 w-12 text-gray-600" />
        <h3 className="mt-4 text-2xl font-bold text-gray-900">
          Battle Expired
        </h3>
        <p className="mt-2 text-gray-700">Time ran out for this negotiation</p>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Battle Header */}
      <div className="rounded-lg border-2 border-blue-500 bg-gradient-to-r from-blue-50 to-purple-50 p-6">
        <div className="flex items-center justify-between">
          <div className="flex items-center space-x-3">
            <div className="rounded-full bg-blue-600 p-3">
              <Swords className="h-6 w-6 text-white" />
            </div>
            <div>
              <h3 className="text-xl font-bold text-gray-900">
                Price Drop Battle
              </h3>
              <p className="text-sm text-gray-600">
                Round {battle.current_round} of {battle.max_rounds}
              </p>
            </div>
          </div>
          <div className="text-right">
            <div className="flex items-center space-x-2 text-orange-600">
              <Clock className="h-5 w-5" />
              <span className="text-lg font-bold">
                {formatTime(timeRemaining)}
              </span>
            </div>
            <p className="text-xs text-gray-600">Time remaining</p>
          </div>
        </div>
      </div>

      {/* Price Comparison */}
      <div className="grid gap-4 md:grid-cols-3">
        <div className="rounded-lg border border-gray-200 bg-white p-4">
          <p className="text-sm text-gray-600">Original Price</p>
          <p className="text-2xl font-bold text-gray-900">
            {formatCurrency(battle.original_price)}
          </p>
        </div>
        <div className="rounded-lg border-2 border-blue-500 bg-blue-50 p-4">
          <p className="text-sm text-blue-600">Current Offer</p>
          <p className="text-2xl font-bold text-blue-900">
            {formatCurrency(battle.current_offer)}
          </p>
        </div>
        <div className="rounded-lg border border-green-200 bg-green-50 p-4">
          <p className="text-sm text-green-600">Potential Savings</p>
          <p className="text-2xl font-bold text-green-900">
            {formatCurrency(savings)}
          </p>
          <p className="text-xs text-green-600">
            {savingsPercentage.toFixed(1)}% off
          </p>
        </div>
      </div>

      {/* Offers History */}
      <div className="rounded-lg border border-gray-200 bg-white p-6">
        <h4 className="mb-4 font-semibold text-gray-900">
          Negotiation History
        </h4>
        <div className="space-y-3">
          {offers.map((offer, index) => (
            <div
              key={offer.id}
              className={`flex items-start space-x-3 rounded-lg p-3 ${
                offer.offered_by === userRole ? "bg-blue-50" : "bg-gray-50"
              }`}
            >
              <div
                className={`rounded-full p-2 ${
                  offer.offered_by === "buyer" ? "bg-blue-100" : "bg-purple-100"
                }`}
              >
                {offer.offered_by === "buyer" ? (
                  <TrendingUp className="h-4 w-4 text-blue-600" />
                ) : (
                  <TrendingDown className="h-4 w-4 text-purple-600" />
                )}
              </div>
              <div className="flex-1">
                <div className="flex items-center justify-between">
                  <span className="font-medium text-gray-900">
                    {offer.offered_by === userRole ? "You" : "Opponent"} offered
                  </span>
                  <span className="text-sm text-gray-600">
                    Round {offer.round_number}
                  </span>
                </div>
                <p className="text-lg font-bold text-gray-900">
                  {formatCurrency(offer.offer_amount)}
                </p>
                {offer.message && (
                  <p className="mt-1 text-sm text-gray-600">{offer.message}</p>
                )}
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Action Area */}
      {isUserTurn ? (
        <div className="rounded-lg border-2 border-green-500 bg-green-50 p-6">
          <div className="mb-4 flex items-center space-x-2">
            <Zap className="h-5 w-5 text-green-600" />
            <h4 className="font-semibold text-green-900">Your Turn!</h4>
          </div>

          <div className="space-y-4">
            <div>
              <label
                htmlFor="counter-offer"
                className="mb-1 block text-sm font-medium text-gray-700"
              >
                Counter Offer Amount (Γéª)
              </label>
              <input
                id="counter-offer"
                type="number"
                value={counterOffer}
                onChange={(e) => setCounterOffer(e.target.value)}
                placeholder={
                  userRole === "buyer"
                    ? "Enter higher offer"
                    : "Enter lower counter"
                }
                min="0"
                step="100"
                className="w-full rounded-lg border border-gray-300 px-4 py-2 focus:border-blue-500 focus:outline-none focus:ring-1 focus:ring-blue-500"
              />
              <p className="mt-1 text-xs text-gray-600">
                {userRole === "buyer"
                  ? `Must be higher than ${formatCurrency(battle.current_offer)}`
                  : `Must be lower than ${formatCurrency(battle.current_offer)}`}
              </p>
            </div>

            <div>
              <label
                htmlFor="offer-message"
                className="mb-1 block text-sm font-medium text-gray-700"
              >
                Message (Optional)
              </label>
              <textarea
                id="offer-message"
                value={message}
                onChange={(e) => setMessage(e.target.value)}
                placeholder="Add a message to your offer..."
                rows={2}
                className="w-full rounded-lg border border-gray-300 px-4 py-2 focus:border-blue-500 focus:outline-none focus:ring-1 focus:ring-blue-500"
              />
            </div>

            <div className="flex space-x-3">
              <button
                type="button"
                onClick={handleMakeOffer}
                disabled={loading || !counterOffer}
                className="flex-1 rounded-lg bg-blue-600 px-4 py-3 font-medium text-white transition-colors hover:bg-blue-700 disabled:bg-gray-400"
              >
                {loading ? "Sending..." : "Make Counter Offer"}
              </button>
              <button
                type="button"
                onClick={handleAcceptOffer}
                disabled={loading}
                className="flex-1 rounded-lg bg-green-600 px-4 py-3 font-medium text-white transition-colors hover:bg-green-700 disabled:bg-gray-400"
              >
                Accept Current Offer
              </button>
            </div>

            <button
              type="button"
              onClick={handleRejectBattle}
              disabled={loading}
              className="w-full rounded-lg border border-red-300 bg-white px-4 py-2 text-sm text-red-600 transition-colors hover:bg-red-50 disabled:opacity-50"
            >
              End Negotiation
            </button>
          </div>
        </div>
      ) : (
        <div className="rounded-lg border border-gray-200 bg-gray-50 p-6 text-center">
          <Clock className="mx-auto h-8 w-8 text-gray-400" />
          <p className="mt-2 font-medium text-gray-900">
            Waiting for opponent's response...
          </p>
          <p className="mt-1 text-sm text-gray-600">
            They have {formatTime(timeRemaining)} to respond
          </p>
        </div>
      )}
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import {
  TrendingUp,
  TrendingDown,
  AlertCircle,
  Check,
  Clock,
  BarChart3,
} from "lucide-react";
import { PriceAnalysis } from "@/lib/services/pricing-suggestion";

interface SmartPricingSuggesterProps {
  listingId?: string;
  factors: {
    condition?: string;
    age_months?: number;
    brand?: string;
    location?: string;
    category?: string;
    subcategory?: string;
  };
  onPriceSelect: (price: number) => void;
  currentPrice?: number;
}

export function SmartPricingSuggester({
  listingId,
  factors,
  onPriceSelect,
  currentPrice,
}: SmartPricingSuggesterProps) {
  const [analysis, setAnalysis] = useState<PriceAnalysis | null>(null);
  const [loading, setLoading] = useState(false);
  const [selectedPrice, setSelectedPrice] = useState<number | null>(null);
  const [showHistory, setShowHistory] = useState(false);

  useEffect(() => {
    if (factors.category) {
      fetchPricingSuggestion();
    }
  }, [factors.category, factors.condition, factors.location]);

  const fetchPricingSuggestion = async () => {
    setLoading(true);
    try {
      const response = await fetch("/api/pricing-suggestions", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          listingId,
          factors,
        }),
      });

      if (response.ok) {
        const data = await response.json();
        setAnalysis(data.analysis);
        setSelectedPrice(data.analysis.suggested_price);
      }
    } catch (error) {
      console.error("Failed to fetch pricing suggestion:", error);
    } finally {
      setLoading(false);
    }
  };

  const handleAcceptSuggestion = () => {
    if (analysis) {
      onPriceSelect(analysis.suggested_price);
      setSelectedPrice(analysis.suggested_price);
    }
  };

  const handlePriceChange = (price: number) => {
    setSelectedPrice(price);
    onPriceSelect(price);
  };

  if (loading) {
    return (
      <div className="rounded-lg border border-gray-200 bg-white p-6">
        <div className="flex items-center space-x-3">
          <div className="h-5 w-5 animate-spin rounded-full border-2 border-blue-600 border-t-transparent" />
          <p className="text-sm text-gray-600">Analyzing market prices...</p>
        </div>
      </div>
    );
  }

  if (!analysis) {
    return null;
  }

  const confidenceColor =
    analysis.confidence_score >= 70
      ? "text-green-600"
      : analysis.confidence_score >= 40
        ? "text-yellow-600"
        : "text-red-600";

  const confidenceBg =
    analysis.confidence_score >= 70
      ? "bg-green-50"
      : analysis.confidence_score >= 40
        ? "bg-yellow-50"
        : "bg-red-50";

  return (
    <div className="space-y-4">
      {/* Main Suggestion Card */}
      <div className="rounded-lg border border-gray-200 bg-gradient-to-br from-blue-50 to-white p-6">
        <div className="mb-4 flex items-start justify-between">
          <div>
            <h3 className="text-lg font-semibold text-gray-900">
              Smart Pricing Suggestion
            </h3>
            <p className="text-sm text-gray-600">
              Based on {analysis.similar_items_count} similar items
            </p>
          </div>
          <div className={`rounded-lg px-3 py-1 ${confidenceBg}`}>
            <p className={`text-sm font-medium ${confidenceColor}`}>
              {analysis.confidence_score}% confident
            </p>
          </div>
        </div>

        {/* Suggested Price */}
        <div className="mb-6">
          <div className="flex items-baseline space-x-2">
            <span className="text-4xl font-bold text-gray-900">
              Γéª{analysis.suggested_price.toLocaleString()}
            </span>
            {analysis.seasonal_adjustment !== 0 && (
              <span className="text-sm text-gray-600">
                ({analysis.seasonal_adjustment > 0 ? "+" : ""}
                {analysis.seasonal_adjustment}% seasonal)
              </span>
            )}
          </div>
          <div className="mt-2 flex items-center space-x-4 text-sm text-gray-600">
            <span>
              Range: Γéª{analysis.min_price.toLocaleString()} - Γéª
              {analysis.max_price.toLocaleString()}
            </span>
            {analysis.market_average > 0 && (
              <span>
                Market avg: Γéª{analysis.market_average.toLocaleString()}
              </span>
            )}
          </div>
        </div>

        {/* Price Range Slider */}
        <div className="mb-6">
          <label className="mb-2 block text-sm font-medium text-gray-700">
            Adjust Price
          </label>
          <input
            type="range"
            min={analysis.min_price}
            max={analysis.max_price}
            value={selectedPrice || analysis.suggested_price}
            onChange={(e) => handlePriceChange(Number(e.target.value))}
            className="h-2 w-full cursor-pointer appearance-none rounded-lg bg-gradient-to-r from-green-200 via-blue-200 to-red-200"
            style={{
              background: `linear-gradient(to right, #86efac 0%, #93c5fd 50%, #fca5a5 100%)`,
            }}
          />
          <div className="mt-2 flex justify-between text-xs text-gray-500">
            <span>Γéª{analysis.min_price.toLocaleString()}</span>
            <span className="font-medium text-gray-900">
              Γéª{(selectedPrice || analysis.suggested_price).toLocaleString()}
            </span>
            <span>Γéª{analysis.max_price.toLocaleString()}</span>
          </div>
        </div>

        {/* Accept Button */}
        <button
          onClick={handleAcceptSuggestion}
          className="flex w-full items-center justify-center space-x-2 rounded-lg bg-blue-600 px-4 py-3 text-white transition-colors hover:bg-blue-700"
        >
          <Check className="h-5 w-5" />
          <span>Accept Suggested Price</span>
        </button>
      </div>

      {/* Deviation Alert */}
      {analysis.deviation_alert && (
        <div
          className={`flex items-start space-x-3 rounded-lg border p-4 ${
            analysis.deviation_alert.type === "above"
              ? "border-orange-200 bg-orange-50"
              : "border-blue-200 bg-blue-50"
          }`}
        >
          <AlertCircle
            className={`h-5 w-5 flex-shrink-0 ${
              analysis.deviation_alert.type === "above"
                ? "text-orange-600"
                : "text-blue-600"
            }`}
          />
          <div>
            <p
              className={`text-sm font-medium ${
                analysis.deviation_alert.type === "above"
                  ? "text-orange-900"
                  : "text-blue-900"
              }`}
            >
              Price Deviation Alert
            </p>
            <p
              className={`mt-1 text-sm ${
                analysis.deviation_alert.type === "above"
                  ? "text-orange-700"
                  : "text-blue-700"
              }`}
            >
              {analysis.deviation_alert.message}
            </p>
          </div>
        </div>
      )}

      {/* Selling Time Estimates */}
      {analysis.avg_selling_time_days > 0 && (
        <div className="rounded-lg border border-gray-200 bg-white p-4">
          <div className="mb-3 flex items-center space-x-2">
            <Clock className="h-5 w-5 text-gray-600" />
            <h4 className="font-medium text-gray-900">Average Selling Time</h4>
          </div>
          <p className="text-2xl font-bold text-gray-900">
            {analysis.avg_selling_time_days} days
          </p>
          <p className="mt-1 text-sm text-gray-600">
            Based on similar items at this price range
          </p>

          {analysis.price_at_different_points.length > 0 && (
            <div className="mt-4 space-y-2">
              <p className="text-sm font-medium text-gray-700">
                Selling time at different prices:
              </p>
              {analysis.price_at_different_points.map((point, index) => (
                <div
                  key={index}
                  className="flex items-center justify-between text-sm"
                >
                  <span className="text-gray-600">
                    Γéª{point.price.toLocaleString()}
                  </span>
                  <span className="font-medium text-gray-900">
                    ~{point.avg_days_to_sell} days
                  </span>
                </div>
              ))}
            </div>
          )}
        </div>
      )}

      {/* Price History */}
      {analysis.price_history.length > 0 && (
        <div className="rounded-lg border border-gray-200 bg-white p-4">
          <button
            onClick={() => setShowHistory(!showHistory)}
            className="flex w-full items-center justify-between"
          >
            <div className="flex items-center space-x-2">
              <BarChart3 className="h-5 w-5 text-gray-600" />
              <h4 className="font-medium text-gray-900">
                Price History (6 months)
              </h4>
            </div>
            <span className="text-sm text-gray-600">
              {showHistory ? "Hide" : "Show"}
            </span>
          </button>

          {showHistory && (
            <div className="mt-4 space-y-3">
              {analysis.price_history.map((entry, index) => {
                const date = new Date(entry.date);
                const monthName = date.toLocaleDateString("en-US", {
                  month: "short",
                  year: "numeric",
                });

                const trend =
                  index > 0
                    ? entry.avg_price -
                      analysis.price_history[index - 1].avg_price
                    : 0;

                return (
                  <div
                    key={index}
                    className="flex items-center justify-between border-b border-gray-100 pb-2 last:border-0"
                  >
                    <span className="text-sm text-gray-600">{monthName}</span>
                    <div className="flex items-center space-x-3">
                      <span className="text-sm font-medium text-gray-900">
                        Γéª{entry.avg_price.toLocaleString()}
                      </span>
                      {trend !== 0 && (
                        <span
                          className={`flex items-center text-xs ${
                            trend > 0 ? "text-green-600" : "text-red-600"
                          }`}
                        >
                          {trend > 0 ? (
                            <TrendingUp className="h-3 w-3" />
                          ) : (
                            <TrendingDown className="h-3 w-3" />
                          )}
                          {Math.abs(trend).toLocaleString()}
                        </span>
                      )}
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </div>
      )}

      {/* Market Insights */}
      <div className="rounded-lg border border-gray-200 bg-white p-4">
        <h4 className="mb-3 font-medium text-gray-900">Market Insights</h4>
        <div className="space-y-2 text-sm text-gray-600">
          <p>
            ΓÇó {analysis.similar_items_count} similar items sold in the last 6
            months
          </p>
          {analysis.market_average > 0 && (
            <p>
              ΓÇó Average market price: Γéª
              {analysis.market_average.toLocaleString()}
            </p>
          )}
          {analysis.seasonal_adjustment !== 0 && (
            <p>
              ΓÇó Seasonal adjustment:{" "}
              {analysis.seasonal_adjustment > 0 ? "+" : ""}
              {analysis.seasonal_adjustment}% (
              {analysis.seasonal_adjustment > 0 ? "high" : "low"} demand period)
            </p>
          )}
          <p>
            ΓÇó Confidence level: {analysis.confidence_score}%
            {analysis.confidence_score >= 70
              ? " (High - Strong market data)"
              : analysis.confidence_score >= 40
                ? " (Medium - Moderate market data)"
                : " (Low - Limited market data)"}
          </p>
        </div>
      </div>
    </div>
  );
}

"use client";

/**
 * Offer Comparison Component
 *
 * Displays offers side-by-side for comparison with accept/reject actions.
 */

import { useState } from "react";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import {
  Package,
  DollarSign,
  User,
  MapPin,
  CheckCircle,
  XCircle,
  Star,
  Shield,
  Phone,
  Award,
} from "lucide-react";
import { formatDistanceToNow } from "date-fns";

interface Offer {
  id: string;
  price: number;
  message: string | null;
  status: "pending" | "accepted" | "rejected";
  created_at: string;
  users: {
    username: string;
    avatar_url: string | null;
    trust_score: number;
    phone_verified: boolean;
    nin_verified: boolean;
  };
  listings: {
    id: string;
    title: string;
    thumbnail_url: string | null;
    condition: string;
    state: string;
    lga: string;
  } | null;
}

interface OfferComparisonProps {
  offers: Offer[];
  requestId: string;
  isRequester: boolean;
  onOfferUpdate?: () => void;
}

export function OfferComparison({
  offers,
  requestId,
  isRequester,
  onOfferUpdate,
}: OfferComparisonProps) {
  const [processingOfferId, setProcessingOfferId] = useState<string | null>(
    null,
  );
  const [error, setError] = useState<string>("");

  // Find the best offer (lowest price among pending offers)
  const pendingOffers = offers.filter((o) => o.status === "pending");
  const bestOffer =
    pendingOffers.length > 0
      ? pendingOffers.reduce((min, offer) =>
          offer.price < min.price ? offer : min,
        )
      : null;

  const handleOfferAction = async (
    offerId: string,
    action: "accept" | "reject",
  ) => {
    setError("");
    setProcessingOfferId(offerId);

    try {
      const response = await fetch(
        `/api/product-requests/${requestId}/offers/${offerId}`,
        {
          method: "PUT",
          headers: {
            "Content-Type": "application/json",
          },
          body: JSON.stringify({ action }),
        },
      );

      if (!response.ok) {
        const data = await response.json();
        throw new Error(data.error || `Failed to ${action} offer`);
      }

      onOfferUpdate?.();
    } catch (err) {
      console.error(`Error ${action}ing offer:`, err);
      setError(
        err instanceof Error ? err.message : `Failed to ${action} offer`,
      );
    } finally {
      setProcessingOfferId(null);
    }
  };

  const getStatusBadge = (status: string) => {
    switch (status) {
      case "accepted":
        return (
          <Badge className="bg-green-500 hover:bg-green-600">
            <CheckCircle className="h-3 w-3 mr-1" />
            Accepted
          </Badge>
        );
      case "rejected":
        return (
          <Badge variant="secondary">
            <XCircle className="h-3 w-3 mr-1" />
            Rejected
          </Badge>
        );
      default:
        return <Badge variant="outline">Pending</Badge>;
    }
  };

  if (offers.length === 0) {
    return (
      <Card className="p-12 text-center">
        <Package className="mx-auto h-12 w-12 text-muted-foreground mb-4" />
        <h3 className="text-lg font-semibold mb-2">No offers yet</h3>
        <p className="text-muted-foreground">
          Sellers will be able to submit offers for this request
        </p>
      </Card>
    );
  }

  return (
    <div className="space-y-4">
      {error && (
        <div className="bg-red-50 dark:bg-red-950/20 border border-red-200 dark:border-red-800 rounded-lg p-3 text-sm text-red-600 dark:text-red-400">
          {error}
        </div>
      )}

      {/* Offers grid */}
      <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
        {offers.map((offer) => {
          const isBestOffer = bestOffer?.id === offer.id;

          return (
            <Card
              key={offer.id}
              className={`p-6 space-y-4 ${
                isBestOffer ? "ring-2 ring-green-500 dark:ring-green-600" : ""
              }`}
            >
              {/* Best offer badge */}
              {isBestOffer && (
                <div className="flex items-center gap-2 text-green-600 dark:text-green-400 text-sm font-medium">
                  <Award className="h-4 w-4" />
                  Best Offer
                </div>
              )}

              {/* Status */}
              <div className="flex items-center justify-between">
                {getStatusBadge(offer.status)}
                <span className="text-xs text-muted-foreground">
                  {formatDistanceToNow(new Date(offer.created_at), {
                    addSuffix: true,
                  })}
                </span>
              </div>

              {/* Seller info */}
              <div className="flex items-center gap-3">
                {offer.users.avatar_url ? (
                  <img
                    src={offer.users.avatar_url}
                    alt={offer.users.username}
                    className="w-12 h-12 rounded-full object-cover"
                  />
                ) : (
                  <div className="w-12 h-12 rounded-full bg-muted flex items-center justify-center">
                    <User className="h-6 w-6 text-muted-foreground" />
                  </div>
                )}
                <div className="flex-1 min-w-0">
                  <p className="font-medium truncate">{offer.users.username}</p>
                  <div className="flex items-center gap-2 text-xs text-muted-foreground">
                    <div className="flex items-center gap-1">
                      <Star className="h-3 w-3 fill-yellow-400 text-yellow-400" />
                      <span>{offer.users.trust_score}</span>
                    </div>
                    {offer.users.phone_verified && (
                      <Phone className="h-3 w-3 text-green-600" />
                    )}
                    {offer.users.nin_verified && (
                      <Shield className="h-3 w-3 text-blue-600" />
                    )}
                  </div>
                </div>
              </div>

              {/* Price */}
              <div className="bg-muted/50 rounded-lg p-4">
                <div className="flex items-center gap-2 text-muted-foreground text-sm mb-1">
                  <DollarSign className="h-4 w-4" />
                  <span>Offer Price</span>
                </div>
                <p className="text-2xl font-bold">
                  Γéª{offer.price.toLocaleString()}
                </p>
              </div>

              {/* Listing details */}
              {offer.listings && (
                <div className="space-y-2">
                  <div className="flex items-center gap-3">
                    {offer.listings.thumbnail_url ? (
                      <img
                        src={offer.listings.thumbnail_url}
                        alt={offer.listings.title}
                        className="w-16 h-16 object-cover rounded"
                      />
                    ) : (
                      <div className="w-16 h-16 bg-muted rounded flex items-center justify-center">
                        <Package className="h-6 w-6 text-muted-foreground" />
                      </div>
                    )}
                    <div className="flex-1 min-w-0">
                      <p className="font-medium text-sm truncate">
                        {offer.listings.title}
                      </p>
                      <p className="text-xs text-muted-foreground">
                        {offer.listings.condition}
                      </p>
                    </div>
                  </div>
                  <div className="flex items-center gap-1.5 text-xs text-muted-foreground">
                    <MapPin className="h-3 w-3" />
                    <span>
                      {offer.listings.lga}, {offer.listings.state}
                    </span>
                  </div>
                </div>
              )}

              {/* Message */}
              {offer.message && (
                <div className="space-y-1">
                  <p className="text-xs font-medium text-muted-foreground">
                    Message:
                  </p>
                  <p className="text-sm bg-muted/50 rounded p-3">
                    {offer.message}
                  </p>
                </div>
              )}

              {/* Actions (only for requester and pending offers) */}
              {isRequester && offer.status === "pending" && (
                <div className="flex gap-2 pt-2 border-t">
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={() => handleOfferAction(offer.id, "reject")}
                    disabled={processingOfferId === offer.id}
                    className="flex-1"
                  >
                    <XCircle className="h-4 w-4 mr-1" />
                    Reject
                  </Button>
                  <Button
                    size="sm"
                    onClick={() => handleOfferAction(offer.id, "accept")}
                    disabled={processingOfferId === offer.id}
                    className="flex-1"
                  >
                    <CheckCircle className="h-4 w-4 mr-1" />
                    Accept
                  </Button>
                </div>
              )}
            </Card>
          );
        })}
      </div>
    </div>
  );
}

"use client";

/**
 * Offer Submission Form Component
 *
 * Allows sellers to submit offers for product requests with existing listings or custom offers.
 * Requirements: 19.3
 */

import { useState, useEffect } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Card } from "@/components/ui/card";
import { createClient } from "@/lib/supabase/client";
import { CheckCircle, AlertCircle, Package } from "lucide-react";

interface OfferSubmissionFormProps {
  requestId: string;
  requestTitle: string;
  onSuccess?: () => void;
  onCancel?: () => void;
}

interface UserListing {
  id: string;
  title: string;
  price: number | null;
  thumbnail_url: string | null;
}

export function OfferSubmissionForm({
  requestId,
  requestTitle,
  onSuccess,
  onCancel,
}: OfferSubmissionFormProps) {
  const [userListings, setUserListings] = useState<UserListing[]>([]);
  const [selectedListingId, setSelectedListingId] = useState<string>("");
  const [selectedListing, setSelectedListing] = useState<UserListing | null>(
    null,
  );
  const [customPrice, setCustomPrice] = useState<string>("");
  const [message, setMessage] = useState<string>("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string>("");
  const [success, setSuccess] = useState(false);
  const [loadingListings, setLoadingListings] = useState(true);

  const supabase = createClient();

  // Fetch user's active listings
  useEffect(() => {
    async function fetchUserListings() {
      try {
        const {
          data: { user },
        } = await supabase.auth.getUser();
        if (!user) return;

        const { data, error } = await supabase
          .from("listings")
          .select("id, title, price, thumbnail_url")
          .eq("user_id", user.id)
          .eq("status", "active")
          .order("created_at", { ascending: false });

        if (error) throw error;

        setUserListings(data || []);
      } catch (err) {
        console.error("Error fetching user listings:", err);
        setError("Failed to load your listings");
      } finally {
        setLoadingListings(false);
      }
    }

    fetchUserListings();
  }, [supabase]);

  // Update selected listing when selection changes
  useEffect(() => {
    const listing = userListings.find((l) => l.id === selectedListingId);
    setSelectedListing(listing || null);
    if (listing && listing.price !== null) {
      setCustomPrice(listing.price.toString());
    }
  }, [selectedListingId, userListings]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError("");
    setSuccess(false);

    const price = parseFloat(customPrice);

    if (isNaN(price) || price < 0) {
      setError("Please enter a valid price");
      return;
    }

    setLoading(true);

    try {
      const {
        data: { user },
      } = await supabase.auth.getUser();
      if (!user) {
        setError("You must be logged in to submit an offer");
        return;
      }

      const response = await fetch(
        `/api/product-requests/${requestId}/offers`,
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
          },
          body: JSON.stringify({
            listing_id: selectedListingId || undefined,
            price,
            message: message.trim() || undefined,
          }),
        },
      );

      if (!response.ok) {
        const data = await response.json();
        throw new Error(data.error || "Failed to submit offer");
      }

      setSuccess(true);
      setTimeout(() => {
        onSuccess?.();
      }, 1500);
    } catch (err) {
      console.error("Error submitting offer:", err);
      setError(
        err instanceof Error ? err.message : "An unexpected error occurred",
      );
    } finally {
      setLoading(false);
    }
  };

  if (loadingListings) {
    return (
      <Card className="p-6">
        <div className="text-center text-muted-foreground">
          Loading your listings...
        </div>
      </Card>
    );
  }

  if (success) {
    return (
      <Card className="p-6">
        <div className="text-center">
          <CheckCircle className="mx-auto h-12 w-12 text-green-500 mb-4" />
          <h3 className="text-lg font-semibold mb-2">Offer Submitted!</h3>
          <p className="text-muted-foreground">
            Your offer has been sent to the buyer. They will be notified and can
            review your offer.
          </p>
        </div>
      </Card>
    );
  }

  return (
    <Card className="p-6">
      <form onSubmit={handleSubmit} className="space-y-6">
        <div>
          <h3 className="text-lg font-semibold mb-2">Submit Your Offer</h3>
          <p className="text-sm text-muted-foreground">
            Offer a product for: <strong>{requestTitle}</strong>
          </p>
        </div>

        {/* Select existing listing (optional) */}
        {userListings.length > 0 && (
          <div className="space-y-2">
            <Label htmlFor="listing">
              Select from Your Listings (Optional)
            </Label>
            <select
              id="listing"
              value={selectedListingId}
              onChange={(e) => setSelectedListingId(e.target.value)}
              className="w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
              aria-label="Select your listing to offer"
            >
              <option value="">Custom offer (no listing)</option>
              {userListings.map((listing) => (
                <option key={listing.id} value={listing.id}>
