"use client";

import { useEffect, useState } from "react";
import { X, Download, Smartphone } from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";
import { Button } from "@/components/ui/button";

interface BeforeInstallPromptEvent extends Event {
  prompt: () => Promise<void>;
  userChoice: Promise<{ outcome: "accepted" | "dismissed" }>;
}

/**
 * InstallPrompt Component
 * Displays a prompt for users to install the PWA on their home screen
 * 
 * Requirements: 17.6
 */
export function InstallPrompt() {
  const [deferredPrompt, setDeferredPrompt] =
    useState<BeforeInstallPromptEvent | null>(null);
  const [showPrompt, setShowPrompt] = useState(false);
  const [isIOS, setIsIOS] = useState(false);
  const [isStandalone, setIsStandalone] = useState(false);

  useEffect(() => {
    // Check if app is already installed (standalone mode)
    const checkStandalone = () => {
      return (
        window.matchMedia("(display-mode: standalone)").matches ||
        (window.navigator as any).standalone === true
      );
    };

    setIsStandalone(checkStandalone());

    // Check if iOS
    const checkIOS = () => {
      return (
        /iPad|iPhone|iPod/.test(navigator.userAgent) &&
        !(window as any).MSStream
      );
    };

    setIsIOS(checkIOS());

    // Check if user has dismissed the prompt before
    const dismissed = localStorage.getItem("pwa-install-prompt-dismissed");
    if (dismissed) {
      const dismissedDate = new Date(dismissed).getTime();
      const sevenDaysAgo = Date.now() - 7 * 24 * 60 * 60 * 1000;

      // Only show again after 7 days
      if (dismissedDate > sevenDaysAgo) {
        return;
      }
    }

    // Listen for beforeinstallprompt event
    const handleBeforeInstallPrompt = (e: Event) => {
      e.preventDefault();
      setDeferredPrompt(e as BeforeInstallPromptEvent);

      // Show prompt after 30 seconds of browsing
      setTimeout(() => {
        if (!checkStandalone()) {
          setShowPrompt(true);
        }
      }, 30000);
    };

    window.addEventListener("beforeinstallprompt", handleBeforeInstallPrompt);

    // Show iOS prompt if applicable
    if (checkIOS() && !checkStandalone()) {
      setTimeout(() => {
        setShowPrompt(true);
      }, 30000);
    }

    return () => {
      window.removeEventListener(
        "beforeinstallprompt",
        handleBeforeInstallPrompt
      );
    };
  }, []);

  const handleInstallClick = async () => {
    if (!deferredPrompt) {
      return;
    }

    // Show the install prompt
    await deferredPrompt.prompt();

    // Wait for the user to respond
    const choiceResult = await deferredPrompt.userChoice;

    if (choiceResult.outcome === "accepted") {
      console.log("User accepted the install prompt");
    } else {
      console.log("User dismissed the install prompt");
    }

    // Clear the deferred prompt
    setDeferredPrompt(null);
    setShowPrompt(false);

    // Track dismissal
    localStorage.setItem(
      "pwa-install-prompt-dismissed",
      new Date().toISOString()
    );
  };

  const handleDismiss = () => {
    setShowPrompt(false);
    localStorage.setItem(
      "pwa-install-prompt-dismissed",
      new Date().toISOString()
    );
  };

  // Don't show if already installed or not applicable
  if (isStandalone || (!deferredPrompt && !isIOS)) {
    return null;
  }

  return (
    <AnimatePresence>
      {showPrompt && (
        <motion.div
          initial={{ y: 100, opacity: 0 }}
          animate={{ y: 0, opacity: 1 }}
          exit={{ y: 100, opacity: 0 }}
          transition={{ type: "spring", damping: 25, stiffness: 300 }}
          className="fixed bottom-4 left-4 right-4 md:left-auto md:right-4 md:max-w-sm z-50"
          role="dialog"
          aria-labelledby="install-prompt-title"
          aria-describedby="install-prompt-description"
        >
          <div className="bg-white dark:bg-gray-900 rounded-lg shadow-2xl border border-gray-200 dark:border-gray-800 p-4">
            <div className="flex items-start justify-between mb-3">
              <div className="flex items-center gap-3">
                <div className="w-12 h-12 bg-gradient-to-br from-green-500 to-emerald-600 rounded-lg flex items-center justify-center">
                  <Smartphone className="w-6 h-6 text-white" />
                </div>
                <div>
                  <h3
                    id="install-prompt-title"
                    className="font-semibold text-gray-900 dark:text-white"
                  >
                    Install FindAm
                  </h3>
                  <p
                    id="install-prompt-description"
                    className="text-sm text-gray-600 dark:text-gray-400"
                  >
                    {isIOS
                      ? "Add to your home screen"
                      : "Install for quick access"}
                  </p>
                </div>
              </div>
              <button
                onClick={handleDismiss}
                className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-300 transition-colors"
                aria-label="Dismiss install prompt"
              >
                <X className="w-5 h-5" />
              </button>
            </div>

            {isIOS ? (
              <div className="text-sm text-gray-600 dark:text-gray-400 space-y-2 mb-4">
                <p>To install this app:</p>
                <ol className="list-decimal list-inside space-y-1 ml-2">
                  <li>Tap the Share button in Safari</li>
                  <li>Scroll down and tap "Add to Home Screen"</li>
                  <li>Tap "Add" in the top right corner</li>
                </ol>
              </div>
            ) : (
              <div className="space-y-2 mb-4">
                <p className="text-sm text-gray-600 dark:text-gray-400">
                  Get faster access and use FindAm offline!
                </p>
                <ul className="text-xs text-gray-500 dark:text-gray-500 space-y-1">
                  <li>Γ£ô Instant loading</li>
                  <li>Γ£ô Work offline</li>
                  <li>Γ£ô Push notifications</li>
                </ul>
              </div>
            )}

            {!isIOS && (
              <Button
                onClick={handleInstallClick}
                className="w-full bg-gradient-to-r from-green-500 to-emerald-600 hover:from-green-600 hover:to-emerald-700"
                size="sm"
              >
                <Download className="w-4 h-4 mr-2" />
                Install App
              </Button>
            )}
          </div>
        </motion.div>
      )}
    </AnimatePresence>
  );
}

/**
 * Hook to programmatically trigger install prompt
 */
export function useInstallPrompt() {
  const [deferredPrompt, setDeferredPrompt] =
    useState<BeforeInstallPromptEvent | null>(null);
  const [isInstallable, setIsInstallable] = useState(false);

  useEffect(() => {
    const handler = (e: Event) => {
      e.preventDefault();
      setDeferredPrompt(e as BeforeInstallPromptEvent);
      setIsInstallable(true);
    };

    window.addEventListener("beforeinstallprompt", handler);

    return () => {
      window.removeEventListener("beforeinstallprompt", handler);
    };
  }, []);

  const promptInstall = async () => {
    if (!deferredPrompt) {
      return false;
    }

    await deferredPrompt.prompt();
    const choiceResult = await deferredPrompt.userChoice;

    setDeferredPrompt(null);
    setIsInstallable(false);

    return choiceResult.outcome === "accepted";
  };

  return {
    isInstallable,
    promptInstall,
  };
}

"use client";

/**
 * Low Data Mode Toggle Component
 * Allows users to enable/disable low-data mode to reduce data usage
 * Requirements: 18.1
 */

import { useState, useEffect } from "react";
import { Switch } from "@/components/ui/switch";
import { Label } from "@/components/ui/label";
import { Wifi, WifiOff, Loader2 } from "lucide-react";
import { pwaService } from "@/lib/services/pwa";
import { useAuthStore } from "@/store/auth";
import { toast } from "sonner";

export function LowDataModeToggle() {
  const { user } = useAuthStore();
  const [enabled, setEnabled] = useState(false);
  const [loading, setLoading] = useState(true);
  const [toggling, setToggling] = useState(false);
  const [dataUsage, setDataUsage] = useState<number>(0);

  useEffect(() => {
    loadSettings();
  }, [user]);

  const loadSettings = async () => {
    if (!user) {
      setLoading(false);
      return;
    }

    try {
      const settings = await pwaService.getSettings(user.id);
      if (settings) {
        setEnabled(settings.low_data_mode);
        setDataUsage(settings.data_usage_mb);
      }
    } catch (error) {
      console.error("Failed to load PWA settings:", error);
    } finally {
      setLoading(false);
    }
  };

  const handleToggle = async (checked: boolean) => {
    if (!user) {
      toast.error("Please sign in to use this feature");
      return;
    }

    setToggling(true);

    try {
      await pwaService.toggleLowDataMode(user.id, checked);
      setEnabled(checked);
      toast.success(
        checked
          ? "Low-data mode enabled. Images will be compressed and videos won't auto-play."
          : "Low-data mode disabled. Full quality media will be loaded.",
      );
    } catch (error) {
      console.error("Failed to toggle low-data mode:", error);
      toast.error("Failed to update settings. Please try again.");
    } finally {
      setToggling(false);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-between p-4 border rounded-lg">
        <div className="flex items-center gap-3">
          <Loader2 className="h-5 w-5 animate-spin text-gray-400" />
          <span className="text-sm text-gray-500">Loading settings...</span>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between p-4 border rounded-lg">
        <div className="flex items-center gap-3">
          {enabled ? (
            <WifiOff className="h-5 w-5 text-orange-500" />
          ) : (
            <Wifi className="h-5 w-5 text-green-500" />
          )}
          <div className="flex-1">
            <Label
              htmlFor="low-data-mode"
              className="text-base font-medium cursor-pointer"
            >
              Low-Data Mode
            </Label>
            <p className="text-sm text-gray-500 mt-1">
              {enabled
                ? "Saving data by compressing images and disabling video auto-play"
                : "Full quality media is being loaded"}
            </p>
          </div>
        </div>
        <Switch
          id="low-data-mode"
          checked={enabled}
          onCheckedChange={handleToggle}
          disabled={toggling || !user}
          aria-label="Toggle low-data mode"
        />
      </div>

      {user && (
        <div className="p-4 bg-gray-50 rounded-lg">
          <div className="flex items-center justify-between">
            <span className="text-sm text-gray-600">Data usage this month</span>
            <span className="text-sm font-medium">
              {dataUsage.toFixed(2)} MB
            </span>
          </div>
          {enabled && (
            <p className="text-xs text-gray-500 mt-2">
              Low-data mode can reduce data usage by up to 70%
            </p>
          )}
        </div>
      )}

      {enabled && (
        <div className="p-4 bg-blue-50 border border-blue-200 rounded-lg">
          <h4 className="text-sm font-medium text-blue-900 mb-2">
            What's different in low-data mode?
          </h4>
          <ul className="text-sm text-blue-800 space-y-1">
            <li>ΓÇó Images compressed to 50% quality</li>
            <li>ΓÇó Lower resolution images loaded</li>
            <li>ΓÇó Videos don't auto-play</li>
            <li>ΓÇó Thumbnails shown instead of full videos</li>
          </ul>
        </div>
      )}
    </div>
  );
}

"use client";

/**
 * Optimized Video Component
 * Handles video playback with low-data mode support
 * Requirements: 18.3
 */

import { useState, useEffect, useRef } from "react";
import { Play } from "lucide-react";
import {
  getVideoThumbnailUrl,
  shouldAutoPlayVideo,
} from "@/lib/utils/image-compression";
import { pwaService } from "@/lib/services/pwa";

interface OptimizedVideoProps {
  src: string;
  poster?: string;
  width?: number;
  height?: number;
  className?: string;
  controls?: boolean;
  loop?: boolean;
  muted?: boolean;
  onPlay?: () => void;
  onPause?: () => void;
  onEnded?: () => void;
}

export function OptimizedVideo({
  src,
  poster,
  width,
  height,
  className = "",
  controls = true,
  loop = false,
  muted = true,
  onPlay,
  onPause,
  onEnded,
}: OptimizedVideoProps) {
  const [isLowDataMode, setIsLowDataMode] = useState(false);
  const [showVideo, setShowVideo] = useState(false);
  const [isPlaying, setIsPlaying] = useState(false);
  const videoRef = useRef<HTMLVideoElement>(null);

  useEffect(() => {
    const lowDataMode = pwaService.isLowDataModeEnabled();
    setIsLowDataMode(lowDataMode);

    // Auto-play only if not in low-data mode
    if (!lowDataMode && shouldAutoPlayVideo()) {
      setShowVideo(true);
    }
  }, []);

  const handlePlayClick = () => {
    setShowVideo(true);
    setIsPlaying(true);

    // Wait for video to load then play
    setTimeout(() => {
      if (videoRef.current) {
        videoRef.current.play();
      }
    }, 100);
  };

  const handleVideoPlay = () => {
    setIsPlaying(true);
    onPlay?.();
  };

  const handleVideoPause = () => {
    setIsPlaying(false);
    onPause?.();
  };

  const handleVideoEnded = () => {
    setIsPlaying(false);
    onEnded?.();
  };

  // Get thumbnail URL
  const thumbnailUrl = poster || getVideoThumbnailUrl(src, { width, height });

  // In low-data mode, show thumbnail with play button
  if (isLowDataMode && !showVideo) {
    return (
      <div className={`relative ${className}`} style={{ width, height }}>
        <img
          src={thumbnailUrl}
          alt="Video thumbnail"
          className="w-full h-full object-cover"
          width={width}
          height={height}
        />
        <button
          onClick={handlePlayClick}
          className="absolute inset-0 flex items-center justify-center bg-black/30 hover:bg-black/40 transition-colors"
          aria-label="Play video"
        >
          <div className="bg-white rounded-full p-4 shadow-lg">
            <Play className="h-8 w-8 text-gray-900" fill="currentColor" />
          </div>
        </button>
        <div className="absolute bottom-2 right-2 bg-black/70 text-white text-xs px-2 py-1 rounded">
          Low-data mode
        </div>
      </div>
    );
  }

  // Show video player
  return (
    <div className={`relative ${className}`} style={{ width, height }}>
      <video
        ref={videoRef}
        src={src}
        poster={thumbnailUrl}
        width={width}
        height={height}
        controls={controls}
        loop={loop}
        muted={muted}
        autoPlay={!isLowDataMode && shouldAutoPlayVideo()}
        playsInline
        className="w-full h-full object-cover"
        onPlay={handleVideoPlay}
        onPause={handleVideoPause}
        onEnded={handleVideoEnded}
      >
        Your browser does not support the video tag.
      </video>
      {isLowDataMode && (
        <div className="absolute top-2 right-2 bg-orange-500 text-white text-xs px-2 py-1 rounded">
          Low quality
        </div>
      )}
    </div>
  );
}

"use client";

/**
 * Sync Queue Component
 * Displays queued offline actions and sync status
 * Requirements: 18.9
 */

import { useState, useEffect } from "react";
import { RefreshCw, CheckCircle, XCircle, Clock, Loader2 } from "lucide-react";
import { pwaService, type OfflineAction } from "@/lib/services/pwa";
import { useAuthStore } from "@/store/auth";
import { toast } from "sonner";
import { Button } from "@/components/ui/button";

export function SyncQueue() {
  const { user } = useAuthStore();
  const [actions, setActions] = useState<OfflineAction[]>([]);
  const [loading, setLoading] = useState(true);
  const [syncing, setSyncing] = useState(false);
  const [isOnline, setIsOnline] = useState(true);

  useEffect(() => {
    loadActions();

    // Check online status
    setIsOnline(navigator.onLine);

    const handleOnline = () => {
      setIsOnline(true);
      // Auto-sync when coming back online
      handleSync();
    };

    const handleOffline = () => setIsOnline(false);

    window.addEventListener("online", handleOnline);
    window.addEventListener("offline", handleOffline);

    return () => {
      window.removeEventListener("online", handleOnline);
      window.removeEventListener("offline", handleOffline);
    };
  }, [user]);

  const loadActions = async () => {
    if (!user) {
      setLoading(false);
      return;
    }

    try {
      const pendingActions = await pwaService.getPendingActions(user.id);
      setActions(pendingActions);
    } catch (error) {
      console.error("Failed to load offline actions:", error);
    } finally {
      setLoading(false);
    }
  };

  const handleSync = async () => {
    if (!user || !isOnline) {
      toast.error("Cannot sync while offline");
      return;
    }

    setSyncing(true);

    try {
      const result = await pwaService.syncOfflineActions(user.id);

      if (result.success) {
        toast.success(
          `Successfully synced ${result.synced_count} action${
            result.synced_count !== 1 ? "s" : ""
          }`,
        );
      } else {
        toast.warning(
          `Synced ${result.synced_count} action${
            result.synced_count !== 1 ? "s" : ""
          }, ${result.failed_count} failed`,
        );
      }

      // Reload actions
      await loadActions();
    } catch (error) {
      console.error("Sync failed:", error);
      toast.error("Failed to sync actions. Please try again.");
    } finally {
      setSyncing(false);
    }
  };

  const getActionIcon = (status: string) => {
    switch (status) {
      case "pending":
        return <Clock className="h-4 w-4 text-gray-400" />;
      case "syncing":
        return <Loader2 className="h-4 w-4 text-blue-500 animate-spin" />;
      case "synced":
        return <CheckCircle className="h-4 w-4 text-green-500" />;
      case "failed":
        return <XCircle className="h-4 w-4 text-red-500" />;
      default:
        return <Clock className="h-4 w-4 text-gray-400" />;
    }
  };

  const getActionLabel = (actionType: string): string => {
    const labels: Record<string, string> = {
      create_listing: "Create listing",
      update_listing: "Update listing",
      delete_listing: "Delete listing",
      send_message: "Send message",
      like_listing: "Like listing",
      unlike_listing: "Unlike listing",
      save_listing: "Save listing",
      unsave_listing: "Unsave listing",
      create_review: "Create review",
      update_profile: "Update profile",
      create_offer: "Create offer",
      accept_offer: "Accept offer",
      reject_offer: "Reject offer",
    };

    return labels[actionType] || actionType;
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center p-8">
        <Loader2 className="h-6 w-6 animate-spin text-gray-400" />
      </div>
    );
  }

  if (actions.length === 0) {
    return (
      <div className="text-center p-8">
        <CheckCircle className="h-12 w-12 text-green-500 mx-auto mb-3" />
        <p className="text-gray-600">All actions synced</p>
        <p className="text-sm text-gray-400 mt-1">No pending offline actions</p>
      </div>
    );
  }

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <div>
          <h3 className="text-lg font-semibold">Sync Queue</h3>
          <p className="text-sm text-gray-500">
            {actions.length} pending action{actions.length !== 1 ? "s" : ""}
          </p>
        </div>
        <Button
          onClick={handleSync}
          disabled={syncing || !isOnline || !user}
          size="sm"
          className="gap-2"
        >
          <RefreshCw className={`h-4 w-4 ${syncing ? "animate-spin" : ""}`} />
          {syncing ? "Syncing..." : "Sync Now"}
        </Button>
      </div>

      {!isOnline && (
        <div className="bg-orange-50 border border-orange-200 rounded-lg p-3">
          <p className="text-sm text-orange-800">
            You're offline. Actions will sync automatically when you're back
            online.
          </p>
        </div>
      )}

      <div className="space-y-2">
        {actions.map((action) => (
          <div
            key={action.id}
            className="flex items-center gap-3 p-3 border rounded-lg hover:bg-gray-50 transition-colors"
          >
            {getActionIcon(action.sync_status)}
            <div className="flex-1 min-w-0">
              <p className="text-sm font-medium truncate">
                {getActionLabel(action.action_type)}
              </p>
              <p className="text-xs text-gray-500">
                {new Date(action.created_at).toLocaleString()}
              </p>
              {action.error_message && (
                <p className="text-xs text-red-600 mt-1">
                  {action.error_message}
                </p>
              )}
            </div>
            {action.priority > 0 && (
              <span className="text-xs bg-blue-100 text-blue-800 px-2 py-0.5 rounded">
                Priority
              </span>
            )}
            {action.sync_attempts > 0 && (
              <span className="text-xs text-gray-500">
                {action.sync_attempts} attempt
                {action.sync_attempts !== 1 ? "s" : ""}
              </span>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}

"use client";

/**
 * ReferralLeaderboard Component
 * Shows top referrers with monthly prizes
 * Requirements: 17.10
 */

import { useState, useEffect } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Badge } from "@/components/ui/badge";
import { Trophy, Medal, Award } from "lucide-react";
import { toast } from "sonner";

interface LeaderboardEntry {
  userId: string;
  username: string;
  avatar: string | null;
  referralCount: number;
  rank: number;
}

interface ReferralLeaderboardProps {
  limit?: number;
  month?: string; // Format: YYYY-MM
}

export function ReferralLeaderboard({
  limit = 100,
  month,
}: ReferralLeaderboardProps) {
  const [leaderboard, setLeaderboard] = useState<LeaderboardEntry[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    loadLeaderboard();
  }, [limit, month]);

  const loadLeaderboard = async () => {
    try {
      setLoading(true);
      const params = new URLSearchParams();
      params.append("limit", limit.toString());
      if (month) {
        params.append("month", month);
      }

      const response = await fetch(`/api/referrals/leaderboard?${params}`);
      if (response.ok) {
        const data = await response.json();
        setLeaderboard(data);
      } else {
        toast.error("Failed to load leaderboard");
      }
    } catch (error) {
      console.error("Failed to load leaderboard:", error);
      toast.error("Failed to load leaderboard");
    } finally {
      setLoading(false);
    }
  };

  const getRankIcon = (rank: number) => {
    switch (rank) {
      case 1:
        return <Trophy className="h-6 w-6 text-yellow-500" />;
      case 2:
        return <Medal className="h-6 w-6 text-gray-400" />;
      case 3:
        return <Award className="h-6 w-6 text-orange-600" />;
      default:
        return null;
    }
  };

  const getRankBadge = (rank: number) => {
    switch (rank) {
      case 1:
        return (
          <Badge className="bg-yellow-500 hover:bg-yellow-600">1st Place</Badge>
        );
      case 2:
        return (
          <Badge className="bg-gray-400 hover:bg-gray-500">2nd Place</Badge>
        );
      case 3:
        return (
          <Badge className="bg-orange-600 hover:bg-orange-700">3rd Place</Badge>
        );
      default:
        return <Badge variant="outline">#{rank}</Badge>;
    }
  };

  const getPrizeInfo = (rank: number) => {
    switch (rank) {
      case 1:
        return "Γéª50,000 Prize";
      case 2:
        return "Γéª30,000 Prize";
      case 3:
        return "Γéª20,000 Prize";
      default:
        if (rank <= 10) {
          return "Γéª5,000 Prize";
        }
        return null;
    }
  };

  if (loading) {
    return (
      <Card>
        <CardHeader>
          <CardTitle>Referral Leaderboard</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="animate-pulse space-y-4">
            {[1, 2, 3, 4, 5].map((i) => (
              <div key={i} className="flex items-center gap-4">
                <div className="w-10 h-10 bg-gray-200 rounded-full"></div>
                <div className="flex-1 space-y-2">
                  <div className="h-4 bg-gray-200 rounded w-1/3"></div>
                  <div className="h-3 bg-gray-200 rounded w-1/4"></div>
                </div>
              </div>
            ))}
          </div>
        </CardContent>
      </Card>
    );
  }

  return (
    <Card>
      <CardHeader>
        <CardTitle className="flex items-center gap-2">
          <Trophy className="h-5 w-5 text-yellow-500" />
          Referral Leaderboard
        </CardTitle>
        <p className="text-sm text-muted-foreground">
          Top referrers this month win amazing prizes!
        </p>
      </CardHeader>
      <CardContent>
        {/* Prize Info */}
        <div className="mb-6 p-4 bg-gradient-to-r from-yellow-50 to-orange-50 rounded-lg border border-yellow-200">
          <h3 className="font-semibold mb-2">Monthly Prizes</h3>
          <ul className="text-sm space-y-1">
            <li className="flex items-center gap-2">
              <Trophy className="h-4 w-4 text-yellow-500" />
              <span>1st Place: Γéª50,000</span>
            </li>
            <li className="flex items-center gap-2">
              <Medal className="h-4 w-4 text-gray-400" />
              <span>2nd Place: Γéª30,000</span>
            </li>
            <li className="flex items-center gap-2">
              <Award className="h-4 w-4 text-orange-600" />
              <span>3rd Place: Γéª20,000</span>
            </li>
            <li className="flex items-center gap-2">
              <Award className="h-4 w-4 text-blue-500" />
              <span>4th-10th Place: Γéª5,000 each</span>
            </li>
          </ul>
        </div>

        {/* Leaderboard List */}
        {leaderboard.length === 0 ? (
          <div className="text-center py-8 text-muted-foreground">
            <Trophy className="h-12 w-12 mx-auto mb-2 opacity-50" />
            <p>No referrals yet this month</p>
            <p className="text-sm">Be the first to start referring!</p>
          </div>
        ) : (
          <div className="space-y-3">
            {leaderboard.map((entry) => (
              <div
                key={entry.userId}
                className={`flex items-center gap-4 p-3 rounded-lg transition-colors ${
                  entry.rank <= 3
                    ? "bg-gradient-to-r from-yellow-50 to-orange-50 border border-yellow-200"
                    : "hover:bg-gray-50"
                }`}
              >
                {/* Rank */}
                <div className="flex-shrink-0 w-12 flex items-center justify-center">
                  {getRankIcon(entry.rank) || (
                    <span className="text-lg font-bold text-muted-foreground">
                      {entry.rank}
                    </span>
                  )}
                </div>

                {/* Avatar */}
                <Avatar className="h-10 w-10">
                  <AvatarImage src={entry.avatar || undefined} />
                  <AvatarFallback>
                    {entry.username.substring(0, 2).toUpperCase()}
                  </AvatarFallback>
                </Avatar>

                {/* User Info */}
                <div className="flex-1 min-w-0">
                  <p className="font-medium truncate">{entry.username}</p>
                  <p className="text-sm text-muted-foreground">
                    {entry.referralCount} referral
                    {entry.referralCount !== 1 ? "s" : ""}
                  </p>
                </div>

                {/* Badge & Prize */}
                <div className="flex-shrink-0 text-right">
                  {getRankBadge(entry.rank)}
                  {getPrizeInfo(entry.rank) && (
                    <p className="text-xs text-muted-foreground mt-1">
                      {getPrizeInfo(entry.rank)}
                    </p>
                  )}
                </div>
              </div>
            ))}
          </div>
        )}

        {/* Footer Note */}
        <div className="mt-6 p-3 bg-blue-50 rounded-lg border border-blue-200">
          <p className="text-sm text-blue-900">
            <strong>Note:</strong> Leaderboard resets monthly. Prizes are
            awarded on the 1st of each month to the previous month's winners.
          </p>
        </div>
      </CardContent>
    </Card>
  );
}

"use client";

/**
 * ReferralTracker Component
 * Displays referral code, share options, statistics, and earned rewards
 * Requirements: 17.1, 17.2, 17.6
 */

import { useState, useEffect } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { toast } from "sonner";
import {
  Copy,
  Share2,
  MessageCircle,
  Twitter,
  Facebook,
  Mail,
  TrendingUp,
  Users,
  Wallet,
  Clock,
} from "lucide-react";

interface ReferralStats {
  totalReferrals: number;
  successfulReferrals: number;
  pendingRewards: number;
  earnedRewards: number;
  monthlyCount: number;
  monthlyLimit: number;
}

interface ReferralTrackerProps {
  userId: string;
}

export function ReferralTracker({ userId }: ReferralTrackerProps) {
  const [referralCode, setReferralCode] = useState<string>("");
  const [stats, setStats] = useState<ReferralStats | null>(null);
  const [loading, setLoading] = useState(true);
  const [copying, setCopying] = useState(false);

  useEffect(() => {
    loadReferralData();
  }, [userId]);

  const loadReferralData = async () => {
    try {
      setLoading(true);

      // Fetch referral code
      const codeResponse = await fetch("/api/referrals/generate-code", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ userId }),
      });

      if (codeResponse.ok) {
        const codeData = await codeResponse.json();
        setReferralCode(codeData.code);
      }

      // Fetch stats
      const statsResponse = await fetch(`/api/referrals/stats?userId=${userId}`);
      if (statsResponse.ok) {
        const statsData = await statsResponse.json();
        setStats(statsData);
      }
    } catch (error) {
      console.error("Failed to load referral data:", error);
      toast.error("Failed to load referral data");
    } finally {
      setLoading(false);
    }
  };

  const getReferralLink = () => {
    const baseUrl = typeof window !== "undefined" ? window.location.origin : "";
    return `${baseUrl}/register?ref=${referralCode}`;
  };

  const copyToClipboard = async () => {
    try {
      setCopying(true);
      await navigator.clipboard.writeText(getReferralLink());
      toast.success("Referral link copied to clipboard!");
    } catch (error) {
      toast.error("Failed to copy link");
    } finally {
      setCopying(false);
    }
  };

  const shareViaWhatsApp = () => {
    const message = encodeURIComponent(
      `Join FindAm using my referral code ${referralCode} and get Γéª200 bonus! ${getReferralLink()}`,
    );
    window.open(`https://wa.me/?text=${message}`, "_blank");
  };

  const shareViaTwitter = () => {
    const message = encodeURIComponent(
      `Join FindAm using my referral code ${referralCode} and get Γéª200 bonus!`,
    );
    const url = encodeURIComponent(getReferralLink());
    window.open(
