"use client";

/**
 * ListingReviewsSection Component
 * Task 19.2: Display reviews with sorting and filtering
 * Requirements: 25.1, 25.4, 25.6, 25.8, 25.9
 * 
 * Features:
 * - Display average ratings with 5-star breakdown (Requirement 25.1, 25.4)
 * - Show "Verified Purchase" badges on confirmed buyer reviews (Requirement 25.6)
 * - Sort reviews by helpfulness, recency, or rating (Requirement 25.9)
 * - Allow vendors to respond to reviews publicly (Requirement 25.8)
 */

import { useState, useEffect } from "react";
import Image from "next/image";
import { Star, ThumbsUp, CheckCircle2, MessageSquare, ChevronDown } from "lucide-react";
import { Button } from "@/components/ui/button";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { cn } from "@/lib/utils";
import { motion, AnimatePresence } from "framer-motion";
import { toast } from "sonner";

interface Review {
  id: string;
  rating: number;
  comment: string | null;
  is_verified_purchase: boolean;
  helpfulness_votes: number;
  vendor_response: string | null;
  vendor_responded_at: string | null;
  created_at: string;
  reviewer: {
    id: string;
    username: string;
    avatar_url: string | null;
    trust_score: number;
  };
  images?: string[];
}

interface ReviewData {
  data: Review[];
  average: number;
  count: number;
  ratingDistribution: {
    5: number;
    4: number;
    3: number;
    2: number;
    1: number;
  };
}

interface ListingReviewsSectionProps {
  listingId: string;
  vendorId: string;
  currentUserId?: string;
  isVendor?: boolean;
  className?: string;
}

export function ListingReviewsSection({
  listingId,
  vendorId,
  currentUserId,
  isVendor = false,
  className,
}: ListingReviewsSectionProps) {
  const [reviewData, setReviewData] = useState<ReviewData | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [sortBy, setSortBy] = useState<"recency" | "helpfulness" | "rating">("recency");
  const [respondingTo, setRespondingTo] = useState<string | null>(null);
  const [responseText, setResponseText] = useState("");
  const [isSubmittingResponse, setIsSubmittingResponse] = useState(false);

  // Fetch reviews
  const fetchReviews = async () => {
    setIsLoading(true);
    try {
      const response = await fetch(`/api/reviews?listing_id=${listingId}&sort=${sortBy}`);
      if (!response.ok) throw new Error("Failed to fetch reviews");

      const data = await response.json();
      setReviewData(data);
    } catch (error) {
      console.error("Error fetching reviews:", error);
      toast.error("Failed to load reviews");
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchReviews();
  }, [listingId, sortBy]);

  // Submit vendor response
  const handleSubmitResponse = async (reviewId: string) => {
    if (!responseText.trim()) {
      toast.error("Please enter a response");
      return;
    }

    setIsSubmittingResponse(true);
    try {
      const response = await fetch(`/api/reviews/${reviewId}/respond`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ response: responseText }),
      });

      if (!response.ok) {
        const error = await response.json();
        throw new Error(error.error || "Failed to submit response");
      }

      toast.success("Response submitted successfully!");
      setRespondingTo(null);
      setResponseText("");
      await fetchReviews();
    } catch (error: any) {
      toast.error(error.message);
    } finally {
      setIsSubmittingResponse(false);
    }
  };

  // Vote helpful
  const handleVoteHelpful = async (reviewId: string) => {
    try {
      const response = await fetch(`/api/reviews/${reviewId}/helpful`, {
        method: "POST",
      });

      if (!response.ok) {
        const error = await response.json();
        throw new Error(error.error || "Failed to vote");
      }

      await fetchReviews();
    } catch (error: any) {
      toast.error(error.message);
    }
  };

  const formatDate = (dateString: string): string => {
    const date = new Date(dateString);
    const now = new Date();
    const diffInMs = now.getTime() - date.getTime();
    const diffInDays = Math.floor(diffInMs / (1000 * 60 * 60 * 24));

    if (diffInDays === 0) return "Today";
    if (diffInDays === 1) return "Yesterday";
    if (diffInDays < 7) return `${diffInDays} days ago`;
    if (diffInDays < 30) return `${Math.floor(diffInDays / 7)} weeks ago`;
    if (diffInDays < 365) return `${Math.floor(diffInDays / 30)} months ago`;
    return `${Math.floor(diffInDays / 365)} years ago`;
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center py-12">
        <div className="h-8 w-8 animate-spin rounded-full border-4 border-naija-green border-t-transparent" />
      </div>
    );
  }

  if (!reviewData) {
    return null;
  }

  const { data: reviews, average, count, ratingDistribution } = reviewData;

  return (
    <div className={cn("space-y-6", className)}>
      {/* Requirement 25.1, 25.4: Average Rating & 5-Star Breakdown */}
      <div className="glass-card rounded-xl border border-dark-border p-6">
        <h2 className="text-2xl font-bold text-white mb-6">Customer Reviews</h2>

        <div className="grid md:grid-cols-2 gap-8">
          {/* Left: Average Rating */}
          <div className="flex flex-col items-center justify-center space-y-3 md:border-r border-gray-800 md:pr-8">
            <div className="text-center">
              <div className="text-5xl font-bold text-white mb-2">
                {average.toFixed(1)}
              </div>

              <div className="flex items-center justify-center gap-1 mb-2">
                {[1, 2, 3, 4, 5].map((star) => {
                  const filled = star <= Math.round(average);
                  return (
                    <Star
                      key={star}
                      className={cn(
                        "h-6 w-6",
                        filled
                          ? "fill-yellow-400 text-yellow-400"
                          : "text-gray-600"
                      )}
                    />
                  );
                })}
              </div>

              <p className="text-sm text-gray-400">
                Based on {count.toLocaleString()} review{count !== 1 ? "s" : ""}
              </p>
            </div>
          </div>

          {/* Right: 5-Star Breakdown */}
          <div className="space-y-3">
            <h3 className="text-sm font-medium text-white mb-4">
              Rating Distribution
            </h3>
            {[5, 4, 3, 2, 1].map((stars, index) => {
              const starCount = ratingDistribution[stars as keyof typeof ratingDistribution];
              const percentage = count > 0 ? (starCount / count) * 100 : 0;
              return (
                <motion.div
                  key={stars}
                  initial={{ opacity: 0, x: -20 }}
                  animate={{ opacity: 1, x: 0 }}
                  transition={{ duration: 0.3, delay: index * 0.05 }}
                  className="flex items-center gap-3"
                >
                  <div className="flex items-center gap-1 w-16 flex-shrink-0">
                    <span className="text-sm text-gray-400">{stars}</span>
                    <Star className="h-3 w-3 fill-yellow-400 text-yellow-400" />
                  </div>

                  <div className="flex-1 h-4 bg-gray-800 rounded-full overflow-hidden">
                    <motion.div
                      initial={{ width: 0 }}
                      animate={{ width: `${percentage}%` }}
                      transition={{ duration: 0.6, delay: index * 0.1 }}
                      className={cn(
                        "h-full rounded-full transition-all",
                        stars === 5 && "bg-naija-green",
                        stars === 4 && "bg-green-500",
                        stars === 3 && "bg-yellow-500",
                        stars === 2 && "bg-orange-500",
                        stars === 1 && "bg-red-500"
                      )}
                    />
                  </div>

                  <div className="w-12 text-right flex-shrink-0">
                    <span className="text-sm text-gray-400">{starCount}</span>
                  </div>
                </motion.div>
              );
            })}
          </div>
        </div>
      </div>

      {/* Requirement 25.9: Sort Controls */}
      {count > 0 && (
        <div className="flex items-center justify-between">
          <p className="text-sm text-gray-400">
            Showing {reviews.length} review{reviews.length !== 1 ? "s" : ""}
          </p>
          <Select value={sortBy} onValueChange={(value: any) => setSortBy(value)}>
            <SelectTrigger className="w-[200px]">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="recency">Most Recent</SelectItem>
              <SelectItem value="helpfulness">Most Helpful</SelectItem>
              <SelectItem value="rating">Highest Rating</SelectItem>
            </SelectContent>
          </Select>
        </div>
      )}

      {/* Reviews List */}
      {reviews.length === 0 ? (
        <div className="text-center py-12">
          <div className="inline-flex h-16 w-16 items-center justify-center rounded-full bg-gray-800/50 mb-4">
            <Star className="h-8 w-8 text-gray-600" />
          </div>
          <p className="text-gray-400 font-medium">No reviews yet</p>
          <p className="text-sm text-gray-500 mt-1">
            Be the first to leave a review!
          </p>
        </div>
      ) : (
        <div className="space-y-4">
          <AnimatePresence mode="popLayout">
            {reviews.map((review, index) => (
              <motion.div
                key={review.id}
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, x: -100 }}
                transition={{ duration: 0.3, delay: index * 0.05 }}
                className="glass-card rounded-xl border border-dark-border p-6 hover:border-naija-green/30 transition-colors"
              >
                <div className="flex gap-4">
                  {/* Reviewer Avatar */}
                  <div className="flex-shrink-0">
                    <div className="h-12 w-12 overflow-hidden rounded-full border border-gray-700">
                      {review.reviewer?.avatar_url ? (
                        <Image
                          src={review.reviewer.avatar_url}
                          alt={review.reviewer.username || "User"}
                          width={48}
                          height={48}
                          className="h-full w-full object-cover"
                        />
                      ) : (
                        <div className="flex h-full w-full items-center justify-center bg-gradient-to-br from-naija-green to-neon-cyan text-lg font-bold text-white">
                          {(review.reviewer?.username || "U").charAt(0).toUpperCase()}
                        </div>
                      )}
                    </div>
                  </div>

                  {/* Review Content */}
                  <div className="flex-1 min-w-0 space-y-3">
                    {/* Header */}
                    <div className="space-y-1">
                      <div className="flex items-center gap-2 flex-wrap">
                        <h4 className="font-semibold text-white">
                          {review.reviewer?.username || "Anonymous User"}
                        </h4>

                        {/* Requirement 25.6: Verified Purchase Badge */}
                        {review.is_verified_purchase && (
                          <span className="inline-flex items-center gap-1 bg-naija-green/20 text-naija-green px-2 py-0.5 rounded-full text-xs font-medium">
                            <CheckCircle2 className="h-3 w-3" />
                            Verified Purchase
                          </span>
                        )}
                      </div>

                      <div className="flex items-center gap-3">
                        {/* Star Rating */}
                        <div className="flex items-center gap-0.5">
                          {[1, 2, 3, 4, 5].map((star) => (
                            <Star
                              key={star}
                              className={cn(
                                "h-4 w-4",
                                star <= review.rating
                                  ? "fill-yellow-400 text-yellow-400"
                                  : "text-gray-600"
                              )}
                            />
                          ))}
                        </div>
                        <span className="text-xs text-gray-400">
                          {formatDate(review.created_at)}
                        </span>
                      </div>
                    </div>

                    {/* Comment */}
                    {review.comment && (
                      <p className="text-sm text-gray-300 leading-relaxed">
                        {review.comment}
                      </p>
                    )}

                    {/* Review Images */}
                    {review.images && review.images.length > 0 && (
                      <div className="flex gap-2 flex-wrap">
                        {review.images.map((imageUrl, imgIndex) => (
                          <div
                            key={imgIndex}
                            className="w-20 h-20 rounded-lg overflow-hidden border border-gray-700"
                          >
                            <Image
                              src={imageUrl}
                              alt={`Review image ${imgIndex + 1}`}
                              width={80}
                              height={80}
                              className="w-full h-full object-cover"
                            />
                          </div>
                        ))}
                      </div>
                    )}

                    {/* Helpfulness Votes */}
                    <div className="flex items-center gap-4">
                      <Button
                        variant="ghost"
                        size="sm"
                        onClick={() => handleVoteHelpful(review.id)}
                        disabled={!currentUserId}
                        className="gap-2 text-xs"
                      >
                        <ThumbsUp className="h-3 w-3" />
                        Helpful ({review.helpfulness_votes})
                      </Button>

                      {/* Requirement 25.8: Vendor Response Button */}
                      {isVendor && !review.vendor_response && (
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => setRespondingTo(review.id)}
                          className="gap-2 text-xs"
                        >
                          <MessageSquare className="h-3 w-3" />
                          Respond
                        </Button>
                      )}
                    </div>

                    {/* Requirement 25.8: Vendor Response Form */}
                    {respondingTo === review.id && (
                      <motion.div
                        initial={{ opacity: 0, height: 0 }}
                        animate={{ opacity: 1, height: "auto" }}
                        className="mt-4 space-y-3"
                      >
                        <textarea
                          value={responseText}
                          onChange={(e) => setResponseText(e.target.value)}
                          placeholder="Write your response..."
                          className="w-full px-4 py-3 bg-dark-card border border-gray-700 rounded-lg text-white placeholder-gray-500 focus:border-naija-green focus:outline-none focus:ring-1 focus:ring-naija-green resize-none"
                          rows={3}
                        />
                        <div className="flex gap-2">
                          <Button
                            onClick={() => handleSubmitResponse(review.id)}
                            disabled={isSubmittingResponse || !responseText.trim()}
                            size="sm"
                            variant="neon"
                          >
                            {isSubmittingResponse ? "Submitting..." : "Submit Response"}
                          </Button>
                          <Button
                            onClick={() => {
                              setRespondingTo(null);
                              setResponseText("");
                            }}
                            size="sm"
                            variant="outline"
                          >
                            Cancel
                          </Button>
                        </div>
                      </motion.div>
                    )}

                    {/* Requirement 25.8: Display Vendor Response */}
                    {review.vendor_response && (
                      <motion.div
                        initial={{ opacity: 0, y: 10 }}
                        animate={{ opacity: 1, y: 0 }}
                        className="mt-4 ml-4 pl-4 border-l-2 border-naija-green/30 space-y-2"
                      >
                        <div className="flex items-center gap-2">
                          <div className="h-6 w-6 rounded-full bg-naija-green/20 flex items-center justify-center">
                            <span className="text-xs font-bold text-naija-green">
                              V
                            </span>
                          </div>
                          <p className="text-xs font-medium text-naija-green">
                            Vendor Response
                          </p>
                          {review.vendor_responded_at && (
                            <span className="text-xs text-gray-500">
                              {formatDate(review.vendor_responded_at)}
                            </span>
                          )}
                        </div>
                        <p className="text-sm text-gray-300 leading-relaxed">
                          {review.vendor_response}
                        </p>
                      </motion.div>
                    )}
                  </div>
                </div>
              </motion.div>
            ))}
          </AnimatePresence>
        </div>
      )}
    </div>
  );
}

"use client";

import { useState } from "react";
import Link from "next/link";
import Image from "next/image";
import { motion, AnimatePresence } from "framer-motion";
import {
  MapPin,
  Star,
  BadgeCheck,
  Crown,
  Phone,
  Mail,
  Globe,
  Navigation,
  Package,
  Store,
  ChevronLeft,
  ChevronRight,
  AlertCircle,
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import type { BusinessProfile } from "@/lib/types/business-profile";

interface SearchResultsProps {
  businesses: (BusinessProfile & { distance_km?: number })[];
  total: number;
  page: number;
  limit: number;
  hasMore: boolean;
  searchMetadata?: {
    query_time_ms: number;
    total_results: number;
    using_vector_search: boolean;
  };
  onPageChange?: (page: number) => void;
  isLoading?: boolean;
}

/**
 * SearchResults component for displaying business search results
 * 
 * Features:
 * - Grid layout for business cards (responsive)
 * - Distance display from user location (if location filter applied)
 * - Premium business highlighting
 * - Verified business badges
 * - Matched search terms highlighting
 * - Pagination controls
 * - Zero results message
 * - Search metadata display
 * 
 * Requirements: 4.3, 4.5, 6.5, 7.6
 */
export function SearchResults({
  businesses,
  total,
  page,
  limit,
  hasMore,
  searchMetadata,
  onPageChange,
  isLoading = false,
}: SearchResultsProps) {
  const [imageErrors, setImageErrors] = useState<Set<string>>(new Set());

  const handleImageError = (businessId: string) => {
    setImageErrors((prev) => new Set(prev).add(businessId));
  };

  const handlePrevPage = () => {
    if (page > 1 && onPageChange) {
      onPageChange(page - 1);
      window.scrollTo({ top: 0, behavior: "smooth" });
    }
  };

  const handleNextPage = () => {
    if (hasMore && onPageChange) {
      onPageChange(page + 1);
      window.scrollTo({ top: 0, behavior: "smooth" });
    }
  };

  // Zero results state
  if (!isLoading && businesses.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center py-16 px-4 text-center">
        <div className="bg-dark-card border-2 border-dashed border-dark-border rounded-xl p-12 max-w-md">
          <AlertCircle className="h-16 w-16 text-gray-400 mx-auto mb-4" />
          <h3 className="text-xl font-semibold text-white mb-2">
            No businesses found
          </h3>
          <p className="text-gray-400 mb-6">
            We couldn't find any businesses matching your search criteria. Try
            adjusting your filters or search terms.
          </p>
          <Button
            variant="outline"
            onClick={() => window.location.reload()}
            className="border-dark-border hover:bg-dark-bg"
          >
            Clear Filters
          </Button>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Search Metadata */}
      {searchMetadata && (
        <div className="flex items-center justify-between text-sm text-gray-400 pb-4 border-b border-dark-border">
          <div>
            <span className="text-white font-medium">{total}</span> businesses
            found
            {searchMetadata.query_time_ms > 0 && (
              <span className="ml-2">
                in {searchMetadata.query_time_ms}ms
              </span>
            )}
          </div>
          {searchMetadata.using_vector_search && (
            <Badge variant="outline" className="border-purple-500 text-purple-400">
              AI-Powered
            </Badge>
          )}
        </div>
      )}

      {/* Loading State */}
      {isLoading && (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {[...Array(6)].map((_, i) => (
            <div
              key={i}
              className="bg-dark-card border border-dark-border rounded-xl overflow-hidden animate-pulse"
            >
              <div className="h-48 bg-dark-bg" />
              <div className="p-4 space-y-3">
                <div className="h-4 bg-dark-bg rounded w-3/4" />
                <div className="h-3 bg-dark-bg rounded w-full" />
                <div className="h-3 bg-dark-bg rounded w-5/6" />
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Business Grid */}
      {!isLoading && (
        <motion.div
          layout
          className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6"
        >
          <AnimatePresence mode="popLayout">
            {businesses.map((business) => (
              <motion.div
                key={business.id}
                layout
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, scale: 0.95 }}
                transition={{ duration: 0.3 }}
              >
                <BusinessCard
                  business={business}
                  hasImageError={imageErrors.has(business.id)}
                  onImageError={() => handleImageError(business.id)}
                />
              </motion.div>
            ))}
          </AnimatePresence>
        </motion.div>
      )}

      {/* Pagination Controls */}
      {!isLoading && businesses.length > 0 && (
        <div className="flex items-center justify-between pt-6 border-t border-dark-border">
          <div className="text-sm text-gray-400">
            Showing {(page - 1) * limit + 1} to{" "}
            {Math.min(page * limit, total)} of {total} businesses
          </div>

          <div className="flex items-center gap-2">
            <Button
              variant="outline"
              size="sm"
              onClick={handlePrevPage}
              disabled={page === 1}
              className="border-dark-border hover:bg-dark-bg disabled:opacity-50"
            >
              <ChevronLeft className="h-4 w-4 mr-1" />
              Previous
            </Button>

            <div className="flex items-center gap-1">
              {/* Page numbers */}
              {Array.from({ length: Math.min(5, Math.ceil(total / limit)) }, (_, i) => {
                const pageNum = i + 1;
                const isCurrentPage = pageNum === page;

                return (
                  <Button
                    key={pageNum}
                    variant={isCurrentPage ? "default" : "outline"}
                    size="sm"
                    onClick={() => onPageChange && onPageChange(pageNum)}
                    className={
                      isCurrentPage
                        ? "bg-neon-cyan text-dark-bg hover:bg-neon-cyan/90"
                        : "border-dark-border hover:bg-dark-bg"
                    }
                  >
                    {pageNum}
                  </Button>
                );
              })}
            </div>

            <Button
              variant="outline"
              size="sm"
              onClick={handleNextPage}
              disabled={!hasMore}
              className="border-dark-border hover:bg-dark-bg disabled:opacity-50"
            >
              Next
              <ChevronRight className="h-4 w-4 ml-1" />
            </Button>
          </div>
        </div>
      )}
    </div>
  );
}

/**
 * BusinessCard component for displaying individual business in search results
 */
interface BusinessCardProps {
  business: BusinessProfile & { distance_km?: number };
  hasImageError: boolean;
  onImageError: () => void;
}

function BusinessCard({ business, hasImageError, onImageError }: BusinessCardProps) {
  const displayName = business.display_name || business.business_name;
  const hasLocation = business.distance_km !== undefined;

  return (
    <Link
      href={`/business-profiles/${business.id}`}
      className="block group"
    >
      <div
        className={`
        bg-dark-card border rounded-xl overflow-hidden 
        transition-all duration-300 h-full
        hover:shadow-xl hover:-translate-y-1
        ${
          business.is_premium
            ? "border-yellow-500/50 shadow-lg shadow-yellow-500/10"
            : "border-dark-border"
        }
      `}
      >
        {/* Image Section */}
        <div className="relative h-48 bg-dark-bg overflow-hidden">
          {business.primary_photo_url && !hasImageError ? (
            <Image
              src={business.primary_photo_url}
              alt={displayName}
              fill
              className="object-cover group-hover:scale-110 transition-transform duration-300"
              onError={onImageError}
            />
          ) : (
            <div className="w-full h-full flex items-center justify-center bg-gradient-to-br from-dark-bg to-dark-card">
              <Store className="h-16 w-16 text-gray-600" />
            </div>
          )}

          {/* Premium Badge Overlay */}
          {business.is_premium && (
            <div className="absolute top-3 left-3">
              <Badge className="bg-yellow-500/90 text-dark-bg border-0 font-semibold backdrop-blur-sm">
                <Crown className="h-3 w-3 mr-1" />
                Premium
              </Badge>
            </div>
          )}

          {/* Verified Badge Overlay */}
          {business.is_verified && (
            <div className="absolute top-3 right-3">
              <div className="bg-blue-500/90 backdrop-blur-sm rounded-full p-1.5">
                <BadgeCheck className="h-4 w-4 text-white" />
              </div>
            </div>
          )}

          {/* Distance Badge */}
          {hasLocation && (
            <div className="absolute bottom-3 right-3">
              <Badge className="bg-dark-bg/80 backdrop-blur-sm border-dark-border">
                <Navigation className="h-3 w-3 mr-1" />
                {business.distance_km} km
              </Badge>
            </div>
          )}
        </div>

        {/* Content Section */}
        <div className="p-4 space-y-3">
          {/* Business Name and Type */}
          <div>
            <h3 className="text-lg font-semibold text-white line-clamp-1 group-hover:text-neon-cyan transition-colors">
              {displayName}
            </h3>
            {business.primary_category && (
              <p className="text-sm text-gray-400 flex items-center gap-1 mt-1">
                <Package className="h-3 w-3" />
                {business.primary_category.name}
              </p>
            )}
          </div>

          {/* Description */}
          <p className="text-sm text-gray-300 line-clamp-2">
            {business.description}
          </p>

          {/* Location */}
          <div className="flex items-center gap-1.5 text-sm text-gray-400">
            <MapPin className="h-4 w-4 flex-shrink-0" />
            <span className="line-clamp-1">
              {business.city}, {business.state}
            </span>
          </div>

          {/* Rating and Reviews */}
          {business.review_count > 0 && (
            <div className="flex items-center gap-2">
              <div className="flex items-center gap-1">
                <Star className="h-4 w-4 fill-yellow-400 text-yellow-400" />
                <span className="text-sm font-medium text-white">
                  {business.average_rating.toFixed(1)}
                </span>
              </div>
              <span className="text-sm text-gray-400">
                ({business.review_count} {business.review_count === 1 ? "review" : "reviews"})
              </span>
            </div>
          )}

          {/* Price Range */}
          {business.price_range && (
            <div className="flex items-center gap-2">
              <span className="text-sm text-gray-400">Price:</span>
              <span className="text-sm font-medium text-green-400">
                {business.price_range}
              </span>
            </div>
          )}

          {/* Service Attributes */}
          {business.service_attributes && (
            <div className="flex flex-wrap gap-1.5">
              {business.service_attributes.delivery_available && (
                <Badge variant="outline" className="text-xs border-dark-border">
                  Delivery
                </Badge>
              )}
              {business.service_attributes.online_service && (
                <Badge variant="outline" className="text-xs border-dark-border">
                  Online
                </Badge>
              )}
              {business.service_attributes.availability_24_7 && (
                <Badge variant="outline" className="text-xs border-dark-border">
                  24/7
                </Badge>
              )}
            </div>
          )}

          {/* Contact Icons (Hidden on Mobile, Shown on Hover) */}
          <div className="flex items-center gap-2 pt-2 border-t border-dark-border opacity-0 group-hover:opacity-100 transition-opacity">
            {business.phone && (
              <div className="text-gray-400 hover:text-neon-cyan transition-colors">
                <Phone className="h-4 w-4" />
              </div>
            )}
            {business.email && (
              <div className="text-gray-400 hover:text-neon-cyan transition-colors">
                <Mail className="h-4 w-4" />
              </div>
            )}
            {business.website && (
              <div className="text-gray-400 hover:text-neon-cyan transition-colors">
                <Globe className="h-4 w-4" />
              </div>
            )}
          </div>
        </div>
      </div>
    </Link>
  );
}

"use client";

/**
 * MatchFeed Component
 * Displays all new matches across all saved searches
 * Requirements: 13.10
 * Task: 42.13
 */

import { useState, useEffect } from "react";
import { Bell, Search, Filter, X } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { motion, AnimatePresence } from "framer-motion";
import { toast } from "sonner";
import type { SearchAlert } from "@/lib/services/alert";
import Link from "next/link";
import Image from "next/image";

interface MatchFeedProps {
  userId: string;
}

export function MatchFeed({ userId }: MatchFeedProps) {
  const [alerts, setAlerts] = useState<SearchAlert[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [filter, setFilter] = useState<"all" | "new_listing" | "price_drop">(
    "all",
  );
  const [unreadOnly, setUnreadOnly] = useState(false);

  useEffect(() => {
    loadAlerts();
  }, [userId, filter, unreadOnly]);

  const loadAlerts = async () => {
    try {
      setIsLoading(true);
      const params = new URLSearchParams({
        limit: "50",
        offset: "0",
      });

      if (unreadOnly) {
        params.append("unreadOnly", "true");
      }

      const response = await fetch(`/api/alerts?${params.toString()}`);
      if (!response.ok) throw new Error("Failed to load alerts");

      const data = await response.json();
      let filteredAlerts = data.alerts || [];

      if (filter !== "all") {
        filteredAlerts = filteredAlerts.filter(
          (alert: SearchAlert) => alert.alert_type === filter,
        );
      }

      setAlerts(filteredAlerts);
    } catch (error) {
      console.error("Error loading alerts:", error);
      toast.error("Failed to load alerts");
    } finally {
      setIsLoading(false);
    }
  };

  const handleMarkAsRead = async (alertId: string) => {
    try {
      const response = await fetch(`/api/alerts/${alertId}/read`, {
        method: "POST",
      });

      if (!response.ok) throw new Error("Failed to mark as read");

      // Update local state
      setAlerts((prev) =>
        prev.map((alert) =>
          alert.id === alertId ? { ...alert, is_read: true } : alert,
        ),
      );
    } catch (error) {
      console.error("Error marking alert as read:", error);
      toast.error("Failed to mark as read");
    }
  };

  const formatTimeAgo = (date: Date): string => {
    const now = new Date();
    const diffMs = now.getTime() - new Date(date).getTime();
    const diffMins = Math.floor(diffMs / 60000);
    const diffHours = Math.floor(diffMs / 3600000);
    const diffDays = Math.floor(diffMs / 86400000);

    if (diffMins < 1) return "Just now";
    if (diffMins < 60) return `${diffMins}m ago`;
    if (diffHours < 24) return `${diffHours}h ago`;
    return `${diffDays}d ago`;
  };

  const unreadCount = alerts.filter((alert) => !alert.is_read).length;

  if (isLoading) {
    return (
      <div className="flex items-center justify-center p-8">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary"></div>
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold flex items-center gap-2">
            Match Feed
            {unreadCount > 0 && (
              <Badge variant="destructive">{unreadCount} new</Badge>
            )}
          </h2>
          <p className="text-sm text-muted-foreground">
            New listings and price drops from your saved searches
          </p>
        </div>
        <Button
          variant={unreadOnly ? "default" : "outline"}
          size="sm"
          onClick={() => setUnreadOnly(!unreadOnly)}
        >
          <Bell className="h-4 w-4 mr-2" />
          {unreadOnly ? "Show All" : "Unread Only"}
        </Button>
      </div>

      {/* Filter Tabs */}
      <Tabs value={filter} onValueChange={(value: any) => setFilter(value)}>
        <TabsList>
          <TabsTrigger value="all">All</TabsTrigger>
          <TabsTrigger value="new_listing">New Listings</TabsTrigger>
          <TabsTrigger value="price_drop">Price Drops</TabsTrigger>
        </TabsList>
      </Tabs>

      {/* Alerts List */}
      {alerts.length === 0 ? (
        <Card>
          <CardContent className="flex flex-col items-center justify-center py-12">
            <Search className="h-12 w-12 text-muted-foreground mb-4" />
            <h3 className="text-lg font-semibold mb-2">No matches yet</h3>
            <p className="text-sm text-muted-foreground text-center">
              {unreadOnly
                ? "You've read all your alerts"
                : "We'll notify you when new listings match your saved searches"}
            </p>
          </CardContent>
        </Card>
      ) : (
        <div className="space-y-3">
          <AnimatePresence>
            {alerts.map((alert) => (
              <motion.div
                key={alert.id}
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: -20 }}
                transition={{ duration: 0.2 }}
              >
                <Card
                  className={`transition-all hover:shadow-md ${
                    !alert.is_read ? "border-l-4 border-l-primary" : ""
                  }`}
                >
                  <CardContent className="p-4">
                    <div className="flex gap-4">
                      {/* Listing Image */}
                      {alert.listing_snapshot?.imageUrl && (
                        <div className="relative w-20 h-20 flex-shrink-0 rounded-md overflow-hidden">
                          <Image
                            src={alert.listing_snapshot.imageUrl}
                            alt={alert.listing_snapshot.title || "Listing"}
                            fill
                            className="object-cover"
                          />
                        </div>
                      )}

                      {/* Alert Content */}
                      <div className="flex-1 min-w-0">
                        <div className="flex items-start justify-between gap-2 mb-2">
                          <div className="flex-1">
                            <Badge
                              variant={
                                alert.alert_type === "price_drop"
                                  ? "destructive"
                                  : "default"
                              }
                              className="mb-2"
                            >
                              {alert.alert_type === "price_drop"
                                ? `${alert.price_drop_percentage}% Price Drop`
                                : "New Match"}
                            </Badge>
                            <h3 className="font-semibold text-sm line-clamp-2">
                              {alert.listing_snapshot?.title || "Listing"}
                            </h3>
                          </div>
                          {!alert.is_read && (
                            <Button
                              variant="ghost"
                              size="sm"
                              onClick={() => handleMarkAsRead(alert.id)}
                            >
                              <X className="h-4 w-4" />
                            </Button>
                          )}
                        </div>

                        {/* Price Information */}
                        <div className="flex items-center gap-2 mb-2">
                          {alert.alert_type === "price_drop" &&
                          alert.previous_price ? (
                            <>
                              <span className="text-sm text-muted-foreground line-through">
                                Γéª{alert.previous_price.toLocaleString()}
                              </span>
                              <span className="text-lg font-bold text-green-600">
                                Γéª{alert.new_price?.toLocaleString()}
                              </span>
                            </>
                          ) : (
                            <span className="text-lg font-bold">
                              Γéª{alert.listing_snapshot?.price?.toLocaleString()}
                            </span>
                          )}
                        </div>

                        {/* Footer */}
                        <div className="flex items-center justify-between">
                          <span className="text-xs text-muted-foreground">
                            {formatTimeAgo(alert.sent_at)}
                          </span>
                          <Link href={`/listing/${alert.listing_id}`}>
                            <Button size="sm" variant="outline">
                              View Listing
                            </Button>
                          </Link>
                        </div>
                      </div>
                    </div>
                  </CardContent>
                </Card>
              </motion.div>
            ))}
          </AnimatePresence>
        </div>
      )}
    </div>
  );
}

"use client";

import { useOfflineActions } from "@/lib/hooks/useOfflineActions";
import { WifiOff, RefreshCw, CheckCircle } from "lucide-react";
import { Button } from "@/components/ui/button";
import { motion, AnimatePresence } from "framer-motion";

export function OfflineIndicator() {
  const { online, queuedCount, isSyncing, triggerSync } = useOfflineActions();

  // Don't show anything if online and no queued actions
  if (online && queuedCount === 0) {
    return null;
  }

  return (
    <AnimatePresence>
      <motion.div
        initial={{ y: 100, opacity: 0 }}
        animate={{ y: 0, opacity: 1 }}
        exit={{ y: 100, opacity: 0 }}
        className="fixed bottom-20 left-1/2 -translate-x-1/2 z-50 md:bottom-4"
      >
        <div className="bg-background/95 backdrop-blur-lg border border-border rounded-full px-4 py-2 shadow-lg flex items-center gap-3">
          {!online ? (
            <>
              <WifiOff className="h-4 w-4 text-destructive" />
              <span className="text-sm font-medium">You're offline</span>
              {queuedCount > 0 && (
                <span className="text-xs text-muted-foreground">
                  {queuedCount} action{queuedCount > 1 ? "s" : ""} queued
                </span>
              )}
            </>
          ) : isSyncing ? (
            <>
              <RefreshCw className="h-4 w-4 text-primary animate-spin" />
              <span className="text-sm font-medium">Syncing...</span>
            </>
          ) : queuedCount > 0 ? (
            <>
              <CheckCircle className="h-4 w-4 text-primary" />
              <span className="text-sm font-medium">
                {queuedCount} action{queuedCount > 1 ? "s" : ""} pending
              </span>
              <Button
                size="sm"
                variant="ghost"
                onClick={triggerSync}
                className="h-6 px-2 text-xs"
              >
                Sync now
              </Button>
            </>
          ) : null}
        </div>
      </motion.div>
    </AnimatePresence>
  );
}

