"use client";

import { useState, useEffect, useRef, useCallback } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { X, ChevronLeft, ChevronRight, Pause, Play } from "lucide-react";
import type { Story } from "@/lib/types";
import Image from "next/image";

interface StoryViewerProps {
  stories: Story[];
  initialIndex?: number;
  onClose: () => void;
  onNext?: () => void;
  onPrevious?: () => void;
  onStoryView?: (storyId: string) => void;
}

export function StoryViewer({
  stories,
  initialIndex = 0,
  onClose,
  onNext,
  onPrevious,
  onStoryView,
}: StoryViewerProps) {
  const [currentIndex, setCurrentIndex] = useState(initialIndex);
  const [isPaused, setIsPaused] = useState(false);
  const [progress, setProgress] = useState(0);
  const videoRef = useRef<HTMLVideoElement>(null);
  const progressIntervalRef = useRef<NodeJS.Timeout | null>(null);

  const currentStory = stories[currentIndex];
  const STORY_DURATION = 30000; // 30 seconds max

  // Track story view
  useEffect(() => {
    if (currentStory && onStoryView) {
      onStoryView(currentStory.id);
    }
  }, [currentStory, onStoryView]);

  // Handle progress bar
  useEffect(() => {
    if (isPaused) {
      if (progressIntervalRef.current) {
        clearInterval(progressIntervalRef.current);
      }
      return;
    }

    setProgress(0);
    const startTime = Date.now();

    progressIntervalRef.current = setInterval(() => {
      const elapsed = Date.now() - startTime;
      const newProgress = Math.min((elapsed / STORY_DURATION) * 100, 100);
      setProgress(newProgress);

      if (newProgress >= 100) {
        handleNext();
      }
    }, 50);

    return () => {
      if (progressIntervalRef.current) {
        clearInterval(progressIntervalRef.current);
      }
    };
  }, [currentIndex, isPaused]);

  // Handle video playback
  useEffect(() => {
    const video = videoRef.current;
    if (!video) return;

    if (isPaused) {
      video.pause();
    } else {
      video.play().catch((err) => console.error("Error playing video:", err));
    }
  }, [isPaused, currentIndex]);

  const handleNext = useCallback(() => {
    if (currentIndex < stories.length - 1) {
      setCurrentIndex((prev) => prev + 1);
      setProgress(0);
    } else if (onNext) {
      onNext();
    } else {
      onClose();
    }
  }, [currentIndex, stories.length, onNext, onClose]);

  const handlePrevious = useCallback(() => {
    if (currentIndex > 0) {
      setCurrentIndex((prev) => prev - 1);
      setProgress(0);
    } else if (onPrevious) {
      onPrevious();
    }
  }, [currentIndex, onPrevious]);

  const handleTap = useCallback(
    (e: React.MouseEvent<HTMLDivElement>) => {
      const rect = e.currentTarget.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const width = rect.width;

      if (x < width / 3) {
        handlePrevious();
      } else if (x > (width * 2) / 3) {
        handleNext();
      } else {
        setIsPaused((prev) => !prev);
      }
    },
    [handleNext, handlePrevious],
  );

  // Keyboard navigation
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === "ArrowRight") handleNext();
      if (e.key === "ArrowLeft") handlePrevious();
      if (e.key === "Escape") onClose();
      if (e.key === " ") {
        e.preventDefault();
        setIsPaused((prev) => !prev);
      }
    };

    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [handleNext, handlePrevious, onClose]);

  if (!currentStory) return null;

  return (
    <AnimatePresence>
      <motion.div
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        exit={{ opacity: 0 }}
        className="fixed inset-0 z-50 bg-black"
      >
        {/* Progress bars */}
        <div className="absolute top-0 left-0 right-0 z-10 flex gap-1 p-2">
          {stories.map((_, index) => (
            <div
              key={index}
              className="flex-1 h-1 bg-white/30 rounded-full overflow-hidden"
            >
              <motion.div
                className="h-full bg-white"
                initial={{ width: "0%" }}
                animate={{
                  width:
                    index < currentIndex
                      ? "100%"
                      : index === currentIndex
                        ? `${progress}%`
                        : "0%",
                }}
                transition={{ duration: 0.1 }}
              />
            </div>
          ))}
        </div>

        {/* Header */}
        <div className="absolute top-4 left-0 right-0 z-10 flex items-center justify-between px-4 pt-4">
          <div className="flex items-center gap-3">
            {currentStory.user?.avatar_url && (
              <Image
                src={currentStory.user.avatar_url}
                alt={currentStory.user.username || "User"}
                width={40}
                height={40}
                className="rounded-full border-2 border-white"
              />
            )}
            <div>
              <p className="text-white font-semibold">
                {currentStory.user?.username || "Unknown"}
              </p>
              <p className="text-white/70 text-sm">
                {new Date(currentStory.created_at).toLocaleTimeString()}
              </p>
            </div>
          </div>

          <button
            onClick={onClose}
            className="text-white hover:bg-white/20 rounded-full p-2 transition-colors"
            aria-label="Close story viewer"
          >
            <X size={24} />
          </button>
        </div>

        {/* Video content */}
        <div
          onClick={handleTap}
          className="relative w-full h-full flex items-center justify-center cursor-pointer"
        >
          <video
            ref={videoRef}
            src={currentStory.video_url}
            className="max-w-full max-h-full object-contain"
            playsInline
            loop={false}
            onEnded={handleNext}
          />

          {/* Pause indicator */}
          {isPaused && (
            <motion.div
              initial={{ scale: 0 }}
              animate={{ scale: 1 }}
              exit={{ scale: 0 }}
              className="absolute inset-0 flex items-center justify-center pointer-events-none"
            >
              <div className="bg-black/50 rounded-full p-4">
                <Pause size={48} className="text-white" />
              </div>
            </motion.div>
          )}

          {/* Navigation hints */}
          <div className="absolute inset-y-0 left-0 w-1/3 flex items-center justify-start pl-4 opacity-0 hover:opacity-100 transition-opacity">
            {(currentIndex > 0 || onPrevious) && (
              <div className="bg-black/30 rounded-full p-2">
                <ChevronLeft size={32} className="text-white" />
              </div>
            )}
          </div>
          <div className="absolute inset-y-0 right-0 w-1/3 flex items-center justify-end pr-4 opacity-0 hover:opacity-100 transition-opacity">
            {(currentIndex < stories.length - 1 || onNext) && (
              <div className="bg-black/30 rounded-full p-2">
                <ChevronRight size={32} className="text-white" />
              </div>
            )}
          </div>
        </div>

        {/* View count */}
        <div className="absolute bottom-4 left-4 text-white/70 text-sm">
          {currentStory.views_count} views
        </div>
      </motion.div>
    </AnimatePresence>
  );
}

"use client";

/**
 * Subscription Downgrade Dialog Component
 * Allows users to downgrade subscription with prorated refund preview
 * Requirements: 24.9
 */

import { useState, useEffect } from "react";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { Loader2, AlertTriangle, ArrowDown, Wallet } from "lucide-react";
import { toast } from "sonner";

interface DowngradeDialogProps {
  currentPlan: "pro" | "enterprise";
  newPlan: "basic" | "pro";
  onDowngraded?: () => void;
  trigger?: React.ReactNode;
}

export function DowngradeDialog({
  currentPlan,
  newPlan,
  onDowngraded,
  trigger,
}: DowngradeDialogProps) {
  const [open, setOpen] = useState(false);
  const [loading, setLoading] = useState(false);
  const [calculatingRefund, setCalculatingRefund] = useState(false);
  const [refundAmount, setRefundAmount] = useState<number | null>(null);
  const [refundMessage, setRefundMessage] = useState("");

  // Calculate refund when dialog opens
  useEffect(() => {
    if (open && refundAmount === null) {
      fetchRefundEstimate();
    }
  }, [open]);

  const fetchRefundEstimate = async () => {
    setCalculatingRefund(true);
    try {
      const response = await fetch(
        `/api/subscription/downgrade?new_plan=${newPlan}`,
      );

      if (!response.ok) {
        throw new Error("Failed to calculate refund");
      }

      const data = await response.json();
      setRefundAmount(data.refund_amount);
      setRefundMessage(data.message);
    } catch (error) {
      console.error("Refund calculation error:", error);
      toast.error("Failed to calculate refund estimate");
    } finally {
      setCalculatingRefund(false);
    }
  };

  const handleDowngrade = async () => {
    setLoading(true);
    try {
      const response = await fetch("/api/subscription/downgrade", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          new_plan: newPlan,
          apply_refund: true,
        }),
      });

      if (!response.ok) {
        const error = await response.json();
        throw new Error(error.error || "Failed to downgrade subscription");
      }

      const data = await response.json();
      toast.success(data.message);
      setOpen(false);
      onDowngraded?.();
    } catch (error) {
      console.error("Downgrade error:", error);
      toast.error(
        error instanceof Error
          ? error.message
          : "Failed to downgrade subscription",
      );
    } finally {
      setLoading(false);
    }
  };

  const planNames: Record<string, string> = {
    basic: "Basic",
    pro: "Pro",
    enterprise: "Enterprise",
  };

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        {trigger || (
          <Button variant="outline" size="sm">
            <ArrowDown className="h-4 w-4 mr-2" />
            Downgrade to {planNames[newPlan]}
          </Button>
        )}
      </DialogTrigger>
      <DialogContent>
        <DialogHeader>
          <DialogTitle>Downgrade Subscription</DialogTitle>
          <DialogDescription>
            You are about to downgrade from {planNames[currentPlan]} to{" "}
            {planNames[newPlan]}.
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-4 py-4">
          {/* Refund Calculation */}
          {calculatingRefund ? (
            <div className="flex items-center justify-center py-4">
              <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
              <span className="ml-2 text-sm text-muted-foreground">
                Calculating refund...
              </span>
            </div>
          ) : refundAmount !== null ? (
            <Alert className="border-blue-200 bg-blue-50">
              <Wallet className="h-4 w-4 text-blue-600" />
              <AlertDescription className="text-blue-900">
                {refundMessage}
                {refundAmount > 0 && (
                  <div className="mt-2 font-semibold text-lg">
                    Γéª{refundAmount.toFixed(2)}
                  </div>
                )}
              </AlertDescription>
            </Alert>
          ) : null}

          {/* Warning About Feature Loss */}
          <Alert className="border-yellow-200 bg-yellow-50">
            <AlertTriangle className="h-4 w-4 text-yellow-600" />
            <AlertDescription className="text-yellow-900">
              <div className="font-medium mb-1">Features you will lose:</div>
              <ul className="text-sm list-disc list-inside space-y-1">
                {currentPlan === "enterprise" && newPlan === "pro" && (
                  <>
                    <li>3 free boosts per month (Enterprise only)</li>
                    <li>Priority support</li>
                    <li>Custom domain</li>
                  </>
                )}
                {newPlan === "basic" && (
                  <>
                    <li>Unlimited listings (limited to 10)</li>
                    <li>Advanced analytics</li>
                    <li>CSV export</li>
                    <li>Free monthly boosts</li>
                    {currentPlan === "enterprise" && (
                      <>
                        <li>Priority support</li>
                        <li>Custom domain</li>
                      </>
                    )}
                  </>
                )}
              </ul>
            </AlertDescription>
          </Alert>

          {/* Timing Information */}
          <p className="text-sm text-muted-foreground">
            {newPlan === "basic"
              ? "Your downgrade will take effect at the end of your current billing period. You will continue to have access to premium features until then."
              : "Your plan will be updated immediately."}
          </p>
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={() => setOpen(false)}>
            Cancel
          </Button>
          <Button
            onClick={handleDowngrade}
            disabled={loading || calculatingRefund}
            variant="destructive"
          >
            {loading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
            Confirm Downgrade
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { useState, useEffect } from "react";
import { Search, Play, Pause, TrendingUp, Music, Filter } from "lucide-react";
import { TrendingSound } from "@/lib/services/trending-sounds";

interface TrendingSoundsLibraryProps {
  onSelectSound?: (sound: TrendingSound) => void;
  selectedSoundId?: string;
}

const SOUND_CATEGORIES = [
  "Pop",
  "Hip Hop",
  "Electronic",
  "Rock",
  "R&B",
  "Afrobeats",
  "Jazz",
  "Classical",
  "Other",
];

export function TrendingSoundsLibrary({
  onSelectSound,
  selectedSoundId,
}: TrendingSoundsLibraryProps) {
  const [sounds, setSounds] = useState<TrendingSound[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState("");
  const [selectedCategory, setSelectedCategory] = useState<string>("");
  const [playingId, setPlayingId] = useState<string | null>(null);
  const [showTrendingOnly, setShowTrendingOnly] = useState(true);

  useEffect(() => {
    fetchSounds();
  }, [selectedCategory, showTrendingOnly]);

  const fetchSounds = async () => {
    setLoading(true);
    try {
      const endpoint = showTrendingOnly
        ? "/api/trending-sounds/trending"
        : "/api/trending-sounds";

      const params = new URLSearchParams();
      if (selectedCategory) params.append("category", selectedCategory);
      if (!showTrendingOnly && searchQuery)
        params.append("search", searchQuery);

      const response = await fetch(`${endpoint}?${params.toString()}`);
      if (response.ok) {
        const data = await response.json();
        setSounds(data.sounds || []);
      }
    } catch (error) {
      console.error("Failed to fetch sounds:", error);
    } finally {
      setLoading(false);
    }
  };

  const handleSearch = () => {
    if (!showTrendingOnly) {
      fetchSounds();
    }
  };

  const filteredSounds = sounds.filter((sound) => {
    if (!searchQuery) return true;
    const query = searchQuery.toLowerCase();
    return (
      sound.title.toLowerCase().includes(query) ||
      sound.artist?.toLowerCase().includes(query) ||
      sound.tags.some((tag) => tag.toLowerCase().includes(query))
    );
  });

  const togglePlay = (soundId: string) => {
    if (playingId === soundId) {
      setPlayingId(null);
    } else {
      setPlayingId(soundId);
    }
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div>
        <h2 className="text-2xl font-bold text-gray-900">Trending Sounds</h2>
        <p className="mt-1 text-gray-600">
          Browse and select audio clips for your video listings
        </p>
      </div>

      {/* Filters */}
      <div className="rounded-lg border border-gray-200 bg-white p-4">
        <div className="grid gap-4 md:grid-cols-3">
          {/* Search */}
          <div className="relative">
            <Search className="absolute left-3 top-1/2 h-5 w-5 -translate-y-1/2 text-gray-400" />
            <input
              type="text"
              placeholder="Search sounds..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              onKeyDown={(e) => e.key === "Enter" && handleSearch()}
              className="w-full rounded-lg border border-gray-300 py-2 pl-10 pr-4 focus:border-blue-500 focus:outline-none focus:ring-1 focus:ring-blue-500"
            />
          </div>

          {/* Category Filter */}
          <div className="relative">
            <Filter className="absolute left-3 top-1/2 h-5 w-5 -translate-y-1/2 text-gray-400" />
            <select
              id="category-filter"
              value={selectedCategory}
              onChange={(e) => setSelectedCategory(e.target.value)}
              title="Filter by category"
              className="w-full appearance-none rounded-lg border border-gray-300 py-2 pl-10 pr-10 focus:border-blue-500 focus:outline-none focus:ring-1 focus:ring-blue-500"
            >
              <option value="">All Categories</option>
              {SOUND_CATEGORIES.map((cat) => (
                <option key={cat} value={cat}>
                  {cat}
                </option>
              ))}
            </select>
          </div>

          {/* Trending Toggle */}
          <label className="flex items-center space-x-2">
            <input
              type="checkbox"
              checked={showTrendingOnly}
              onChange={(e) => setShowTrendingOnly(e.target.checked)}
              className="h-4 w-4 rounded border-gray-300 text-blue-600 focus:ring-blue-500"
            />
            <span className="text-sm text-gray-700">Trending only</span>
          </label>
        </div>
      </div>

      {/* Sounds Grid */}
      {loading ? (
        <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
          {[1, 2, 3, 4, 5, 6].map((i) => (
            <div
              key={i}
              className="h-32 animate-pulse rounded-lg border border-gray-200 bg-gray-100"
            />
          ))}
        </div>
      ) : filteredSounds.length === 0 ? (
        <div className="rounded-lg border border-gray-200 bg-white p-12 text-center">
          <Music className="mx-auto h-12 w-12 text-gray-400" />
          <h3 className="mt-4 text-lg font-medium text-gray-900">
            No sounds found
          </h3>
          <p className="mt-2 text-gray-600">
            Try adjusting your filters or search query
          </p>
        </div>
      ) : (
        <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
          {filteredSounds.map((sound) => (
            <SoundCard
              key={sound.id}
              sound={sound}
              isPlaying={playingId === sound.id}
              isSelected={selectedSoundId === sound.id}
              onTogglePlay={() => togglePlay(sound.id)}
              onSelect={() => onSelectSound?.(sound)}
            />
          ))}
        </div>
      )}
    </div>
  );
}

interface SoundCardProps {
  sound: TrendingSound;
  isPlaying: boolean;
  isSelected: boolean;
  onTogglePlay: () => void;
  onSelect: () => void;
}

function SoundCard({
  sound,
  isPlaying,
  isSelected,
  onTogglePlay,
  onSelect,
}: SoundCardProps) {
  return (
    <div
      className={`group rounded-lg border p-4 transition-all ${
        isSelected
          ? "border-blue-500 bg-blue-50"
          : "border-gray-200 bg-white hover:shadow-md"
      }`}
    >
      {/* Header */}
      <div className="mb-3 flex items-start justify-between">
        <div className="flex-1">
          <h3 className="font-semibold text-gray-900">{sound.title}</h3>
          {sound.artist && (
            <p className="text-sm text-gray-600">{sound.artist}</p>
          )}
        </div>
        {sound.trending_score > 0 && (
          <div className="flex items-center space-x-1 rounded-full bg-orange-100 px-2 py-1 text-xs font-medium text-orange-700">
            <TrendingUp className="h-3 w-3" />
            <span>{sound.trending_score.toFixed(0)}</span>
          </div>
        )}
      </div>

      {/* Category & Tags */}
      <div className="mb-3 flex flex-wrap gap-2">
        {sound.category && (
          <span className="rounded-md bg-gray-100 px-2 py-1 text-xs text-gray-700">
            {sound.category}
          </span>
        )}
        {sound.tags.slice(0, 2).map((tag, index) => (
          <span
            key={index}
            className="rounded-md bg-blue-100 px-2 py-1 text-xs text-blue-700"
          >
            {tag}
          </span>
        ))}
      </div>

      {/* Stats */}
      <div className="mb-3 flex items-center space-x-4 text-sm text-gray-600">
        <div className="flex items-center space-x-1">
          <Music className="h-4 w-4" />
          <span>{sound.usage_count} uses</span>
        </div>
        {sound.duration_seconds && (
          <span>{Math.floor(sound.duration_seconds)}s</span>
        )}
      </div>

      {/* Actions */}
      <div className="flex space-x-2">
        <button
          type="button"
          onClick={onTogglePlay}
          className="flex items-center justify-center rounded-lg bg-gray-100 p-2 transition-colors hover:bg-gray-200"
          aria-label={isPlaying ? "Pause sound" : "Play sound"}
          title={isPlaying ? "Pause" : "Play"}
        >
          {isPlaying ? (
            <Pause className="h-5 w-5 text-gray-700" />
          ) : (
            <Play className="h-5 w-5 text-gray-700" />
          )}
        </button>
        <button
          type="button"
          onClick={onSelect}
          className={`flex-1 rounded-lg px-4 py-2 text-sm font-medium transition-colors ${
            isSelected
              ? "bg-blue-600 text-white"
              : "bg-blue-100 text-blue-700 hover:bg-blue-200"
          }`}
        >
          {isSelected ? "Selected" : "Select"}
        </button>
      </div>
    </div>
  );
}

