 */
function TestimonialCard({
  testimonial,
  index = 0,
}: {
  testimonial: Testimonial;
  index?: number;
}) {
  return (
    <motion.div
      className="p-6 rounded-xl bg-card border hover:border-primary/40 transition-colors h-full flex flex-col"
