            <div className="overflow-hidden">
              <motion.div
                className="flex"
                animate={{ x: `-${currentTestimonialIndex * 100}%` }}
                transition={{ type: "spring", stiffness: 300, damping: 30 }}
              >
                {displayTestimonials.map((testimonial, index) => (
                  <div key={testimonial.id} className="w-full flex-shrink-0 px-2">
                    <TestimonialCard testimonial={testimonial} index={index} />
                  </div>
                ))}
              </motion.div>
            </div>

            {/* Carousel Controls */}
            <div className="flex items-center justify-center gap-4 mt-6">
              <button
                onClick={prevTestimonial}
                className="p-2 rounded-full bg-card border hover:bg-muted transition-colors focus:outline-none focus-visible:ring-2 focus-visible:ring-primary focus-visible:ring-offset-2"
                aria-label="Previous testimonial"
              >
                <ChevronLeft className="w-5 h-5" />
              </button>

              {/* Dots Indicator */}
              <div className="flex gap-2">
                {displayTestimonials.map((_, index) => (
                  <button
                    key={index}
                    onClick={() => setCurrentTestimonialIndex(index)}
                    className={cn(
                      "w-2 h-2 rounded-full transition-all focus:outline-none focus-visible:ring-2 focus-visible:ring-primary focus-visible:ring-offset-2",
                      index === currentTestimonialIndex
                        ? "bg-primary w-6"
                        : "bg-muted-foreground/30"
                    )}
                    aria-label={`Go to testimonial ${index + 1}`}
                    aria-current={index === currentTestimonialIndex ? "true" : undefined}
                  />
                ))}
              </div>

              <button
                onClick={nextTestimonial}
                className="p-2 rounded-full bg-card border hover:bg-muted transition-colors focus:outline-none focus-visible:ring-2 focus-visible:ring-primary focus-visible:ring-offset-2"
                aria-label="Next testimonial"
              >
                <ChevronRight className="w-5 h-5" />
              </button>
            </div>
          </div>
        </div>

        {/* Payment Methods & Security Badges (Requirement 6.6) */}
        <motion.div
          className="flex flex-col items-center justify-center gap-6 pt-12 border-t"
          initial={{ opacity: 0 }}
          whileInView={{ opacity: 1 }}
          viewport={{ once: true }}
        >
          <p className="text-sm text-muted-foreground">Secure payments powered by</p>
          <div className="flex items-center gap-8 flex-wrap justify-center">
            <div className="flex items-center gap-2 px-4 py-2 rounded-lg bg-card border">
              <Lock className="w-5 h-5 text-primary" />
              <span className="font-semibold">Paystack</span>
            </div>
            <div className="flex items-center gap-2 px-4 py-2 rounded-lg bg-card border">
              <Shield className="w-5 h-5 text-primary" />
              <span className="font-semibold">256-bit SSL</span>
            </div>
            <div className="flex items-center gap-2 px-4 py-2 rounded-lg bg-card border">
              <CheckCircle className="w-5 h-5 text-primary" />
              <span className="font-semibold">PCI Compliant</span>
            </div>
          </div>
        </motion.div>
      </div>
    </section>
  );
}

"use client";

import { useState, useEffect, useRef } from "react";
import { getOptimizedImageUrl } from "@/lib/cdn/optimization";

/**
 * Lazy-loaded image component with Intersection Observer
 * Requirements: Performance optimization
 */

interface LazyImageProps {
  src: string;
  alt: string;
  width?: number;
  height?: number;
  className?: string;
  placeholder?: string;
  onLoad?: () => void;
  priority?: boolean;
}

export function LazyImage({
  src,
  alt,
  width,
  height,
  className = "",
  placeholder = "data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 400 300'%3E%3Crect fill='%23f0f0f0' width='400' height='300'/%3E%3C/svg%3E",
  onLoad,
  priority = false,
}: LazyImageProps) {
  const [isLoaded, setIsLoaded] = useState(false);
  const [isInView, setIsInView] = useState(priority);
  const imgRef = useRef<HTMLImageElement>(null);

  useEffect(() => {
    if (priority) return;

    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            setIsInView(true);
            observer.disconnect();
          }
        });
      },
      {
        rootMargin: "50px",
        threshold: 0.01,
      },
    );

    if (imgRef.current) {
      observer.observe(imgRef.current);
    }

    return () => {
      observer.disconnect();
    };
  }, [priority]);

  const handleLoad = () => {
    setIsLoaded(true);
    onLoad?.();
  };

  // Get optimized image URL
  const optimizedSrc = getOptimizedImageUrl(src, {
    width,
    height,
    quality: "auto",
    format: "auto",
  });

  return (
    <img
      ref={imgRef}
      src={isInView ? optimizedSrc : placeholder}
      alt={alt}
      width={width}
      height={height}
      className={`${className} ${isLoaded ? "opacity-100" : "opacity-0"} transition-opacity duration-300`}
      onLoad={handleLoad}
      loading={priority ? "eager" : "lazy"}
    />
  );
}

