"use client";

import { useEffect, useState } from "react";
import { toast } from "sonner";
import {
  openDB,
  queueOfflineAction,
  getQueuedActions,
  removeQueuedAction,
  clearQueuedActions,
} from "@/lib/utils/offline-storage";

interface OfflineQueueItem {
  id?: number;
  url: string;
  method: string;
  headers: Record<string, string>;
  body: string;
  timestamp: number;
}

export function useOffline() {
  const [isOnline, setIsOnline] = useState(true);
  const [queuedActions, setQueuedActions] = useState<OfflineQueueItem[]>([]);

  useEffect(() => {
    // Set initial online status
    setIsOnline(navigator.onLine);

    // Listen for online/offline events
    const handleOnline = () => {
      setIsOnline(true);
      toast.success("Back online! Syncing queued actions...");
      syncOfflineQueue();
    };

    const handleOffline = () => {
      setIsOnline(false);
      toast.warning("You're offline. Actions will be queued for sync.");
    };

    window.addEventListener("online", handleOnline);
    window.addEventListener("offline", handleOffline);

    // Listen for service worker messages
    if ("serviceWorker" in navigator) {
      navigator.serviceWorker.addEventListener("message", handleSWMessage);
    }

    // Load queued actions on mount
    loadQueuedActions();

    return () => {
      window.removeEventListener("online", handleOnline);
      window.removeEventListener("offline", handleOffline);
      if ("serviceWorker" in navigator) {
        navigator.serviceWorker.removeEventListener("message", handleSWMessage);
      }
    };
  }, []);

  const handleSWMessage = (event: MessageEvent) => {
    if (event.data && event.data.type === "SYNC_SUCCESS") {
      toast.success("Synced offline action successfully");
      loadQueuedActions();
    }
  };

  const loadQueuedActions = async () => {
    try {
      const actions = await getQueuedActions();
      setQueuedActions(actions);
    } catch (error) {
      console.error("Failed to load queued actions:", error);
    }
  };

  const syncOfflineQueue = async () => {
    // Check if background sync is available
    const hasBackgroundSync =
      typeof window !== "undefined" &&
      "serviceWorker" in navigator &&
      typeof navigator.serviceWorker.ready !== "undefined";

    if (hasBackgroundSync) {
      try {
        const registration = await navigator.serviceWorker.ready;
        // Check if sync is available on the registration
        if ("sync" in registration) {
          await registration.sync.register("sync-offline-queue");
          return;
        }
      } catch (error) {
        console.error("Background sync registration failed:", error);
      }
    }

    // Fallback: manually sync
    await manualSync();
  };

  const manualSync = async () => {
    try {
      const requests = await getQueuedActions();

      for (const requestData of requests) {
        try {
          const response = await fetch(requestData.url, {
            method: requestData.method,
            headers: requestData.headers,
            body: requestData.body,
          });

          if (response.ok && requestData.id) {
            // Remove from queue
            await removeQueuedAction(requestData.id);
            toast.success("Synced offline action");
          }
        } catch (error) {
          console.error("Failed to sync request:", error);
        }
      }

      await loadQueuedActions();
    } catch (error) {
      console.error("Manual sync failed:", error);
    }
  };

  const queueAction = async (
    url: string,
    method: string,
    body?: any,
    headers?: Record<string, string>,
  ) => {
    try {
      await queueOfflineAction(
        url,
        method,
        headers || { "Content-Type": "application/json" },
        JSON.stringify(body),
      );
      await loadQueuedActions();
      toast.info("Action queued for sync when online");
    } catch (error) {
      console.error("Failed to queue action:", error);
      toast.error("Failed to queue action");
    }
  };

  const clearQueue = async () => {
    try {
      await clearQueuedActions();
      setQueuedActions([]);
      toast.success("Offline queue cleared");
    } catch (error) {
      console.error("Failed to clear queue:", error);
    }
  };

  return {
    isOnline,
    queuedActions,
    queueAction,
    syncOfflineQueue,
    clearQueue,
  };
}

"use client";

import { useEffect, useRef } from "react";
import { toast } from "sonner";

/**
 * Hook to ensure data changes persist immediately
 * Provides optimistic updates with automatic retry on failure
 */
export function usePersistentData<T>(
  data: T,
  saveFn: (data: T) => Promise<void>,
  options: {
    debounceMs?: number;
    onSuccess?: () => void;
    onError?: (error: Error) => void;
    retryAttempts?: number;
  } = {},
) {
  const { debounceMs = 500, onSuccess, onError, retryAttempts = 3 } = options;

  const timeoutRef = useRef<NodeJS.Timeout>();
  const retryCountRef = useRef(0);
  const lastDataRef = useRef<T>(data);

  useEffect(() => {
    // Skip if data hasn't changed
    if (JSON.stringify(data) === JSON.stringify(lastDataRef.current)) {
      return;
    }

    lastDataRef.current = data;

    // Clear existing timeout
    if (timeoutRef.current) {
      clearTimeout(timeoutRef.current);
    }

    // Debounce the save operation
    timeoutRef.current = setTimeout(async () => {
      await persistData(data);
    }, debounceMs);

    return () => {
      if (timeoutRef.current) {
        clearTimeout(timeoutRef.current);
      }
    };
  }, [data, debounceMs]);

  const persistData = async (dataToSave: T) => {
    try {
      await saveFn(dataToSave);
      retryCountRef.current = 0;
      onSuccess?.();
    } catch (error) {
      console.error("Failed to persist data:", error);

      // Retry logic
      if (retryCountRef.current < retryAttempts) {
        retryCountRef.current++;
        toast.warning(
          `Retrying save (${retryCountRef.current}/${retryAttempts})...`,
        );

        // Exponential backoff
        const delay = Math.pow(2, retryCountRef.current) * 1000;
        setTimeout(() => persistData(dataToSave), delay);
      } else {
        retryCountRef.current = 0;
        onError?.(error as Error);
        toast.error("Failed to save changes. Please try again.");
      }
    }
  };

  return {
    persist: () => persistData(data),
  };
}

/**
 * Hook for immediate persistence without debouncing
 * Use for critical data that must be saved immediately
 */
export function useImmediatePersist<T>(
  saveFn: (data: T) => Promise<void>,
  options: {
    onSuccess?: () => void;
    onError?: (error: Error) => void;
  } = {},
) {
  const { onSuccess, onError } = options;

  const persist = async (data: T) => {
    try {
      await saveFn(data);
      onSuccess?.();
    } catch (error) {
      console.error("Failed to persist data immediately:", error);
      onError?.(error as Error);
      toast.error("Failed to save changes");
      throw error;
    }
  };

  return { persist };
}

/**
 * Hook for batch persistence
 * Collects multiple changes and persists them together
 */
export function useBatchPersist<T>(
  saveFn: (items: T[]) => Promise<void>,
  options: {
    batchSize?: number;
    flushIntervalMs?: number;
    onSuccess?: (count: number) => void;
    onError?: (error: Error) => void;
  } = {},
) {
  const {
    batchSize = 10,
    flushIntervalMs = 5000,
    onSuccess,
    onError,
  } = options;

  const batchRef = useRef<T[]>([]);
  const intervalRef = useRef<NodeJS.Timeout>();

  useEffect(() => {
    // Set up periodic flush
    intervalRef.current = setInterval(() => {
      if (batchRef.current.length > 0) {
        flush();
      }
    }, flushIntervalMs);

    return () => {
      if (intervalRef.current) {
        clearInterval(intervalRef.current);
      }
      // Flush remaining items on unmount
      if (batchRef.current.length > 0) {
        flush();
      }
    };
  }, []);

  const add = (item: T) => {
    batchRef.current.push(item);

    // Auto-flush if batch size reached
    if (batchRef.current.length >= batchSize) {
      flush();
    }
  };

  const flush = async () => {
    if (batchRef.current.length === 0) return;

    const itemsToSave = [...batchRef.current];
    batchRef.current = [];

    try {
      await saveFn(itemsToSave);
      onSuccess?.(itemsToSave.length);
    } catch (error) {
      console.error("Failed to persist batch:", error);
      onError?.(error as Error);
      // Re-add failed items to batch for retry
      batchRef.current.unshift(...itemsToSave);
    }
  };

  return { add, flush };
}

/**
 * Hook for using session manager
 * Provides utilities for session state management
 */

import { useEffect, useCallback } from "react";
import { useAuthStore } from "@/store/auth";
import { sessionManager, SessionState } from "@/lib/utils/session-manager";
import { usePathname } from "next/navigation";

export function useSessionManager() {
  const { user } = useAuthStore();
  const pathname = usePathname();

  /**
   * Save current route when it changes
   */
  useEffect(() => {
    if (user?.id && pathname) {
      sessionManager.saveCurrentRoute(user.id, pathname);
    }
  }, [user?.id, pathname]);

  /**
   * Restore session on mount
   */
  useEffect(() => {
    if (user?.id) {
      restoreSession();
    }
  }, [user?.id]);

  /**
   * Restore complete session
   */
  const restoreSession = useCallback(async (): Promise<SessionState | null> => {
    if (!user?.id) return null;
    return await sessionManager.restoreCompleteSession(user.id);
  }, [user?.id]);

  /**
   * Save scroll position
   */
  const saveScrollPosition = useCallback(
    async (route: string, position: number): Promise<void> => {
      if (!user?.id) return;
      await sessionManager.saveScrollPosition(user.id, route, position);
    },
    [user?.id],
  );

  /**
   * Get scroll position
   */
  const getScrollPosition = useCallback(
    async (route: string): Promise<number> => {
      if (!user?.id) return 0;
      return await sessionManager.getScrollPosition(user.id, route);
    },
    [user?.id],
  );

  /**
   * Save search query
   */
  const saveSearchQuery = useCallback(
    async (query: string): Promise<void> => {
      if (!user?.id) return;
      await sessionManager.saveSearchHistory(user.id, query);
    },
    [user?.id],
  );

  /**
   * Get search history
   */
  const getSearchHistory = useCallback(async (): Promise<string[]> => {
    if (!user?.id) return [];
    return await sessionManager.getSearchHistory(user.id);
  }, [user?.id]);

  /**
   * Save filter state
   */
  const saveFilterState = useCallback(
    async (filterKey: string, filterValue: any): Promise<void> => {
      if (!user?.id) return;
      await sessionManager.saveFilterState(user.id, filterKey, filterValue);
    },
    [user?.id],
  );

  /**
   * Get filter state
   */
  const getFilterState = useCallback(
    async (filterKey: string): Promise<any> => {
      if (!user?.id) return null;
      return await sessionManager.getFilterState(user.id, filterKey);
    },
    [user?.id],
  );

  /**
   * Get last active route
   */
  const getLastActiveRoute = useCallback(async (): Promise<string | null> => {
    if (!user?.id) return null;
    return await sessionManager.getLastActiveRoute(user.id);
  }, [user?.id]);

  /**
   * Clear session
   */
  const clearSession = useCallback(async (): Promise<void> => {
    if (!user?.id) return;
    await sessionManager.clearSession(user.id);
  }, [user?.id]);

  return {
    restoreSession,
    saveScrollPosition,
    getScrollPosition,
    saveSearchQuery,
    getSearchHistory,
    saveFilterState,
    getFilterState,
    getLastActiveRoute,
    clearSession,
  };
}
